1. 적용범위 책임(●) / 협조(→/←) 절 차 문서(●) / 기록(→/←)
이 규정은 회사의 중장기 및 연도별 경영계획의 수립과 운영에 대하여 적용한다.
2. 목적 (●) 각 사업부장 사업부별 계획 작성 (→) 사업계획서 초안
중장기 경영계획 수립과 이의 효율적인 운영을 통해 회사의 지속적인 성장으로 경영목표 달성을
그 목적으로 한다. ↓
(●) 공장장 (→) 각 사업부장 검토 및 조정 (→) 사업계획서 조정안', 0
WHERE NOT EXISTS (SELECT 1 FROM regulation_sections WHERE reg_code = 'A-2100' AND sort_order = 0);
