의미하며, 사업계획은 전사목표 달성을 위한 부문별 계획을 의미한다. (●) 대표이사 (←) 경영관리실 대표이사 승인 (→) 사업계획서 확정안', 1
WHERE NOT EXISTS (SELECT 1 FROM regulation_sections WHERE reg_code = 'A-2100' AND sort_order = 1);
INSERT INTO regulation_sections (reg_code, section_title, section_body, sort_order)
SELECT 'A-2100', '4. 계획기간 ↓', '(1) 중장기 경영계획은 3~5년 계획으로 수립한다. (●) 각 사업부장 사업계획 추진 (→)해당 추진 실적
(2) 연도별 경영계획은 1년 계획으로 수립한다.
5. 경영계획 운영절차 (●) 각 사업부장 실적 관리 (→) 업무실적 보고서
경영계획 운영의 주관팀은 경영관리실이 되며, 그 절차는 다음과 같다.
책임(●) / 협조(→/←) 절 차 문서(●) / 기록(→/←) (●) 각 사업부장 사업계획 수정 (→) 사업계획서 수정안
(●) 대표이사 (←) 경영관리실 경영방침 및 목표 설정 (→) 경영방침 및 목표
(●) 경영관리실 방향 설정 및 통보 (→)사업계획 작성 지침
