사업계획 운영 규정 개 정 번 호 5
페 이 지 3/4
6. 경영계획수립 진행방법 (10) 협력업체 평가 및 지도 계획
6.1 경영목표 및 방침 설정 (11) 리스크 및 기회를 다루기 위하여 취해진 조치의 효과성
경영관리실은 경영층의 의견을 수렴하여 목표년도에 실현되어야 할 회사의 이미지, 사업 (12) 저 품질비용(내부 및 외부 부적합 비용)
구조, 기술, 인적자원, 세계화 등에 대한 비젼을 설정하고 비젼 실현을 위한 경영목표 (13) 프로세스 효과성,효율성의 측정치
및 경영방침을 수립하여 대표이사의 승인을 득한다. (14) 제품 적합성
(15) 새로운 시설 또는 새로운 제품에 대해 그리고 기존 운용(오퍼레이션)에 대한 변경에 대해
6.2 방향설정 수행된 제조 타당성 확인의 평가
경영관리실은 확정된 회사 경영방침, 경영목표와 내,외부 이슈와 이해관계자의 요구사항을 (16) 고객 만족
고려한 경영계획 수립 방향 및 계획수립 일정 등을 작성하여 대표이사의 승인을 득하여 각 (17) 보전 목표 대비 성과 검토
사업부에 통보한다. (18) 보증 성과(해당되는 경우)
(19) 고객 점수표 검토(해당되는 경우)
6.3 사업부별 계획 작성 (20) 리스크 분석을 통해 파악된 잠재적 고장형태의 파악(FMEA)
6.3.1 각 사업부는 통보된 경영계획 수립 방향, 계획수립 일정 및 내,외부 이슈와 이해관계자의 (21) 실제 필드 고장 및 안전 또는 환경에대한 그들의 영향
요구사항을 고려하여 사업부별/팀별 SWOT분석을 실시하고, 각 실행 전략별 리스크를 6.3.3 개발, 품질등 관련팀은 경쟁사 또는 동종업계와 자사수준을 비교, 분석한 자료와
도출하고 『 리스크 관리 규정 』의 절차에 따라 리스크를 분석하여 리스크 분석 결과를 품질지수, 생산성지수 등을 벤치마킹한 결과를 토대로 구체적인 계획을 작성해야
토대로 "사업 계획서"를 작성한 후 해당 대표이사의 결재를 득하고 경영관리실로 통보한다. 하며, 타팀의 협조가 필요한 부분에 대해서는 해당 사업부장에 통보하여 협조를 얻는다.
6.3.2 각 사업부/팀은 계획수립시 다음과 같은 사항을 참조하여 계획에 따른 실적평가가 6.3.4 사업부장은 팀별 계획을 검토하여 회사의 경영목표 및 경영방침과 부합하지 않거나
가능하도록 목표치를 정형화, 계수화될 수 있도록 작성하여야 한다. 실현가능성이 희박한 계획을 해당팀과 협의하여 조정한다.
(1) 차기 년도 매출계획(내수, 수출 등) 6.3.5 사업부장은 검토, 조정된 팀별 계획을 종합하여 경영계획서 초안을 작성하여 이를
(2) 당해 년도 투자 실적 분석 및 차기 년도 투자 계획 대표이사에게 보고한다.
(3) 품질 및 생산성 향상 계획 6.3.6 사업부장은 대표이사의 승인을 득한후 목표년도 계획으로 확정하고 이를 각 경영관리실에
(4) 인원 운영 계획 통보한다.
(5) 고객 만족도 계획(Claim율, 납기 준수율)
(6) 개발 계획 7. 실적관리
(7) 설비 정기 점검 계획 7.1 월별실적관리
(8) 종업원 교육 훈련 계획 월별실적은 매월 월업무계획/실적서로 대표이사에게 보고하고, 계획 미달사항 및 문제점은
(9) 내부품질 감사 계획 차월 계획에 반영토록 한다.
