7.2 반기, 년 실적관리 (3) 리스크 관리 규정(A-8100)
(1) 각 사업부장은 반기별로 추진된 업무실적에 대하여 내부평가 실시 그 결과를 대표이사의
승인 후 경영관리 실장에게 회람하여야 한다. 11. 관련양식
(2) 각 사업부장은 내부평가에 대한 대표이사 지시사항과 분석결과를 정리하여 해당팀에 통보 (1) 사업 계획서(A2100-01) - 각 사업부 별도 양식
한다. (2) 사업 실적 보고서(A2100-02) - 각 사업부 별도 양식
(3) 중장기 경영계획의 실적관리는 매년 결산자료 및 팀별 업무실적을 토대로 중장기 경영계획의 (3) 내외부 이슈 사항(A2100-03)
진척, 실적사항을 년단위로 분석하여 평가한다. (4) 이해관계자 요구사항(A2100-04)
(4) 실적평가 결과 경영환경의 급속한 변화등의 특별한 사유없이 계획과 대비하여 "20%"이상 (5) SWOT 분석표(A2100-05)
차이가 있을 경우 각 사업부장은 해당팀에 시정조치를 요구할 수 있다.', 2
WHERE NOT EXISTS (SELECT 1 FROM regulation_sections WHERE reg_code = 'A-2100' AND sort_order = 2);
INSERT INTO regulation_sections (reg_code, section_title, section_body, sort_order)
SELECT 'A-2100', '8. 경영계획 수정', '(1) 경영계획의 수정이란 관리항목, 목표치 및 방식의 변경, 추가, 폐기, 주요추진업무의 변경등을
말한다.
(2) 경영계획의 수정은 대표이사의 지시에 의하거나 급격한 경영환경 변화등의 사유로 경영계획
수정이 불가피한 경우, 각 사업부장은 계획 수정에 대한 배경 및 내용등을 정리하여 경영대리인
의 심의를 거친 후 대표이사의 승인을 득하여 확정하고 전팀에 이를 통보한다.
(3) 수정 경영계획서 작성 절차는 5항 "경영계획 운영절차"와 같다.', 3
WHERE NOT EXISTS (SELECT 1 FROM regulation_sections WHERE reg_code = 'A-2100' AND sort_order = 3);
