SELECT 'A-2200', '7. 관련양식', '4.6 검토회의 (1) 회의록 (A2200-01)
4.6.1 총무팀장은 팀별 보고/검토한 내용에 대해 경영검토 보고서를 작성하고 참석자의 확인 및 (2) ( )년 경영검토 계획서 (A2200-02)
대표이사 승인 후 보고서를 관련팀에 배포한다. 보고서 작성 요령은 다음과 같다. (3) ( )년 경영검토 보고서 (A2200-03)
가. 전회 결정/지시사항 결과 보고
나. 금회 검토,결정/지시사항
- 개선의 기회
- 시스템 변경의 필요성(품질,환경, 안전 및 보건 등)
- 자원의 필요성
4.7 시정/개선조치
(1) 관련팀장은 검토한 내용중 기대효과, 해결가능성, 시급성, 중요도등을 고려하여 자체
일정계획을 수립 및 추진하거나 관련팀의 협조를 받아 TFT를 구성하여 추진한다.
(2) 관련팀장은 시정조치 또는 개선사항에 대한 조치 결과를 관리팀장에게 통보한다.
(3) 총무팀장은 조치결과를 확인하고 관련표준의 제/개정이 필요한 경우 해당팀을 지명하여
제/개정될 수있도록 한다.
(4) 총무팀장은 차기 경영검토 회의시 조치결과에 대해 대표이사에게 보고한다.', 4
