4.3 MDT장
3. 용어의 정의 MDT장은 개발단계별 회의를 주관하여, 회의 결과에 따른 진행 상태를 확인하고, 점검
결과에 따른 조치를 한다.
3.1 업무회의
각 팀장 주관하에 부서내 부서원들이 참석하여 업무 수행 진행상태 및 결과, 실무 진행상의 5. 업무 절차
애로사항 교환 및 해소를 위한 회의이다.
책임(●) / 협조(→/←) 절 차 문서(●) / 기록(→/←)
3.2 사업부장 회의
각 사업부장급들이 참석하여 주요 의사결정 및 현안문제에 대한 조치 및 대책을 수립하는
회의를 말하며, 사업보고회 / 팀장 회의 / 임시회의가 있다. (●) 주관 사업부장 개최 통보 (→) 협조전,공고,전자메일
3.3 MDT(Multi-DisciplInery Team)회의 ↓
신규 또는 변경 제품의 생산을 준비하기 위한 사전 제품 품질계획을 수립하고 실시하기 위한 (●) 주관 사업부장 회의 준비 (→) 부표 1에 따른 준비물
회의로 MDT장이 개발단계에 따라 주관하는 회의를 말한다.
3.4 임시회의 (●) 주관 사업부장 회의 실시 (→) 회의록
현안이 발생될 때마다 그 현안을 해결하기 위한 회의로 각 팀장이 참석하는 회의를 말한다.
(●) 주관 사업부장 회의결과 보고 (→) 회의록', 2
WHERE NOT EXISTS (SELECT 1 FROM regulation_sections WHERE reg_code = 'A-3100' AND sort_order = 2);
