재,개정 일자 45047
회의 운영 규정 개 정 번 호 5
페 이 지 3/3
책임(●) / 협조(→/←) 절 차 문서(●) / 기록(→/←) 6.5 회의결과 보고
6.5.1 주관팀장은 회의결과를 공장장과 대표이사에게 보고한다.
↓ 6.5.2 해당되는 경우, 주관팀장은 회의결과에 따른 시정/예방조치가 되도록 관리한다.
(●) 주관 사업부장 결과 통보 (→) 회의록
6.6 결과통보
주관팀장은 회의록 사본을 회의구성원에게 배포하고, 필요할 경우 회의결과를 회람,
6.2 개최통보 공고,게시한다.
6.2.1 회사차원에서 실시되는 회의는 주관팀에서 실시 일정을 공장장과 협의하여 설정하고
각 팀에 협조전으로 통보 또는 공고, 게시 및 전자메일 송부하여 통보한다. 7. 관련표준
6.2.2 필요한 경우, 주관 팀장은 회의실시에 관한 사항을 보고하여 공장장 또는 대표이사의 (1) 개발업무 규정(J-1100)
승인을 득하여 통보한다. (2) 사업계획 운영 규정(A-2100)
6.3 회의준비 8. 관련양식
6.3.1 주관사업부 회의 실시형태에 따른 여건을 사전에 준비한다. (1) 회의록 (A2200-01)
6.3.2 회의 구성원은 통보된 주제에 대한 관련 준비서류를 정비하여 회의를 준비한다.
6.4 회의실시
6.4.1 주관 사업부장이 회의를 운영하며, 회의는 브리핑, 질의 응답순으로 진행한다.
6.4.2 주관 사업부징은 회의종료전 협의되었던 결과를 회의구성원에게 설명하여 이의여부를
확인한다.
6.4.3 이의가 있는 경우 재협의 하여 명확하게 회의결과를 정리한다.
6.4.4 주관사업부 해당팀장은 회의시 토론되었던 중요내용과 결정사항을 회의록에 기재하여
참석자의 확인을 받는다.
6.4.5 회의시간은 사전 통보된 시간을 준수하도록 한다.', 3
