구 분 기준 및 방법 책임부서 6. 부서별 의사소통 내용, 주기 및 방법
의사소통 내용 전달/의견 수렴 수단 구 분 의 사 소 통 내 용 의사소통 방법 주 기 담 당
2.외부의사소통 2) 결정사항은 환경비상사태관리/기록관리 절차에 따라 관리 경영관리실 내부 의사 소통 품질 방침 교육 / 게시 년간 품질팀
3) 외부 비상연락망 비치(관할관청 등) 품질 목표 및 세부 목표 회의 / 회람 년간 품질팀
4) 환경관련 비상사태/환경 위해성 문제에 대해서는 품질 목표 대비 실적 회의 / 회람 년간 품질팀
상황정도에 따라 인근주민, 인근기업, 관할관청 등에 품질/환경/안전보건 주요 부적합 사항 교육 / 게시 분기 주관팀
협조 요청하여 조치 내.외부 이슈사항 및 리스크 평가결과 교육 / 회의 년간 품질팀
3.고객의사소통 (CSR포함) - 고객 요구사항 - 고객관련 프로세스 절차 참조 영업팀 환경측면 파악 및 위험성 평가결과 회의 / 회람 년간 경영관리실
- 고객 불만사항 예) 계약검토, 고객불만처리, 품질보증팀 환경/안전관련 법규 요구사항 교육 / 회람 년간 경영관리실
- 고객 만족도 고객만족도 평가 절차 영업팀 내부심사, 2자심사, 3자심사 결과 회의 / 회람 년간 품질팀
4.의사소통 결정방법 - 의사소통 내용,시기 - 고객관련 프로세스 절차참조 영업팀 경영검토 결과 회의 년간 품질팀
- 의사소통 대상, 방법 예) 계약검토, 고객불만처리, 품질보증팀 고객불만사항 게시 월간 품질팀
- 의사소통 담당자 고객만족도 평가 절차 영업팀 고객만족도 조사결과 회의 / 회람 년간 영업팀
제품품질현황 회의 / 게시 수시 품질팀
4.2 CSR(Customer Specific Requirements, 고객 지정요구사항) 프로세스 성과 회의 / 게시 년간 품질팀
(1) CSR 파악 방법 외부 의사 소통 품질/환경/안전보건 방침 게시 수시 품질&경영
가.누 가 : 각 부서별 담당자 환경/안전 관련 민원 문서 수시 경영관리실
나.언 제 : 업무 시작시 (08시30분 이전) / 업무 종료시 (17시30분 이전) 품질/환경/안전보건 성과 문서 필요시 품질&경영
다.방 법 : 각 고객사 홈페이지 정부시책 문서 수시 경영관리실
(2) CSR 공유 관공서 행정사항 문서 수시 경영관리실
가.각 부서별 담당자는 접수 내용에 대하여 팀장 또는 사업부장에게ㅐ 보고하여야 한다 기타 환경/안전보건 관련 사항 문서 수시 경영관리실
나.팀장 및 사업부장은 접수 내용에 대하여 검토 후 필요시 경영진에 보고하여야 한다.
다.팀장 및 사업부장은 전결 또는 경영진 승인 내용에 대하여 관련 부서에 회람을 하여야 한다. 7. 관련양식
(회람 방법 : 출력물-회람싸인 받을것 / 사내 전산망 - 비즈메카) (1) 이해관계자 불만 조치대장(A3200-01)
(3) CSR 반영 (2) 이해관계자 불만 조치일지(A3200-02)
가.각 부서별 담당자는 필요시 품질경영팀 공유, 사내 시스템에 적용하여야 한다.', 4
