SELECT 'A-4100', '3. 용어의 정의 3.4 양식', '3.1 회사표준 업무의 정확성과 신속성을 도모할 목적으로, 서식을 사전에 지정하여 제공하는 것으로서
회사표준이라 함은 경영 및 제반관리 시스템의 운영에 관한 기준을 정한 문서이다. 업무결과가 기록되기 이전의 것을 말한다.
이는 매뉴얼, 프로세스, 규정, 지침으로 대별된다.
(1) 매뉴얼 4. 관리절차
회사 시스템 전반에 대하여 품질,환경,안전 등의 요건과 고객요구사항, 회사의 방침을 만족 4.1 회사표준관리
하고 있음을 충분히 보장하고 있음을 대외적으로 소개하기 위한 표준이다. 회사 회사표준관리의 주관팀은 품질관리팀이 되며, 표준 제/개정 절차는 다음과 같다.
(2) 프로세스(Process) 단, 기술표준은 해당 표준관리 절차에 따른다.
프로세스는 매뉴얼에 규정된 요구사항을 이행하기 위한 활동업무 단위의 관리를 위하여 입력
과 출력, 그리고 얻고자 하는 성과지표를 효과적이고 효율적인 달성을 위해 문서화된 표준이다 책임(●) / 협조(→/←) 절 차 문서(●) / 기록(→/←)
(2) 규정
조직의 사업영위를 위하여 필수적인 업무의 처리, 운영의 원칙 및 주요활동 범위를 ↓
정하고, 개별업무의 구체단계, 절차 및 관련 기준을 분명히 하기 위한 표준이다. (●) 해당 사업부 표준 필요설 판단
(3) 지침
규정에 지정된 업무를 효율적으로 수행하기 위하여 구체적으로 세부 절차를 기술한 ↓
표준이다. (●) 해당 사업부 담당자 초안 작성 (←) 타 표준, 작성 지침 (→) 표준 초안
