책임(●) / 협조(→/←) 절 차 문서(●) / 기록(→/←) 5. 회사표준관리 절차
5.1 표준의 제정, 개정 및 폐기 시기
(1) 조직의 개편이나 업무내용이 변경된 경우
(●) 해당 사업부장 양식 제/개정 필요성 판단 (←) 해당 관련표준/기존양식 (2) 새로운 업무의 발생, 신제품의 개발이 된 경우
(3) 제품의 도태, 기존업무의 소멸이 된 경우
↓ (4) 현 표준의 보완이 요구될 때
(●) 해당 사업부장 필요 양식 초안 작성 (→) 양식초안 (5) 기타 표준의 제/개정이나 폐기가 필요할 때
↓ 5.2 제정
(●) 해당 사업부장 표준 대비 완전성 검토 5.2.1 작성
(1) 표준작성의 책임과 권한은 해당표준 관련 업무를 주관하는 등록주관팀에 있다.
↓ (2) 해당팀장은 제/개정의 사유가 있는 경우 표준작성 필요 여부를 판단하고 표준이
(●) 해당 사업부장 관련팀 검토(해당시) 필요한 경우 초안을 작성한다. 회사표준의 작성에 대한 세부 사항은 『관리표준
작성 지침』에 따르고, 기술표준은 해당 작성 지침에 따른다.
(3) 해당팀장은 작성된 초안을 검토한 후 회사표준의 표지에 제정 사유를 기재하여
(●) 해당 사업부장 (←)기술연구소 소장 주관팀에 원본 제출 (→) 양식 원본 등록주관팀에 송부한다.
5.1.2 검토 및 승인
(1) 등록주관팀은 제출된 초안에 대하여 완전성과 타당성을 검토하며, 관련팀장 회의를
(●) 기술연구소 소장 양식검토 및 등록 (→) 양식등록대장 소집하거나 회람시켜 심의한다.
단, 표준검토 팀은 표준내용의 시행에 직접 관련이 있는 모든 팀이 된다.
(2) 관련팀 검토중 이견이 발생한 경우에는 회의를 소집하여 이견을 해소한 후 해당
(●) 기술연구소 소장 (→) 관련 사업부장 양식배포 및 활용 (→) 양식등록대장 팀장에게 송부하여 재작성토록 한다.
(3) 작성팀장은 관련팀이 검토 완료한 초안에 대하여 승인권자의 승인을 득한다.
관련팀 검토중 이견 해소가 안된 경우에는 승인권자에게 보고하여 최종결론을
(●) 기술연구소 소장 사 후 관 리 내리도록 한다.
