5.8 표준의 취급 6.5 개정본 접수 및 등록
(1) 표준은 대외비로 관리한다. 자료 입수절차와 같은 방법으로 접수 및 등록하여 관리한다.
(2) 표준의 사외반출은 대표이사의 사전승인을 받아야 한다.
6.6 개정본 배포
6. 자료관리 세부절차 (1) 등록된 개정본은 필요팀에 배포하여야 하며 필요팀에서는 구본을 주관팀에
6.1 자료의 입수 반납하거나 자체 폐기한다.
(1) 품질관리팀장은 국가규격/국제규격등의 자료는 매년 1회 이상에 총람확인 또는 관련 (2) 책자상태의 규격인 경우, 사본을 접수한 팀은 해당사본을 홀더에 편철하고 해당
전문기관에 문의 등을 통하여 규격 제/개정 현황을 파악하고 필요한 규격을 입수한다. 자료명을 화일제목으로 하며, 해당규격(책자)의 목차 및 내용란에 “구본”의 식별
(2) 품질관리팀장은 고객규격은 고객의 규격관리담당에게 매년 1회이상 해당규격의 제/개정 표시를 한다.
여부를 확인하여 필요한 규격을 입수한다. (3) 주관팀에서는 구본을 보관하되 책자상태인 경우 표지에, 낱장인 경우 모든 PAGE 에
(3) 경영관리팀장은 회사 대관업무 수행에 필요한 법규는 해당 관공서를 통하여 해당법규의 붉은색으로 “구본”의 날인을 한다.
신규제정 및 일부 개정시 수시로 입수한다.', 3
