품질보증팀은 관련팀에 제정 또는 개정된 양식을 배포하여 사용토록 하고,
7.2 필요양식의 작성 및 검토 구 양식은 해당팀에서 폐기한다.
양식의 신규제정 또는 개/폐의 필요성이 있는 팀(이하 해당팀라 한다)는 필요한
양식 초안을 작성한 후 해당 회사표준을 확인하여 완전성 여부를 검토한다. 7.7 양식의 사후관리
[주]양식의 제정은 사용 빈도가 많거나 업무 수행상 주의를 요하는 경우에 실시한다. (1) 품질보증팀장은 양식등록대장과 등록된 양식을 보관,유지하여야 하며, 양식등록대장에는
관련표준명 및 양식의 개정현황을 알수 있도록 양식번호, 등록일, 개정번호 등이
7.3 관련팀 검토 나타나도록 한다.
신규제정 또는 개/폐하려는 양식이 타팀과 공용으로 사용하는 것인 경우 해당팀은 (2) 품질보증팀은 반기별로 양식사용 실태를 확인하고, 구양식을 사용하고 있거나 양식
관련팀의 검토를 받아야 한다. 관리를 하지 않는 팀에 시정조치 요구등 양식의 올바른 사용을 위한 조치를 취한다.
