SELECT 'A-4101', '1. 적용범위 5.2 문장의 끝', '본 지침은 회사표준의 작성 방법에 적용한다. 문장의 끝은 그 뜻에 따라 다음의 보기와 같이 쓴다.
뜻의 구분 문장 끝에 쓰는 용어
2. 목적 지시 또는 요구 ______한다. ____으로 한다.
회사표준 작성방법에 대한 기준을 정하여 표준의 통일성을 기하고, 쉽게 이해하며 실행 할 수 ______에 따른다. _____과(와) 같이 한다.
있도록 하기 위함이다. ___하여야 한다. _____하지 않는다.
예외를 인정하는 경우 원칙으로 ________ 한다.
3. 용어의 정의 _______을(를) 원칙으로 한다.
회사표준에 쓰이는 용어의 뜻은 아래와 같다. 장려 또는 권장 _______하는 것이 좋다.
(1) [본문]은 표준을 형성하는 문장, 그림 및 표를 총칭한다. 허 용 _______하여도 좋다.
(2) [부표]는 본문안에 넣으면 복잡하게 되므로 따로 설명한 것을 말한다.
(3) [주]는 본문, 비고 등의 일부에 주기 부호를 달고 따로 떼어내어 기재한 것을 말한다. 5.3 이상, 이하, 초과, 미만 등의 용법
(4) [보기]는 본문, 비고 등에 나타난 사항에 대하여 예시하는 것을 말한다. (1) 이상과 이하는 그앞에 표시한 것을 포함한다.
(2) 초과 및 미만은 그앞에 표시한 것을 포함하지 않는다.
4. 표준서의 크기 및 양식 (3) "및"은 나란히 쓰는 용어가 2개일때 그 사이에 넣어 쓰며, 3개 이상일 때에는 앞에
4.1 표준서의 크기 나온 용어 뒤에 쉼표로 끊고, 마지막 용어 앞에 넣어 쓴다.
표준서는 A4 규격(297×210mm)으로 한다. (4) 숫자는 아라비아 숫자의 사용을 원칙으로 한다.
편철은 A4 규격의 상철 또는 좌철을 기준으로 한다.', 1
