SELECT 'A-4101', '10. 표준서의 구성 및 배열', '7. 문장부호 10.1 표준번호, 명칭 및 조항 제목
문장부호는 구두점, 묶음표, 따옴표 및 연속부호로 한다. 표준에는 표준관리규정에서 정하는 바에 따라 표준번호, 개정번호, 페이지를 명시
7.1 구두점 하여야 하며, 그 내용이 규정하고 있는 대상을 정확히 표시하는 표준명칭을 붙인다.
구두점은 마침표( . ), 쉼표( , ), 가운뎃점( ∙ ), 쌍점( : )으로 하고 이들의 사용법은 다음과 또한, 본문 처음에는 적용범위에 관한 조항을 붙이고 조항에는 제목을 붙인다.
같다. 그리고 다음에 오는 첫째줄은 행을 바꿔 쓰도록 한다.
(1) 마침표는 문장의 끝에 쓴다.
(2) 쉼표는 말을 끊고 연속되는 것을 명시할때 쓴다. 10.2 타 표준의 인용
(3) 가운뎃점은 쉼표로 끊어서는 문장을 읽기 어색할때 쓴다. 다른 표준을 인용할 때에는 내용중에 묶음 표시 안에 표준명칭만을 쓰고 관련표준란에
명칭 및 표준번호를 표시한다.
