1. 적용범위 책임(●) / 협조(→/←) 절 차 문서(●) / 기록(→/←)
이 규정은 업무결과 발생되는 기술적, 법적 및 품질관련 주요증거 및 자료와 사용이
만료 된 문서원본(이하 “기록”이라 한다)의 관리에 적용한다. ↓
(●) 각 사업부장 편 철 및 보 관', 0
