안전하게 보존되도록 하는데 있다. (●) 각 사업부장 보존 필요성 확인 (→) 기록분류표', 1
WHERE NOT EXISTS (SELECT 1 FROM regulation_sections WHERE reg_code = 'A-4200' AND sort_order = 1);
