SELECT 'A-4200', '3. 관리절차 ↓', '기록관리의 주관팀은 관리팀이 되며 관리 절차는 다음과 같다. (●) 각 사업부장 (→) 경영관리실 보 존 (→) 보존기록목록표 (각 사업부)
책임(●) / 협조(→/←) 절 차 문서(●) / 기록(→/←) ↓
(●) 경영관리실 (→) 해당 사업부장 열 람
(●) 각 사업부장 기록 작성/접수 ↓
(●) 경영관리실 (→) 해당 사업부장 보존 연한 초과기록 통보 문서 점검 후 폐기 (→) 폐기기록 목록표 [각 사업부)
(●) 각 사업부장 보관 필요성 확인 ↓
(●) 해당 사업부장 폐 기 / 소 각
(●) 각 사업부장 해당화일 존재 여부확인 (←) 기록분류표
(●) 각 사업부장 신 규 등 록 (→) 기록분류표
