SELECT 'A-4200', '4. 기록의 분류 5.4 신규 화일준비 및 등록', '기록의 분류체계는 아래와 같다. 5.4.1 신규 기록으로 해당 홀더 또는 바인더가 없는 경우 신규화일을 준비하여 색인한후
그 안에 편철하며, 신규화일을 “기록 분류표”에 등재한다.
5.4.2 파일, 바인더의 표지기록 및 식별방법과 문서보관함의 식별방법은 부표 1에 따른다.
① : 대분류 - ( A-Z) : 표준관리규정의 대분류와 같음 5.4.3 보관형식 결정
② : 중분류 - 업무기능코드 (1) 각 팀은 분류된 문서에 대하여 보관, 열람 및 사용이 가장 적합한 방법으로 문서의
(0:공통, 1:총무, 2. 재무, 3:개발, 4:자재, 5:영업, 6:생산, 7:품질, 8:생기, 9:개발) 보관방법을 결정한다.
③④ : 소분류 - 일련번호(01 - 99) (2) 문서의 보관방법은 다음의 형식으로 하며, 특별히 지장이 없는한 이 방법을 택한다.
가. 바인더 : 연속적또는 관련내용을 연결하여 일괄적으로 볼수 있도록 관리하는 문서.', 3
WHERE NOT EXISTS (SELECT 1 FROM regulation_sections WHERE reg_code = 'A-4200' AND sort_order = 3);
INSERT INTO regulation_sections (reg_code, section_title, section_body, sort_order)
SELECT 'A-4200', '5. 세부절차 [예] 제품 개발관련 기록', '5.1 기록의 작성 나. 홀더 : 단위또는 개별적으로 관리하는 문서.
(1) 기록의 작성시에는 연필이나 수정액의 사용은 허용되지 않는다. [예] 관리팀 - 사업계획서, 생산팀 - 생산계획서
(2) 중요한 수정 및 보완은 작성자가 수정하여 원본승인자가 승인한다. 다만, 오자수정 등의 5.4.2 분류형식 결정
중요하지 않은 간단한 수정은 작성자가 할수 있다. (1) 문서를 바인더 또는 홀더에 편철할 때 문서의 특성에 따라 분류하는 방법을 결정한다.
(3) 수정된 내용은 적색으로 두줄을 긋고 수정내용을 기입하며, 수정자 또는 승인자가 서명 (2) 문서의 분류형식은 다음의 기준으로 한다.
또는 날인한다. 가. 고객별(업체별) 나. 프로젝트별
다. 품목별 라. 일자별 마. 기타
5.2 보관 필요성 확인
기록을 발행하였거나 접수한 경우 “기록 분류표”를 참조하여 보관필요성을 판단하며, 5.5 보관
보관이 불필요한 경우 즉시 폐기한다. (1) 기록의 보관은 서가나 캐비넷에 하며, 보안이 필요한 기록은 시건장치를 한다.
단, 통지성 문서나, 해당업무의 수행이 완료됨으로써 더이상의 법적/기술적 증거력이나 (2) 각 팀장은 매년 12월말까지 차기년도에 사용할 화일박스, 홀더 및 바인더 등을 준비한다.
참고 필요성이 소멸되는 경우 보관대상에서 제외한다.
5.6 보존필요성 확인
5.3 편철 (1) 각 팀장은 매년 1월말 이전에 전년도 기록을 마감하고 보존이 필요한 기록은 보존
각 업무담당(또는 기록담당)은 해당기록을 “기록분류표”에 따라 해당 홀더 또는 바인더에 기한별로 분리하고 수집한다.
편철한다. 편철은 좌철을 기준으로 하며, 기록의 특성에 따라서 상철을 선택할 수 있다. (주1) 업무가 미결되어 계속 추진이 필요한 사안은 당해년도 화일로 연계하여 사용한다.
