매년 변경 발생여부를 확인하고, 변경이 있었던 경우 구본을 분리하여 보관하고 (1) 기록보존 장소는 물리적 손상, 풍수해, 도난 등으로 부터 안전하여야 한다.
현행의 원본은 계속 유지한다. (2) 각 사업부장은 분기별로 기록보존상태를 점검하고 이상이 있는 경우 팀장에게 통보하여
(2) 각 팀장은 “기록분류표”에 의거 기록을 종류별, 고객별, 제품별, 기간별등으로 분류 신속한 복구조치가 되도록 한다.
하여 표지와 측면지를 붙이고 단단히 결속한다. (3) 당사 사원은 누구나 기록을 열람 또는 대출할수 있다.
(3) 기록의 보존년한의 설정은 보존년한 설정기준(부표2)에 따른다. 열람을 희망하는 경우 각 사업부장에게 승인 후 관리팀장에게 협조 요청한다.
(4) 기록의 보존년한 설정의 기준은 고객에 의해 달리 규정되지 않는한 부표 2의 기준에
따른다. 5.9 폐기
(1) 각사업부장은 매년초, 당해년도에 보존이 만료되는 기록을 조회하여“폐기기록목록표”
5.7 이관 및 등록 를 작성하고 기록발행 팀장에게 추가보존 필요성을 문의한다.
(1) 각 팀장은 3년 이상 보존이 필요한 기록을 관리팀에 이관한다. (2) 추가보존이 필요치 않은 기록에 대하여 관리팀장은 폐기 승인을 하며, 기록담당은
단, 업무수행상 참고가 필수적인 경우에는 이관하지 않을수 있다. 해당기록을 폐기한다.
(주) 이관을 위한 기록의 재분류는 차후 검색 및 활용이 용이하도록 선번별, 고객별 (주) 보안이 필요한 기록은 소각처리 한다.
또는 업무 기능별, 기간별등의 방법중 선택하여 시행한다. (3) 기록의 폐기가 끝난 이후 각사업부장은“보존기록목록표”를 갱신하고 폐기기록목록을
(2) 기록 재분류후에는 기록번호를 부여하며 해당기록의 전면 및 측면(해당시)에 표기 품질기록으로 유지한다.
한다. 기록번호 부여방법은 다음과 같다.
