부표 1 파일링 기준 1.2 파일의 색인표 및 문서파일 번호 : 해당문서의 파일번호를 기록한다', 4
WHERE NOT EXISTS (SELECT 1 FROM regulation_sections WHERE reg_code = 'A-4200' AND sort_order = 4);
INSERT INTO regulation_sections (reg_code, section_title, section_body, sort_order)
SELECT 'A-4200', '1. 홀더 및 파일상자', '1.1 파일의 표지 1.3 파일표지 기록
(1) 소속팀 : 소속팀을 기록한다.
(2) 문 서 : 문서의 제목을 기록한다. (문서의 발생년도 표시 : 예) ''04문서분류표)
(3) 작성년도 : 문서의 작성년도를 기록한다.
(4) 분류번호 : 문서파일의 분류번호를 기록한다.
(5) 작 성 자 : 작성자의 이름을 기재한다.
1.4 보존기록
(1) 보존년한에 해당하는 곳에 ○표 한다.
(2) 문서의 보존 만기일을 기재한다.
1.5 파일의 색상
팀마다 고유의 색상을 지정하여 사용할수 있으며, 색상의 한정에 따라 동일한 색상을 사용
할 수도 있다.
1.6 파일을 펼쳤을 때 : 파일의 좌측명을 문서목록표, 우측면은 해당문서를 철한다.
해당문서의 파일번호를 기록한다
