작성년도 작성년도
보 관
보 관 보 존
보 존
2.2 문서내용 색인
(1) 사용팀명을 기록한다.
1.8 BOX에 기재할 때는 반드시 "유성펜" 또는 "출력물 부착 방식"을 사용하여야 한다. (2) 분류기준표에 따른 파일번호를 기록한다.
(번짐방지 및 재활용시 편리목적) (3) 파일명을 기록한다.
(4) 작성년도월을 기록한다.(FILE 처음 작성된 년도)
1.9 운영도중 예상하지 못한 새로운 파일의 발생으로 문서보관상자가 증가하여 BOX 사이에 (5) 보관, 보존년한을 기록한다.
첨가하여야 할 경우 중분류NO 뒤에 숫자 1부터 이어간다.
