2.3 간지 및 식별표기 (1) 색인표 기록
바인더내 문서의 식별이 필요한 경우 구분마다 간지를 사용하여 구분하고 간지의 측면 가. 상단 : 부서명을 기록한다.
에 구분내용을 기록한다. 나. 하단 : 관리책임자를 기록한다.
(2) 칸번호 색인
2.4 바인더의 색상 보관함 내부에 칸별로 상단을 기준으로 "1", "2", "3" 순으로 식별표시 하며 보관함
특별히 분류할 필요가 있을 경우를 제외하고 "하늘색" 2공 또는 3공으로 통일한다. 이 여러 개 될경우 좌측배열 순으로 보관함 좌측상단에 "가", "나" 등으로 표시한다.
2.5 색인표의 크기 (3) 파일 BOX 배열
바인더의 측면(바인더를 꽂았을 때 보이는 면)에 크기별 표준이 되는 2가지의 색인표를 가. 대분류 코드순으로 배열한다.
각각의 바인더 크기에 맞춰 붙여 통일한다. 나. 일련번호 순으로 배열한다.
다. 좌에서 우로 배열한다.', 5
