SELECT 'A-5200', '3. 책임과 권한', '3.1 품질보증팀장 ↓
품질보증팀장은 주기적인 제조공정 및 완성품 심사를 실시하여 사전문제점 예방 및 (●) 품질보증팀장 심사 수행 (→) 제조공정 심사 체크시트 (→) 제품품심사체크시트
발생된 문제에 대한 시정조치 업무를 주관한다.
3.2 관련팀장 (●) 품질보증팀장 심사결과 정리 (→) 제조공정 심사 체크시트 (→) 제품품심사체크시트
공정 및 제품 심사 결과 발생된 문제점에 대한 시정조치의 책임이 있다.
4. 업무 절차 (●) 품질보증팀장 업무결과 보고 (●)시정/예방조치 규정 (●)사업계획 운영 규정
제품 및 공정심사 업무의 주관팀은 품질보증팀이며, 업무 절차는 다음과 같다.
책임(●) / 협조(→/←) 절 차 문서(●) / 기록(→/←) 5. 세부 절차
5.1 심사대상 발생
제품 및 공정심사 대상은 다음과 같다.
(●) 품질보증팀장 심사대상 발생 (1) 주요공정 변경 발생시
(2) 설비의 성능이 노후되어 품질산포가 클 경우
↓ (3) 불량이 지속적으로 발생하는 경우(고객, A/S, 클레임 포함)
(●) 품질보증팀장 필요성 검토 및 대상선정 (4) 양산초기 생산 제품
(5) 중대한 부적합으로 시정조치 완료 후
