페 이 지 3/4
5.2 필요성 검토 및 대상 선정 (4) 공정 자주검사 및 모니터링의 실행상태
품질보증팀장은 상기의 심사 사유에 해당되는 대상 공정 및 제품을 우선순위로 선정하고, (5) 품질기록 유지 상태 및 품질에 영향을 주는 요인
최소한 전체공정이 3년에 1회이상 심사될수 있도록 한다. 5.5.2 제품심사
심사원은 대상제품의 생산, 보관, 인도 단계에서의 무작위 파렛트 또는 BOX 를 샘플링하여
5.3 심사계획 수립 다음 각 사항을 심사하여 문제점을 "(제품,공정)심사 개선 계획 및 진척 현황"에 기록한다.
품질보증팀장은 고객지정의 요구되는 접근법을 사용하여 시스템의 효과성 및 효율성을 (1) 포장규격 준수 및 포장상태
결정하기 위하여 3년 주기로 모든 제조 프로세스가 심사될 수 있도록 "공정심사 계획서"에 (2) 제품식별표를 포함한 모든 라벨의 일치와 부착상태
공정심사 계획을 수립하고 제품심사는 "년 제품심사 계획서"에 따라 제품심사를 실시한다. (3) 제품의 조립상태 및 외관결함 상태
그리고 계획서에는 모든 교대조가 포함되도록 한다. (4) 제품의 중요 치수 측정 및 성능, 기능 정도
(5) 고객의 주요불만 시정조치 상태
5.4 심사통보 및 준비
5.4.1 품질보증팀장은 제품 및 제조공정 심사를 수행할 수 있는 심사원을 선정하고, 해당 세부 5.6. 심사결과 정리
일정을 수립하여 공장장의 승인을 득한다. 5.6.1 심사 종료시 심사원은 피심사팀장과 지적사항별로 개선대책을 협의하여 설정한다.
5.4.2 품질보증팀장은 심사계획을 해당팀에 배포하여 심사수행사항을 통보한다. 5.6.2 심사원은 심사결과를 "(제품,공정)심사 개선 계획 및 진척 현황"에 정리하여
5.4.3 품질보증팀장은 해당 업무담당자와 현재 적용되고 있는 제품,공정 수행에 필요한 관련 체크시트 및 검사성적서를 첨부하여 품질보증팀장에게 제출한다.
제반문서의 내용을 상호확인 한다.
5.7 업무결과 보고
5.5 심사수행 5.7.1 품질보증팀장은 심사결과를 종합하여 지적유형별 대응 대책을 수립한 후 공장장에게
5.5.1 공정심사 보고한다.
심사원은 프로세스 리스크 분석 (PFMEA와 같은), 관리계획서 및 연관된 문서의 효과적인 5.7.2 품질보증팀장은 업무보고시 공정/제품 심사결과에 따른 제반 문서의 개정현황을
실행에 대한 심사를 포함하여 대상제품의 공정이 수행되는 전체 생산 Line에 입회하여 파악하고 공장장에게 보고한다.
수행중인 작업을 확인하거나 해당 작업자와 인터뷰를 통하여 "내부심사 제조공정 체크시트" 5.7.3 품질보증팀장은 개선대책에 따라 결과를 확인하고 미흡할 경우 시정조치가 되도록
에 따라 다음의 사항을 심사하고 심사 결과 문제점을 기록한다. 관리한다.
(1) 관련표준류(공정FMEA,관리계획서,작업표준서,검사기준서 등) 적합성 및 이행상태 5.7.4 공정 및 제품심사에 따른 문서개정사항은 경영검토에 상정하도록 관리한다.
(2) 부적합품 처리 및 관리상태
(3) 이상발생시 대응상태
