5.2 제안 제출팀
2. 목적 (1) 제안 1차 점수평가(해당팀) / 제안 2차 점수평가(제안 심사위원회)
이 규정은 회사의 전사적 품질경영 활동의 일환으로 사원의 창의성과 연구심을 진작, (2) 제안현황 관리
육성하고 이를 회사운영에 반영하므로서 사원의 사기양양과 업무능률의 향상을 기하여 (3) 제안활동 참여 독려
회사의 발전을 도모하는데 그 목적이 있다.
5.3 개선 실시팀
3. 용어의 정의 (1) 1차 채택제안 개선실시 유,무를 결정한다.
