제안이란 업무의 개선, 품질향상, 생산성향상 및 원가절감등을 위하여 개인이나 공동의
참여에 의해 스스로가 연구 창의한 것으로 회사발전에 기여할 수 있는 것을 말한다. 6. 제안심사위원회 구성 및 운영
