(2) 각 위원은 제안내용을 제안서의 심사기준에 의거 심사를 하며, 필요시 현장조사를 실시 7.5.1 심사위원 및 심사내용
하여 심사한다. 구 분 심 사 위 원 심 사 일 심 사 내 용
팀별별 심사 해당 팀장 (1차) 접수후 3일 이내
7. 제안절차 주관팀 심사 각 사업부장 (2차) 매월 마감후 15일 이내 2차 평가후 아이디어 이상
7.1 제안의 대상 최종 심사 경영진 2차심사후 7일 이내 2차 평가후 아이디어 이상
제안은 경영 및 관리업무의 능률개선, 생산성 향상 및 품질향상과 사고 또는 재해방지, 7.5.2 심사항목
신제품 개발등을 위해 회사경영에 유익하다고 인정되며, 건설적이고 구체적인 내용이 (1) 불채택
있는것을 제안의 대상으로 한다. 가. 상사의 구체적 지시명령에 의해 행해진 사항
나. 업무상의 회의등으로 행한 개선사항
7.2 권리승계 다. LINE(설비)등 도입시 양산전에 LIST-UP된 문제점의 개선
접수된 제안에 대하여 일체의 권리는 접수일로부터 회사에 귀속된다. 라. 단순한 비판, 불평등의 내용이나 건설적 요소가 포함되지 않은것
마. 예상효과가 인정되지 않거나 개선실현이 불가능한 것
7.3 제안서 작성 (2) 아이디어 : 예상효과는 미세하나 개선실현이 가능하여 실지 실시하고 제안한것
