6.1 주제의 선정
4.3 분임조장 (1) 분임조 활동의 주제 선정은 각 분임조에서 재기된 문제점을 중심으로 조장이 소속장과
4.3.1 구 성 협의하여 선정한다.
각 분임조장은 분임조에서 선출하여 분임조 운영 위원장의 결재를 득하여 결정한다. (2) 분임조 단독으로 주제선정이 곤란할 때에는 분임조 운영 위원회에 의뢰하여 자문 또는
4.3.2 임 무 지정 받을 수 있다.
(1) 분임조 활동회의 주관 (3) 주제 선정 시에는 반드시 선정 이유를 제시하여야 한다.
(2) 분임조 활동 계획 수립
(3) 분임조원의 임무부여 6.2 활동계획서 작성
(4) 분임조의 활동 진행 및 결과체크 주제가 결정되면 "분임조 활동계획서"를 2부 작성하여 1부는 추진 사무국에 제출하여
(5) 기타 분임조 활동 전체를 총괄 운영한다. 승인을 받고 1부는 자체 보관한다.
4.4 분임조 서기 6.3 요인분석 및 대책입안
4.4.1 구 성 (1) 선정된 주제는 철저하고도 확실성 있게 근거에 의한 현상파악을 한다.
서기는 분임조원 중에서 호선하여 조장이 임명 또는 분임원 토의에서 자체 선출하여 (2) 중요한 요인에 대한 분석은 각종 경영기획 기법으로 분석하여 원인을 파악한다.
임기는 1년을 원칙으로 한다.
4.4.2 임 무 6.4 개선활동
(1) 품질분임조 활동 시 "분임조 활동계획서", " 품질경영 활동 회의록", "분임조 활동결과 (1) 계획에 따라 조장을 중심으로 개선활동을 적극적으로 추진한다.
보고서"를 작성 결재 제출 및 보관한다. (2) 개선활동은 문제점을 해결하기 위한 제반요인을 단계적으로 체크하여 해결하도록 한다.
(2) 기타 분임조에 관련된 활동 수행 중에 조장을 보좌하여 제반업무에 처리한다.
