(2) 회합장소는 사무실, 작업장 및 사외로 할 수 있으며 분임조장은 반드시 "품질경영 활동 방침에 관련된 테마인가, 일상 업무중 능히 할 수 있는 테마인가 등을 고려하여 평점한다.
