자세 확립과 윤리경영 실천에 기여하고자 함. 명예를 실추시키는 행위를 하여서는 아니된다.
3. 윤리적 의사결정 및 행동 원칙 6. 성실한 업무 수행
구성원은 직무수행과 관련하여 윤리적 갈등상황에 놓이게 될 경우, 윤리규정과 실천지침을 구성원은 자신의 권한과 책임을 명확히 인식하고 신의성실의 원칙에 따라 직무를 수행
기준으로 판단하고 행동하여야 한다. 하여야 한다.
