판단하고 행동하여야 하며, 자신의 판단에 확신이 없는 경우에는 조직의 부서장에게 질의, 7. 선물, 접대등의 수수
상담하여 그 해석에 따라 행동하여야 한다. (1)구성원은 모든 경영활동을 공정하고 투명하게 수행하여야 한다. 따라서, 부당하고 불공정한
(1) 합법성: 자신의 행동이 법규 또는 사규 위반으로 해석될 가능성이 있는가? 이익의 향응을 목적으로 이해관계자에게 금품이나 향응 등을 제공하여서는 아니된다.
(2) 투명성: 자신의 의사결정 과정과 내용을 공개할 수 있는가? (2)구성원은 협력회사 등 이해관계자들로부터 금품, 향응 또는 기타 개인적인 편의 등을
(3) 합리성: 다른 구성원들도 동일한 상황에서 같은 결정을 할 것인가? 받아서는 아니된다.
(3)단, 상호간의 건전한 관계를 유지하기 위해 이해관계자와 사회 통념상 인정되는 범위내에서
4. 책 임 합리적인 수준의 선물이나 접대 등을 주고 받을 수 있다.
(1) 모든 구성원들은 윤리규정과 실천지침을 준수할 책임이 있으며, 의문이 있는 사항에 대해서는
