기대한 결과에 대한 불확실성의 영향(effect of uncertainty on an expected result)으로
Risk는 “조직/개인의 시간 , 자원, 재정 또는 행복한 상태에 부정적 영향을 줄 가능성이 ↓
있는 상태”이다. (●) 품질경영팀장 (→) 관련팀장 리스크 분석 (→) 리스크 분석표
3.2 사업연속성 기획(BCP:Business Continuty Plan) ↓
중단 사고 발생 시 사전 정의된 수준으로 조직이 핵심업무를 대응, 복구, 재개 및 (●) 품질경영팀장 리스크 대응 방안 수립 (→) 리스크 분석표
복원할 수 있도록 설명된 문서화된 절차
