SELECT 'A-8100', '5. 세부업무 절차 (예) 프로세스: 자금관리', '5.1 리스크 분석 및 대상 결정 Risk : 단기 자금 경색
5.1.1 각 팀은 매년 사업 계획 수립 시 또는 주요 변경사항 발생 시 해당 팀의 주요 업무뿐야 및 원인: 수금 또는 자금조달과 지출의 불일치에 의한 자금 지출 불능 발생
프로세스와 제품개발에 따른 Risk 파악 및 분석을 하여야 한다. 영향: 임금/구입 대금 등 지급 지연에 의한 신용 저하, 조직 이미지 실추
5.1.2 Risk 분석은 고객만족/기업성과에 큰 영향을 미치는 활동/프로세스와 제품이 대상이 되며, 대응(단기): 수금 계획, 자금계획(월, 주) 수립 및 운영
제품과 관련된 리스크 분석은 『공정 FMEA 지침』에 따른다. 대응(장기): 단기 자금 차입 축소 전략/계획 수립
5.1.3 각 팀은 매년 사업계획 수립시 다음을 고려하여 Risk 분석 대상을 정한다.
(1) 고객의 신 제품 개발, 생산 및 경영 동향 및 변화 5.3 리스크 메커니즘 규정
(2) 국제 경제 환경, 변동 요소 및 이슈사항 5.3.1 각 팀은 Risk 항목 별로 Risk가 발생/전개되는 과정(Mechanism) 을 파악하여야
(3) 비상상태 대비 및 대응 10가지 이슈사항 하며 이를 위하여 발생원인과 영향/결과를 파악하여 정리한다.
(4) 현재/잠재 경쟁 자의 개발, 생산, 조직 운영 및 주요 변동사항 5.3.2 원인 규명 시에는 “5why, 계통도법” 등의 방식을 이용하여, 발생 과정과 원인을
(5) 법규, 제도 및 사회 환경 변화 내용 파악한다
(6) 조직 구조/인적자원/시스템 및 운영방식/재무 구조 등 내부 이슈 5.3.3 Risk 에 따른 영향/결과(Consequence)를 다음을 포함하여 파악한다.
5.1.4 각 팀은 Risk 분석 결과를 사업계획에 반영하여야 하며, 사업계획 실행 중 목표 (1) 고객에게 미치는 영향
달성에 영향을 끼칠 수 있는 변동이나 이슈가 발생된 경우 Risk 분석을 재 실시한다. (2) 회사의 손익/수익성에 미치는 영향
(3) 내,외부 이해관계자에게 미치는 영향
5.2 리스크 파악 (4) 제품 품질 및 납기에 미치는 영향
5.2.1 각 팀은 파악된 이슈, 주요 변화 요소 및 성과에 중대한 영향을 미치는 프로세스 (5) 제품/서비스 사용 및 유지에 미치는 영향 등
등에 대하여 Risk 파악을 실시한다. (6) 회사 이미지/평판에 미치는 영향
5.2.2 Risk 파악은 업무/프로세스에 있어 그 목적의 미 달성, 고객 불만족, 효율성 저하, 5.3.4 파악된 내용은 “부정적 사항(위험)과 긍정적 사항(기회)”로 나누어 분류하며.
재산/이익 측면의 손실 발생, 직원 안전/건강 또는 사기저하 등을 유발할 수 있는 “RISK 분석표”에 등록한다.
기술적 위협, 자연 재해, 의도된 위협을 포함한다.
5.2.3 Risk 분석 시 잠재/실제 리콜, 필드 반송, 수리, 불만, 폐기 및 모든 재작업으로부터 5.4 리스크 추정
의 습득교훈이 포함되도록 하여야 한다. 5.4.1 각 팀은 Risk의 영향, 발생 빈도, 감지가능성/돌발성에 대한 의사소통과 합리적인
5.2.4 Risk 파악 시에는 정상 상황 뿐만 아니라 비 정상 상황에서 발생되는 요소도 포함 수준 평가를 위하여 수준 등급을 정하고 점수를 부여하여야 한다.
하여야 한다. 5.4.2 각 팀은 Risk의 영향/결과에 대하여 심각한 정도를 판단하고 이를 점수화 한다.
5.2.5 Risk 파악 시 Risk와 그 원인 및 영향이 혼동되지 않도록 구분하여야 한다. Risk 심각도의 점수화 기준은 부표 1에 따른다
