Risk 발생도의 점수화 기준은 부표 2에 따른다 (4) 기타 취약성의 보완
5.4.4 각 팀은 Risk의 감지 가능 정도와 돌발적 발생 및 확산 정도에 대하여 긴급도를 5.7.2 각 팀은 대응방안의 실행 과정 및 완료 여부를 모니터링 하여야 한다.
추정하고 이를 점수화 한다. Risk 긴급도의 점수화 기준은 부표 3에 따른다 또한 실행 결과를 보고하여야 한다.
5.5 리스크 분석 5.8 사업 연속성계획(BCP) 수립
5.5.1 각 팀은 Risk 영향(심각도), 발생 가능성(발생도), 감지 가능성(긴급도)을 곱하여 5.8.1 각 팀은 중점관리 대상으로서 Risk 대응 방안이 “ 비상계획(Contingency Plan)인
위험지수(RPN=Risk Priority Number)를 산출한다. 경우 사업연속성 계획(BCP-Business Continuity Plan)을 수립하여야 한다.
5.5.2 위험 지수 산출 결과 25점 이상이거나 개별 항목 중 5점이 있는 경우 중점관리 대상 5.8.2 사업연속성 계획(BCP) 에는 중점 관리대상 활동에 대하여 위협이 현실화 한 경우
으로 분류하고 조치 방안을 수립하여 관리한다. 어떻게 신속한 복구 및 업무 재개가 되도록 할 것인가의 계획이어야 하며, 최악의
5.5.3 Risk 분석 결과는 RISK 분석표에 기록 후 총무팀에 제출, 총무팀은 경영진에 보고한다. 상황을 고려하여 계획을 수립하여야 한다.
5.8.2 사업연속성 계획에는 다음 사항이 포함되어야 한다.
5.6 리스크 대응방안 수립 - 핵심 설비 고장,공급자 운영 중단, 자연 재해, 유틸리티 중단, 노동력 부족 또는
5.6.1 각 팀은 각 Risk 항목에 대하여 대응방안을 수립한다. 인프라 중단 등
대응 방안에는 수용, 전가, 통제, 회피, 활용, 강화, 비상계획이 있을 수 있다 5.8.3 사업연속성 계획은 중단 사건 발생 시 누가, 어떤 자원을 이용하여, 어떤 방법으로
5.6.2 대응 방안은 위험과 기회 또는 이들 모두에 해당되는 경우로 구분하여 수립한다. 신속히 복구 및 업무 재개를 할 것인지를 나타내어야 한다.
세부사항은 부표 4에 따른다 5.8.4 사업연속성 계획에는 고객 운영에 영향을 주는 모든 상황의 정도와 기간에 대한
5.6.3 각 팀은 위험에 대한 대응방안이 “통제(Control)이거나 기회로서 대응이 필요한 고객 통보 절차를 포함하여야 하며, 적절한 시뮬레이션을 포함하여 사업 연속성
경우 구체 대응 방안을 수립하고 사업계획에 반영한다. 계획의 효과성을 주기적으로 테스트하여야 한다.
5.6.4 대응 방안 수립 시에는 적절한 기한 내에 완성되도록 하고, 달성 가능(Achievable)
한 방안으로서, 목표 달성 여부의 측정가능(Measurable)한 것이 되도록 한다 5.9 유지관리
5.6.5 Risk 대응방안 수립 결과는 RISK 분석표에 기록, 총무팀에 제출, 총무팀은 경영진에 보고한다. 5.9.1 각 팀은 대응방안 실행 이후, 잔존 위험의 존재 여부와 수준을 파악하고 평가하여야
한다.
5.7 리스크 대응계획 실행 5.9.2 잔존 위험이 감내할 수준이 아닌 경우 Risk 분석 및 대응방안 수립, 실행을 다시
5.7.1 각 팀은 다음을 포함하여 Risk 대응방안을 실행하여야 한다. 진행하여야 한다.
(1) 관련 프로세스/시스템 개정 또는 개선 5.9.3 각 팀은 Risk 항목 별로 사후관리 필요 여부를 판단하여 Risk 대응 방안 실행으로
