(4) 기반시설 붕괴
4. 책임과 권한 (5) 공급자 공급중단 (원/부자재)
4.1 대책위원장 (6) 천재지변 발생시
대표이사는 비상사태 대책위원장으로서 비상사태 발생시 중대한 문제를 결정, 승인, 조기, (7) 인원 부족시
응급 복구 할 책임이 있다. (8) 정보 시스템에 대한 사이버 공격
(9) 가스 및 화학물 유출
4.2 대책위원회 (10)팬데믹(바이러스)
대책위원회는 각 사업부 사업부장 및 각 부서 팀장들로 구성되며, 비상사태 예방 및 사태
수습을 위한 실무조직을 구성, 운영해야 한다.
