5.2 비상사태의 발생 통보 5.3.4 사고 조사반
(1) 비상사태 발생팀은 긴급사항을 유,무선 또는 구두로 총무팀장에게 통보하여야 한다. (1) 사고현장 기록 유지(사진, 동영상)
(2) 통보를 접수한 총무팀장은 비상사태라고 판단되는 경우 비상사태 대책위원회를 소집 운영한다. (2) 원인조사 및 재발방지 대책 수립
(3) 총무팀장은 비상사태 발생 즉시 필요한 경우 비상연락망 및 사내방송등을 통하여 전 임직원에게 (3) 관계기관 섭외 및 정보수집
상황을 전파토록 한다.
(4) 회사의 중요 대외기관의 연락처는 부표 1과 같다. 5.3.5 대외 홍보반
(1) 언론기관 섭외 및 통제
5.3 비상사태 대책 위원회 운영 (2) 대외 발표자료 작성 배포
비상사태 대책위원회 조직은 부표 2와 같으며 그 역할은 아래와 같다. (3) 지역주민 홍보
(4) 본사 보고 및 연락창구 역할
5.3.1 대책위원회
비상사태 발생시 이의 수습을 위해 총괄 지휘 및 대외기관에 협조를 요청하며, 비상연락망, 5.3.6 일반지원반
무전기, 랜턴 등의 응급장구 및 안전보호 장비를 확보해야 한다. 사고발생 소속해당팀장 및 소속인원은 비상기획팀원으로 구성하며, 대비/지원반
및 방호복구반을 지원한다.
5.3.2 대피/지원반
(1) 피해자 수송과 치료 전반의 의무활동 < 비상사태별 주요책임자별 업무처리 FLOW>
(2) 피해 우려지역 대피 및 방재활동 지원 종 류 장 소 책 임 자 처 리 절 차 비상사태 발효
(3) 피해자 조사, 보상협의 및 장례운영 주요설비 고장 제조 현장 생산기술팀 비상사태 발생시 대응 방안 참조 (A8101-01)
유틸리티 고장 제조 현장 생산기술팀
5.3.3 방호복구반 화재 발생시 전 공장 총무팀
(1) 사고현장 확인, 보존 및 증거기록 (증거가 필요한 부분에 한함) 기반시설 붕괴 전 공장 총무팀
(2) 추가 비상사태 발생 인자 차단 공급자 공급중단 제조 현장 구매팀
(3) 재해발생 상황별 대응 천재지변 발생시 전 공장 총무팀
(4) 후속 사고예방 활동 인원 부족 제조 현장 생산관리팀
(5) 현장 복구 사이버 공격 전 공장 총무팀
팬데믹(바이러스) 전 공장 총무팀
