※ 특히, 외부 출입자가 예기치 못한 사고(실수)로 시설파손(누수,누유등)을 야기시켰을 경우 (5) 총무팀장은 각 사업부별 접수된 "비상사태 훈련결과 보고서"를 취합하여 경영진에 보고
경비 또는 총무팀에 연락을 취하고 , 각 시설 책임자는 즉각 관련조치를 취한다. 결재 승인을 받아야 한다.
(6) 필요시 외부기관과 협의, 지원을 받아 훈련을 실시한다.
5.4 비상사태 종료 및 결과보고 (7) 훈련 종료후 훈련내용의 개선 및 보완점은 가상 비상사태 대책서를 개정하고 다음
(1) 사고조사팀은 비상사태 원인조사 및 피해정도를 평가하여 대책위원회에 보고하고, 보고받은 훈련시에 반영해야 하며, 해당부문의 예기치 않은 비상사태 발생시는 다음연도에
대책위원회는 비상사태 복구과 완료되었을 경우 비상사태를 종료한다. 이를 대비시키기 위하여 훈련 및 교육을 실시해야 한다.
(2) 사고발생 팀장은 사고 재발방지를 위해 정밀분석 검토하여 비상사태 조치결과 및 재발방지 (8) 훈련시 총무팀장은 훈련장비 및 훈련에 대하여 적극 지원하여야 하며, 해당팀별
대책을 수립 보고하고 필요한 경우 조직 및 관련 규정 및 비상계획을 개정한다. 훈련결과에 따라 각 비상 대책서의 실효성을 확인하여야 한다.
(사고조사반과 공동 작성 할 수 있음)
(3) 비상사태에 대한 내용은 재발방지를 위해 관련 임직원에게 원인 및 처리결과에 따라 교육을 8. 기록 및 보관
실시하여야 한다. 본 규정의 이행에 따라 발생되는 기록은 『기록관리 규정』의 절차에 따라 보관,
관리되어야 한다.', 3
