재,개정 일자 45047
지속적 개선업무 규정 개 정 번 호 5
페 이 지 3/5
팀 명 분석 대상 자료 분석 방법 (선택) 주기 5.2 개선실시
생산팀 생산기술팀 설비효율 라인별, 공정별, 품목별, 내용별, 설비별 반기 5.2.1 개선테마 설정
설비고장 (1) 해당팀장은 추출된 개선 과제에 대하여 기대효과, 해결가능성, 시급성, 중요도
생산성 등을 토대로 개선 추진 필요성을 검토한다.
품질보증팀 수입, 공정, 최종검사 결과 품목별, 업체별, 원인별, 유형별 (발생수량, 발생빈도) 반기 (2) 해당팀장은 개선항목이 타팀으로 인하여 발생된 문제에 대해서는 “(시정․예방)조치
부적합 발생보고 요구서”를 작성하여 조치팀에 통보한다.
중요한 품질문제
고객품질불만 5.2.2 개선실시
공정능력 평가 (1) 개선 활동은 각 팀장이 주관이 되어 시행하여야 하며, 관련팀의 협조를 받을 수
부적합 사항에 대해 시정조치 후 유사 제품 및 업무에 확산 적용이 필요할 경우 건별 발생시 있다.
(2) 설비, 치공구 등의 신규 제작이나 변경 또는 그 외의 사항으로 예산이 필요한 경우
대표이사의 승인으로 예산을 확보한다.
공 통 업무 수행중 예상되는 문제점을 사전에 방지하고자 하는 경우 대상별 반기 (3) 개선추진을 위하여 TFT 구성이 필요하다고 판단되는 경우에는 대표이사에게 보고
하여 TFT를 구성한다. TFT운영 요령은 "부표1"과 같다.
5.2.3 개선시 활용되는 기법
제품/공정/프로세스/안전/환경 /리스크 분석 결과 경감/완화 하기로 결정한 조치 각 팀장은 효과적인 지속적 개선 실행을 위해 아래의 필요한 기법에 대해 사내,외
교육을 통하여 실시하고 활용하여야 한다.
(1) 관리도
(2) 실험 계획법
5.1.2 개선테마 도출 (3) 제한 이론
(1) 각 팀장은 업무 수행에 따른 리스크 분석 결과와 매월초 전월 해당 성과를 파악하고 (4) 종합적 장비 효과성
그 결과의 구체적 조사 및 해석을 통하여 정상상태(목표치)를 벗어난 사항이나 긴급 개선을 (5) PPM 분석
필요로 하는 문제점 등을 테마로 도출한다. 해당시 타팀의 요청사항 또는 팀원의 제안 등을 (6) 가치 분석
통하여 개선테마로 도출한다. (7) 벤치 마킹
(2) 분기 또는 반기에 해당되는 사항은 해당 분기/반기 직후에 성과를 파악한다. (8) 동작 인간 공학 분석
(3) 5.1.1 / 5.1.2 (1) (2)항까지의 분석에도 불구하고 개선 대상이 없을 수 있으나, (9) 실수 방지방법론
최소한 기록분석을 하였다는 증거를 유지하여야 한다.
