5.3 개선결과 확인 및 보고
(1) 해당팀장은 개선완료후 실시 결과에 효과성을 확인하고 개선진행 및 조치 결과를 정리
하여 대표이사에게 보고하여야 한다.
(2) 해당팀장은 반기별로 경영검토회의시 개선 항목과 개선진행 항목을 보고하여야 한다.
5.4 표준화
각 팀장은 개선 과정 또는 결과상 나타난 표준의 제/개정 필요항목에 대하여 표준
제정 또는 개정을 추진한다.
5.5 기록관리
해당 팀장은 개선실시 결과를 품질기록으로 관리한다.', 2
