페 이 지 5/5
부표1, TFT 운영 요령 결과보고 및 표준화 TF팀장은 팀활동의 과정 및 결과를 승인권자에게 보고
1. TF팀의 구성 하고, 필요시 관련표준의 제/개정을 실시한다.
(1) 회사내에 긴급 특정업무가 발생 하였거나, 비일상적인 과제의 해결 및 잠재적 부적합의
예방조치를 위하여 특별조직의 가동이 필요한 경우에는 TF팀을 구성한다. 팀 해 체 대표이사는 팀활동을 검토하고 팀해체를 승인하며,
(2) TF팀은 대표이사가 팀의 구성을 지시한다. 필요시 포상을 실시한다.
(3) TF팀장은 과업수행을 위한 계획수립 및 결과보고의 책임과 권한이 있으며, 팀 운영을
위한 예산을 회사에 요구할 수 있다.', 4
WHERE NOT EXISTS (SELECT 1 FROM regulation_sections WHERE reg_code = 'B-2200' AND sort_order = 4);
