포함한 계획서를 작성하여 승인권자의 승인을
받는다.(단순한 과제일 경우 생략 가능)
현상파악 및 조사 NO 과제에 관련된 구체사항을 파악한다.
대안수립 및 품의 목적달성을 위한 대책방안을 수립하고 승인권자에게
품의한다.
실시 및 결과확인 TF팀장은 대책을 실시하고 효과를 확인한다.
효과가 없는 경우 원인조사 부터 재실시 한다.
