SELECT 'B-2300', '6. 세부절차 6.5 표준화 및 유지관리', '6.1 관리자 선정 (1) 개선이 완료되면 각 개선 담당자는 개선 결과에 대해 관련 표준의 제,개정을 추진한다.
(1) 품질팀장은 관리자 중 근무 년수, 업무 숙련도 등을 고려하여 정성품질 담당 관리자를 선정 (2) 개선 완료 후 일정기간 동안 개선사항에 대한 유효성, 안정화 여부, 경향 등을 파악하여
하여 최고경영자에 보고한다. 만족스럽다고 판단될 경우 개선 활동에 대하여 최고경영자에게 보고한다.
(2) 관리자가 선정되면 필요시 고객사 담당자에 관리자의 정보를 공유한다. (3) 관리자는 개선된 사항에 대해서 지속적으로 관찰하며 문제점으로 발전될 수 있는 부분이
없는지에 대해 꾸준히 확인하여야 한다.
6.2 정성품질 대상파악 (현상 파악) (4) 해당 개선된 사항은 경영검토시 보고되어야 한다.
(1) 관리자는 작업자 부주의 또는 실수로 인해 발생된 품질 문제 및 고객 부적합을 확인하여
분석을 실시하며 분석 및 개선 활동을 위하여 CFT를 조직하여 운영할 수 있다 7. 관련표준
(2) 분석은 작업자 인터뷰, 현상 재조사, 부적합품 분석 등을 통하여 상세원인을 파악한다. (1) 경영검토 규정 (A-2200)
(3) 명확한 원인조사를 위해 작업자와 인터뷰 하는 과정이 해당 인원의 잘못을 추궁하는 자리가 (2) 시정조치 규정 (B-2100)
되어서는 안되며, 작업자가 편안함을 느낄 수 있는 장소에서 티타임을 하는 등 자연스러운 (3) 지속적 개선업무 (B-2200)
분위기를 유도하여 원인을 명확하게 파악하는 수단이어야 한다.
(3) 인터뷰, 현상 재조사 등을 통해 파악된 내용을 바탕으로 인적요인 및 원인유형을 분류한다 8. 관련양식
(1)정성품질 CFT 업무분장 (B2300-1)
6.3 개선 계획 수립 (2)정성품질 취합 대장 (B2300-2)
(1) 파악된 인적요인 및 원인유형을 바탕으로 대책 방안을 수립하고 해당 대책 방안별 개선계획 (3)정성품질 점검 체크시트(B2300-3)
수립 및 담당을 정한다. (부표 1 "휴면에러 원인 유형 및 대책방안" 예시 참조) (4)문제점 및 개선 제안서(B2300-4)
(2) 관리자는 개선을 진행하기에 앞서 작업자 교육, 체육대회, 다과회, 현수막, 포상제 등을 통해 (5)정성품질 개선 타당성 검토(B2300-5)
개선하고자 하는 분위기 형성안을 제안하고 대표이사의 승인을 득한 후 실시한다. (6)유효성 평가 보고서(B2300-6)
(7)인라인 공정불량 사례 시트(B2300-7)
6.4 개선 활동 전개
(1) 개선 계획 담당은 해당 항목별 개선 활동을 실시하고 필요시 작업자 교육 및 벤치마킹 등을 9. 부표
통해 해결할 수 있도록 한다 (1) 휴먼에러 원인유형 및 대책방안 예시
(2) 개선 실시 중 발생되는 문제점은 해당 팀장과 협의하여 진행한다.
(3) 개선 제안 내용에 대한 포상은 "A-6100 제안관리 규정"에 따른다 10. 동영상 교육 사이트
