→ 잘못된 의사소통 → 작업환경은 작업 혼동 및 집중력 저하 현상에 많은 영향을 미침
→ 불안정한 직장내 인간관계 → 작업자의 조직/개인적인 문제는 작업 효율을 저하시킴
→ 부적합한 서류작업 (3) 대책방안
(2) 세부내용 → 작업장 주위 정리정돈(공구 및 SUB부품 등)을 통한 작업 혼동 방지
→ 작업관련 지식과 의견은 명확해야 하며 오해의 소지가 없어야 함 → 작업 셋팅에 대한 점검항목 설정하여, 시업(복귀) 시 셋팅 상태 확인(재확인) 필요
→ 주/야간 업무 교대 시 업무인수인계가 철저해야 함 → 지속적인 작업자 면담 프로그램 운영 필요
→ 전 단계에서 완료되지 않은 업무에 대해서는 반드시 정보가 전달 되어야 함 → 작업 내용 변경 시 변경 내용을 문서보다는 시각적으로 표기하여 작업오류 방지
→ 외국인 작업자가 최소한의 의사소통이 가능한 방법 제공 필요 → 휴게시간 준수, 좌/우 공정 로테이션
→ 여러 작업자가 단일의 업무를 수행하기 위해서는 작업자 간의 팀워크가 중요함 → 현장내 관리자들의 부적절한 행동통제(작업자 옆 전화통화, 복장 미흡, 작업공간 침범 등)
(3) 대책방안 → 작업자 중심 조도 측정구역 선정 및 조도 추가 확보 실시
→ 완료된 일과 해야할 일에 대한 명확한 전달을 위해 문서화 된 업무 전달 필요 (LED 조명으로 교체, 이동식 조명 비치 등)
(이상상황 정보 전달 대장 이용 업무 인수인계 내용 기록 및 O/P 서명)
→ 소속감을 느낄 수 있도록 품목별/라인별 그룹핑하여 교육이나 단체활동을 실시하고 회사 1.3 자기표현 부족, 침묵
차원의 인센티브 부여 (1) 인적요인
→ 외국인 작업자의 현지어로 작성된 업무표준 및 양식 제공 → 잘못된 의사소통
→ 외국인 작업자를 위한 자료는 그림/사진/동영상 등으로 직관적인 전달 필요 (2) 세부내용
→ 팀원간 유대 관계 형성 및 원활한 업무 협조를 위해 정기회의로 업무 공유 및 업무량 조정 → 자기주장은 자신의 긍정적/생산적인 감정, 의견, 요구사항을 표현하는 것으로 공격적인
→ 의사소통에 대한 교육/세미나 참석 기회 제공 행동이나 주장과는 다름
→ 품질 문제 발생 시 신속한 전파 교육 실시 → 작업자 본인의 주장을 명확하게 얘기하지 않는 경우 품질문제 유발 및 안전사고 초래
→ 후공정작업 시 전공정 문제점을 상호 정보 전달 필요
