(3) 대책방안 2.2 지식부족
→ 작업자 제안제도 운영(우수제안 포상 포함) 필요 (1) 인적요인
→ 양방향 토론 및 회의문화 정착 (일방적인 업무지시성 조회 및 회의는 지양) → 열악한 교육훈련
→ 무기명(비밀) 신고제도 운영 필요 → 부적합한 서류작업
→ 부서내 멘토링 제도 실시 → 업무능력에 대한 잘못된 평가방법
→ 자진신고 시 제재 면제 등 긍정적인 방향의 보상 제시 (2) 세부내용
