2.1 안일함, 인지력 저하 → 공정 문제 발생시 반드시 현장 관리자의 도움을 받아야 함 (작업지연과 무관)
(1) 인적요인 (3) 대책방안
→ 지루한 반복작업 → 부품 사양별작업 특성에 대한 교육 필요
→ 직무 불만족 → 설비 상태(유압, 공압, 모니터, 전원, EOS 등)에 따른 불량유형을 충분히 교육 받은 직원만
→ 열악한 교육훈련 해당공정 작업 수행
→ 부적합한 서류작업 → 작업 관련 기준(표준, 절차 등)은 항상 최신본 유지
(2) 세부내용 → 정기적인 작업자 직무교육 시행 및 배치기준 설정, 시행 필요
→ 동일한 작업 지속시 익숙함으로 인해 안일함/자만심 및 인지력 저하 발생 가능함 → 유사부품 구분에 대한 명확한 시각적 자료를 배치하고 교육 실시
→ 검사 관련하여 문제없는 상태가 지속되는 항목의 경우 작업자가 임의로 검사를 소홀히 → 교육 후 평가를 통한 적절한 보상 제공으로 동기부여
하거나 미실시할 가능성이 있음 → 사무직 뿐 아니라 현장직원들도 품질/생산관련 사내외교육 기회 확대
→ 자신의 행동이 어떤 의미를 갖는지를 알지 못하면 그로 인한 결과도 인지하지 못함 → 자신의 작업 불량이 완성차에 어떤 영향을 끼치는지에 대한 교육 실시(영상, 이미지 등)
(3) 대책방안
→ 중요 공정/검사 항목은 이중확인 절차 운영 필요 2.3 자만심, 잘못된 관행
→ 특정 공정에 장기간 근무한 작업자는 정기적인 순환 배치가 필요함 (1) 인적요인
→ 완벽하게 확인되기 전 작업일보 등 서명 금지 → 잘못된 기준
→ 작업자가 생산하는 부품의 기능 및 품질 중요성에 대한 교육 필요(작업 중요성 인식) → 직무 불만족
→ 주기적인 작업자 면담을 통해 순환근무, 보직 변경 등 검토 필요
→ 작업자 호칭 변경 (작업자 → 공정 책임자)하여 생산품에 대한 책임감 부여
