(2) 세부내용 → 심리적 인자 : 감정적 요소, 직장동료 및 상관과의 관계, 가정사 등
→ 관행이란 문서화된 규정은 아니지만 일반적으로 행하는 일의 방식 → 생리적 인자 : 피로, 허약한 몸 상태, 배고픔, 질병 등
→ 부정적인 관행은 작업 기준 수립을 방해하고 품질문제 및 안전사고 발생의 원인 (3) 대책방안
→ 부정적 관행은 비정상 작업수행, 기억에 의존한 작업 수행, 절차 미준수등이 있으며 고참 → 공정별 업무강도 분석 후 작업자별 적절한 업무 순환 배치 및 분배 필요
작업자일수록 따르기 쉬움 → 시업(복귀)시 작업자 건강상태 자체 판단하여 업무배치 조정 가능한 절차(기준) 운영
(3) 대책방안 → 작업자가 스트레스를 받는 요인을 분석하여 도움을 줄 수 있는 프로그램(제도) 운영
→ 동일한 기준을 준수할 수 있도록 작업 관련 기준(표준, 절차 등)은 항상 최신본유지 필요 → 정기적인 통근버스 노선 점검 실시(월 단위 등)하여 신규 입사자의 통근 불편 예방
→ 중요 공정/검사 항목은 이중확인 절차 운영 필요 → 외국인 작업자의 근무환경 조성
→ 한도견본을 게시(대형은 해당부위 절단) 또는 큰 사진으로 표현하여 작업자가 수시로 확인 ① 동료간 의지할 수 있도록 되도록 같은 국가 인원 채용
→ 작업표준 최신본유지에 그치지 않고, 해당 표준대로 작업실시 여부 등을 현장 관리자의 정기 ② 외국인 기숙사 환경 주기적 점검 개선
점검활동 필요 ③ 정기 인터뷰를 통해 타국생활 상담
→ 생산을 위해 품질을 미루는 잘못된 관행 개선을 위해 제조부서 팀장 이상급인식 제고를 위한 → 근골격계 질환 사전 예방 : 피로 증가 또는 증상 발생 시 재활 프로그램 참여
교육 실시/참여 → 지역 보건소 스트레스 예방 검사 실시', 6
