SELECT 'B-2300', '3. 작업자 3.2 압박, 부담', '3.1 안일함, 인지력 저하 (1) 인적요인
(1) 인적요인 → 비현실적인 시간
→ 비현실적인 시간 (2) 세부내용
→ 육체적/정신적 피로 → 작업자가 작업시간에 대한 과도한 압박을 느끼거나 새로운 업무를 맡을 경우 자신감이
→ 개인적인 가정사 문제 떨어지며, 촉박한 시간 등의 부담이 큰 상황에서 오류를 발생시킬 가능성이 높음
→ 부적절한 작업환경 → 작업시간을 위해 안전과 품질이 희생되는 것은 허용될 수 없으며, 작업자가 시간에 쫓긴
→ 회사 처우에 대한 불만 다고 인지하는 경우 조직의 관리자에게 보고하고 공개하여 대안을 논의할 수 있어야 함
(2) 세부내용 (3) 대책방안
→ 피로는 자연적인 현상이며 작업자의 정신적/육체적 상태에 악영향을 줄 수 있음 → 작업자가 느끼는 부담 해소를 위하여 관리자는 지속적인 의견청취 및 개선 프로그램 운영
→ 피로는 작업자의 반사속도, 집중력 저하에 따른 실수 증가 및 잘못된 결정 유발 가능 → 작업자가 적절한 시간으로 작업할 수 있도록 고려하여 표준 수립 및 지속적 업데이트
→ 물리적 인자 : 업무량과 작업환경 등 → 작업시간에 압박을 느끼는 작업자의 작업수준 향상 프로그램 운영
