SELECT 'D-1100', '1. 적용범위 4.3 생산팀장', '이 규정은 회사의 자동차 관련 부품에 적용한다. (1) 제품생산기획 시, 제품안전과 연관된 위험 식별 및 완화
(2) 제품안전과 관련되어 식별된 안전치명항목/주요특성치/특별요구사항/LOT의 관리 및 이행
2 목 적 (3) 생산인원에 대한 제품안전교육 제공
이 규정은 당사가 설계/제작한 또는 고객의 기술자료에 의거 제작하여 고객에게 제공한
제품에 대해, 제품 전 순기에 걸쳐 제품안전을 보장하기 위한 절차를 규정한다. 4.4 구매팀장/생산팀장
(1) 적용시, 제품안전에 대한 요구사항 협력업체에 전파
3.용어의 정의 (2) 협력업체 내에서, 식별된 안전치명항목/주요특성치/특별요구사항의 관리 및 이행 보장
3.1 제품 안전(Product Safety) (3) 구매인원에 대한 제품안전교육 제공
사람에 대한 위해나 재산상의 손실과 같이 받아들일 수 없는 위험을 초래하지 않고, 설계된
또는 의도된 목적을 달성할 수 있는 제품의 상태 4.5 품질보증팀장
(1) 내부심사를 통해 제품안전관리 절차의 이행 보장
4. 책임과 권한 (2) 제품안전 사고의 영향 분석
4.1 대표이사 (3) 제품안전 사고의 이해관계자에 보고
(1) 제품안전에 대한 최종 책임
(2) 제품안전에 법규 및 고객 요구사항 달성을 위한 자원 확보 5. 업무 절차
(3) 제품안전에 대한 권한과 책임 부여 5.1 일반사항
(4) 관련자에 대해 제품안전 사고 교육 (1) 제품안전과 관련된 본 규정의 적용 정도는 고객에 제공된 제품의 안전에 관한 잠재적
영향과 제품의 유형 및 종류에 따라 결정된다.
4.2 개발팀장 (2) 견적 및 계약검토 단계에서 제품안전에 대한 추가 검토 필요성이 있으면 5.2항을 적용한다.
(1) 제품 공정설계 시, 제품안전에 대한 위해요소 평가 및 안전치명항목/주요특성치/ (3) 견적 및 계약단계에서 제품의 형상, 기능을 고려하여 제품안전에 위해 요인이 없는 경우,
특별요구사항/LOT 관리 결정 이를 계약검토서에 기록/유지하여야 한다.
(2) 제품안전을 확보하기 위한 위험관리 실시
(3) 제조공정 설계인원에 대한 제품안전교육 제공 5.2 생산단계에서의 제품안전관리
(1) 생산 중, 제품안전의 위해요소을 분석하여 관련 위험을 식별하기 위해 공정 FMEA를
사용한다. 이때 조직의 인적요인 및 부여된 책임에 대한 위험도 식별하여 처리하여야 한다.
(2) 식별된 위험은 『리스크 관리 규정』 에 따라 관리한다,.
