SELECT 'D-1100', '6. 관련 표준', '5.3 협력업체에서의 제품안전관리 (1) 개발업무 규정(J-1100)
(1) 구매팀장/생산팀장은 적용시 제품안전에 요구사항을 계약서, 발주서, 협약서 등을 통해 (2) 공정 FMEA 작성 및 관리 규정(J-1101)
협력업체에 전파하여야 한다. (3) 협력업체관리 규정(K-1200)
(2) 년1회 협력업체 평가 시, 제품안전활동의 이행여부를 점검하고 불일치 발생 시 시정조치를 (4) 리스크 관리 규정(A-8100)
요구해야 한다.
8 관련 양식
5.4 발생한 제품안전 이벤트 분석 및 보고 (1) 안전 사고 발생보고서(D1100-01)
5.4.1 품질보증팀은 내부심사 시, 제품안전관련 활동 이행상태를 점검하고 잠재적인 이벤트의 (2) 제품 안전교육 보고서(D1100-03)
영향을 분석하여 그 결과를 최고경영자에게 보고한다. (3) 공정 안전점검 연간 계획_실적(D1100-04) - 각 사업부 개별 점검 양식
5.4.2 적용 시, 발생된 이벤트는 24시간 이내에 고객을 포함한 이해관계자에게 ''제품 안전 사고 (4) 공정 안전점검 체크시트(D1100-05) - 각 사업부 개별 점검 양식
발생보고서''를 작성하여 보고한다. (5) 공정 안전점검 개선대책(D1100-06) - 각 사업부 개별 점검 양식
5.4.3 품질보증팀은 발생된 사고에 대해, 관련자를 대상으로 이벤트 교육을 실시하고, 그 결과를
유지한다. 사고 교육에는 아래 사항이 포함된다.
(1) 납품한 제품의 영향
(2) 동일한 기술 또는 구성품에 기반을 두거나, 유사기능을 가지는 다른 부품 에 발생한 이벤트
(3) 안전요인으로 인한 이벤트
5.6 제품안전 교육
(1) 각 팀은 년1회 부서원에 대해 제품안전교육을 실시하고, 교육보고서를 작성/유지한다.
(2) 제품안전교육에는 제품안전에 대한 각 부서원의 기여도와 납품 후 당사가 제공한 제품의
안전에 대한 부정적인 영향을 포함한다.
(3) 관리팀은 협력업체 종업원에 대해 제품안전교육이 실시되도록 계약서, 발주서, 협약서 등을
통해 협력업체에 요구한다. 제품안전교육에는 협력업체 종업원의 제품안전에 대한 기여도가
포함된다.', 2
WHERE NOT EXISTS (SELECT 1 FROM regulation_sections WHERE reg_code = 'D-1100' AND sort_order = 2);
