교육훈련 규정 개 정 번 호 9
페 이 지 2/4
1. 적용범위 책임(●) / 협조(→/←) 절 차 문서(●) / 기록(→/←)
이 규정은 당사 직원의 업무에 관련된 교육훈련 제반 사항에 관하여 적용한다.
2. 목적 (●) 총무팀장 교육기록 유지 [전산이력관리)
사원의 자질과 능력을 개발하고 업무수행에 필요한 지식과 기능을 향상시키는데 있다.
3. 운영 절차 4. 교육훈련의 종류
직무 교육의 주관팀은 경영관리실 총무팀이 되며, 운영 절차는 다음과 같다. 4.1 직무교육
책임(●) / 협조(→/←) 절 차 문서(●) / 기록(→/←) (1) 직무교육은 각 직무에 종사하는 사원의 업무 관련지식 습득 및 업무능률 향상을
목적으로 실시를 하며, 그 기준은 부표 1을 기준으로 시행한다.
(2) 직무교육은 직무 기본 교육사항을 정하여 실시하는 과정으로 신규 직무부여 시에는
(●) 각 팀장 팀원 개인별 업무능력 평가 및 필요 교육 파악 "신입교육", 기존 직무 수행자에게는 "직무교육"을 실시한다.
↓ 4.2 4M변경 교육
(●) 총무팀장 연간 교육훈련 계획 수립 (→) 교육훈련 계획서 4M변경 사항에 대하여 관련 직무에 종사하는 사원에 대하여 관련 정보 및 지식을 공유하는
교육을 실시하여야 한다.
(●) 총무팀장 (←) 대표이사(→) 각 팀장 연간 교육계획 확정 및 통보 (→) 교육훈련 계획서 4.3 매뉴얼, 프로세스, 규정, 지침 제/개정 교육
매뉴얼, 프로세스, 규정, 지침 제/개정 사항에 대하여 관련 직무 종사 사원에 대하여 관련 정보
↓ 및 지식을 공유하는 교육을 실시하여야 한다.
(●) 각 팀장 (→) 총무팀장 사내, 외 교육훈련 실시 및 결과보고 (←) 교육훈련 계획서 (→) 교육훈련결과보고서
4.4 환경 안전교육
↓ 환경 및 안전에 관한 준수사항과 업무 절차를 습득시키기 위하여 환경 안전교육 관련
(●) 총무팀장 교육결과 이력관리 (→) 교육훈련 이력카드 [전산이력관리] 업무 수행자에게 교육을 실시하며, 필요시 사외 위탁교육을 시행할수 있다.
