재,개정 일자 45821
교육훈련 규정 개 정 번 호 9
페 이 지 3/4
4.5 지식관리표 교육 6.3 연간 교육계획 확정 및 통보
지식관리표를 매년 1회 갱신 하여야하며, 갱신된 내용을 이용하여 부서별, 담당자 직별별 (1) 총무팀장은 차년도 교육계획 내용과 소요예산이 포함된 교육계획을 공장장의
업무 수행자에게 교육을 실시하며, 필요시 사외 위탁교육을 시행할수 있다. 검토와 대표이사의 승인으로 확정한다.
(2) 총무팀장은 확정된 교육계획을 각 팀에 배포하여 교육훈련을 시행할 수 있도록 한다.
5. 책임과 권한
(1) 사업부장은 팀원 육성을 위하여 자기개발지원 및 사내,외에서 이루어지는 교육의 위탁 및 7. 교육 방법
관리를 하여야 할 책임과 권한이 있다. (1) 교육방법은 목표, 기간, 비용 등을 고려하여 합숙 또는 기타의 방법을 선택한다.
(2) 사원은 회사에게 지시받은 교육은 반드시 이수하여야 한다. 단, 휴직또는 기타사유로 (2) 교육의 방법은 강의, 토의, 사례연구, 실습 등 각종 교육기법 중에서 해당과정 또는
교육이수가 불가능하다고 인정되는 경우에는 예외로 한다 과목의 특성에 따라 교육효과를 높일 수 있는 방법을 선택하여 실시한다.
※공정 면허에 대한 교육 방법은 이론 평가 및 실기 평가 (실제품 표준 기준 생산 능력
6. 교육 계획 및 검사 능력)를 병행, 평가하여야 한다.
6.1 팀원 업무능력 평가 및 필요 교육 파악
(1) 총무팀장은 매년 12월중에 각 팀장에게 차기년도 교육계획 수립 및 통보를 요청한다.
(2) 각 팀장은 개인별 직무능력 배양 및 업무 목표 달성을 위해 요구되는 부문에 대한 직무별 8.교육 실시 및 결과 보고
필요 역량 분석 및 필요 교육과정을 분석하여 역량개발에 대한 개인별 교육계획을 8.1 사내/외 교육훈련 실시 및 결과보고
수립한다. (1) 각 팀장은 확정된 내용을 토대로 연간 팀내 교육훈련을 실시한다.
(3) 계획 수립은 개인별 직무수행 능력 및 사내 자격관리 요건등을 기반으로하며, 업무 진행에 (2) 교육훈련을 실시후에는 결과보고서를 작성하여야 하며, 교육완료후 7일 이내에
필요한 지식을 고려하여 수립한다. (부표1 및 지식 관리표 참조) 팀장의 승인 후 총무팀 및 품질경영팀에 송부하여야 한다. (자격부여 교육외 팀
(주) 각 팀장은 본인 및 사업부장의 필요 교육도 파악하여 교육훈련계획을 수립하여야 한다. 자체적으로 실시되는 사내교육일 경우는 별도로 총무팀에 송부하지 않는다.)
(4) 각 팀장은 수립된 부서별 교육훈련계획을 총무팀으로 제출 한다. (3) 교육 결과 보고서 작성은 다음과 같이 실시한다.
가. 사외 위탁교육의 경우 수강자가 보고서를 작성한다.
6.2 연간 교육 계획 수립 나. 사내 집체교육시에는 강사가 보고서를 작성한다.
(1) 총무팀장은 관련팀으로부터 사내 및 사외 교육훈련 계획을 접수하여 전사 교육훈련 다. 사내 개별 교육시에는 강사 또는 수강자가 보고서를 작성한다.
계획을 작성한다.
(2) 교육계획에는 교육대상자, 교육시행처, 교육과목, 예상교육비, 예상시기(분기)를 8.2 교육기록 유지
포함하여야한다. 총무팀은 교육훈련 계획서 및 보고서를 보관한다.
(주) 사외교육의 경우에는 외부 교육기관의 교육안내 정보를 참조하여 작성한다.
