9. 사내 자격 관리
사내에 특수 직능이나 능력요건을 필요로 하는 업무 수행자에 대하여는 자격을 부여하고,
해당업무는 유자격자에 의하여만 수행되도록 통제한다.자격관리 세부사항은 『사내 자격
관리 지침』에 따른다.
10. 교육기록 관리
교육훈련 계획서 및 결과 보고서는 품질기록으로 관리한다.
11. 관련 표준
(1) 신규보직자 교육훈련 지침 (F-1101)
(2) 사내 자격관리 규정 (F-2100)
12. 관련양식
(1) 년 사/내외 교육훈련 계획서 (F1100-01)
(2) 교육 이수 보고서 (F1100-02)
(3) 교육훈련 이력카드 (F1100-03) - 전산이력관리 대체
(4) 지식 관리표 (F1100-04)
(5) 사내교육 관리대장(F1100-05)
(6) 사내 교육 보고서(F1100-06)
