SELECT 'F-1101', '4. 운영 절차', '신임교육의 주관팀은 각 팀이 되며, 운영 절차는 다음과 같다. ↓
책임(●) / 협조(→/←) 절 차 문서(●) / 기록(→/←) (●) 소속팀장 직 무 부 여
(●) 소속팀장 신임교육 필요성 확인 (←) 학력,경력,경험 등 확인 5. 세부 절차
5.1 신임교육 필요성 확인
↓ 소속 팀장은 다음 각 호의 경우 신임교육 필요성을 검토하여야 한다.
