(2) 보직변경 또는 담당 직무의 변경
(●) 소속팀장 (→) 지도요원 지도요원 지명 및 임무부여 5.2 필요 교육과목 결정
소속 팀장은 피교육자의 주요경력과 교육이력을 확인하여 필요 교육과목을 결정하여야
