페 이 지 3/4
5.3 지도사원 지명 및 임무부여 (3) 소속 팀장은 평가 결과를 토대로 지도 목표와 달성 정도에 미달할 경우에는
(1) 각 팀장은 해당팀 신임교육을 담당할 지도요원을 지명한다. 재교육을 실시한다.
(2) 지도요원은 교육대상 인원에 대한 신임교육의 목표와 계획수립에 대한 실무 책임자가 (4) 훈련성과 평가 완료후에는 향후 육성의 필요점 등을 파악하여 차기교육 계획에 반영
된다. 지도요원이 다수인 경우 팀장은 지도를 총괄할 대표요원을 선정한다. 하고 사원의 능력개발 자료로 활용하여야 한다.
5.4 신임 교육계획 수립 및 승인 5.8 직무 부여
(1) 지도요원은 소속 팀장이 지시한 교육 대상자의 교육 필요과목에 따라 신임 교육 (1) 신임교육 완료 후 팀장은 해당 인원에게 직무를 부여하고 ''개인별 직무 매트릭스''를
계획서를 작성하여 팀장의 승인을 받아야 한다. 작성, 유지하도록 한다.
(2) 신임교육 계획서는 교육일정, 내용, 교육방법 등을 포함하여야 한다. (2) 신임교육이 완료되기 전에는 독자적으로 업무수행을 하도록 해서는 안되며, 감독자의
(3) 신임 교육 실시기간은 팀장의 판단에 따라 결정 한다. 지도 감독하에 제한된 범위의 보조업무만을 부여할 수 있다.
5.5 훈련 실시 6. 관련표준
지도요원은 “신임 교육 계획서”에 따라 훈련을 실시한다. (1) 조직 및 업무분장 규정 (A-1100)
5.6 훈련 결과보고 7. 관련 양식
(1) 지도요원은 신임교육 완료 후 3일 이내에 ''교육 결과 보고서''를 작성하여 소속팀장 (1) 신임 교육 계획서 (F1101-01)
에게 보고하여야 한다. (2) 신임 교육 일지 (F1101-02)
(2) 피교육 대상자는 하루에 여러 과목을 교육하는 경우 매일, 한 과목을 여러날 시행하는 (3) 교육 결과 보고서 (F1100-02)
경우 해당 교육과목 종료시점에 신임교육 일지를 작성하여 소속팀장에게 보고하여야
한다. 단, 현장사원으로서 단순교육인 경우 강사가 ''교육결과 보고서''로 대체할 수 있다. 8. 부표
(1) 신규보직자 교육훈련 프로그램
5.7 훈련 성과 평가
(1) 소속팀장은 교육이 종료된 경우에는 직무수행에 필요한 능력 배양의 정도를 평가
하여야 한다.
(2) 평가 방법에는 교육 내용의 소감 및 의견 청취, 질의응답, REPORT 접수, 실기평가
또는 평가시험 등의 방법으로 실시할 수 있다.
