품질경영 시스템 문 서 번 호 TPC - F - 2100
재,개정 일자 45047
사내 자격관리 규정 개 정 번 호 5
페 이 지 2/6
1. 적용범위 책임(●) / 협조(→/←) 절 차 문서(●) / 기록(→/←)
이 규정은 특정업무 종사 인원의 사내자격 인정에 적용한다.
2. 목 적 (●) 해당팀장 (→) 후보자 교 육 / 훈 련 (→) 교육결과보고서
유자격자에 의하여 정확한 업무 수행이 되도록 하는데 있다.
3. 자격 종류 (●) 승인권자 자격 평가 (←) 자격부여기준 및 평가자료 (→) 자격인정 평가서
당사의 자격 부여 종류는 다음과 같다.
(1) 검사 및 시험요원 --- 관리부서 : 각 사업부 품질보증팀 ↓
(2) 개발요원(개발담당,개발책임자) --- 관리부서 : 각 사업부 개발팀 (●) 기술연구소 품질경영팀장 자격 등록 및 활용 (→) 사내 자격 관리대장
(3) 내부심사 요원(품질,환경) --- 관리부서 : 기술연구소 품질경영팀
(4) 제조공정 및 제품심사 요원 (2자 심사요원) --- 관리부서 : 기술연구소 품질경영팀 ↓
(5) 특별공정 요원 --- 관리부서 : 해당 사업부 (●) 해당팀장 사 후 관 리
(6) 환경,안전,보건 관리자 --- 관리부서 : 경영관리실 총무팀
(7) 공정 작업자 면허 --- 관리부서 : 각 사업부 생산관리팀', 0
WHERE NOT EXISTS (SELECT 1 FROM regulation_sections WHERE reg_code = 'F-2100' AND sort_order = 0);
INSERT INTO regulation_sections (reg_code, section_title, section_body, sort_order)
SELECT 'F-2100', '5. 세부 절차', '', 1
WHERE NOT EXISTS (SELECT 1 FROM regulation_sections WHERE reg_code = 'F-2100' AND sort_order = 1);
INSERT INTO regulation_sections (reg_code, section_title, section_body, sort_order)
SELECT 'F-2100', '4. 운영절차 5.1 자격 필요 여부 파악', '사내 자격관리는 기술연구소 품질보증팀이 되며, 운영 절차는 다음과 같다. 각 팀장은 신입 또는 보직변경 등 필요시 자격부여 필요 여부를 파악하여야 한다.
책임(●) / 협조(→/←) 절 차 문서(●) / 기록(→/←)
5.2 대상 후보자 선정
해당 팀장은 자격부여가 필요한 경우 해당 자격과 관련하여 기본 자질을 겸비한 인원
(●) 각 팀장 자격 부여 필요여부 파악 (←) 자격부여 기준 중에서 후보자를 선정한다.
↓ 5.3 교육 훈련 실시
(●) 해당팀장 대상 후보자 선정 (←) 자격인증 변경 요청서 해당 팀장은 해당 자격요건에 따라 교육훈련을 실시 하여야 한다.
단, 경력자인 경우 경력 인정으로 교육훈련은 생략할 수 있다.
