페 이 지 3/6
5.4 자격 평가 6. 관련양식
자격 부여를 위한 조건은 자격요건을 이수 하였거나, 이에 상응하는 경력이 있는자에 대하여 (1) 사내 자격 관리대장 (F2100-01)
평가권자가 평가하여 합격한 경우로 한다. 자격 요건 및 평가 방법은 부표 1/부표 2와 같다. (2) 사내 자격 인증 카드 (F2100-02)
(3) 사내 자격 인증서 (F2100-03)
5.5 자격 등록 및 활용 (4) 자격인증 변경 요청서 (F2100-04)
(1) 해당팀장은 ''자격 인정평가서''에 승인권자의 승인을 득하여 기술연구소 품질경영팀으로 해당 (5) 공정면허 이론평가서 1안 (F2100-05-01) - 각 사업부 품질보증팀장 주관 재정 이론 시험 평가
원본을 송부한다. (6) 공정면허 이론평가서 2안 (F2100-05-02)
(2) 기술연구소 품질경영팀장은 신규자격 부여를 한 경우에는 아래와 같이 자격번호를 부여하여 (7) 공정면허 실기평가서 (F2100-06) - 표준 기준 조건 셋팅, 제품 생산, 검사 능력 현물 평가
''사내 자격 관리대장''에 등록한다. 갱신 등록의 경우 기존의 번호를 사용한다. (8) 숙련도_다기능 평가 계획 (F2100-07)
(9) 숙련도 평가표 (F2100-08)
(1)(2)(3) : 당사 약호(TPC) (10) 작업자 현장 직무 현황 (F2100-09)
(4) : 자격분류 코드(아래참조) (11) 작업자 숙련도 CHECK SHEET (F2100-10)
(5)(6) : 일련번호(01~99) (12) 자격 인증 교육 및 평가서 (F2100-11)
(13) 공정별 전담자 및 대체자 관리기준 (F2100-12)
자격분류 기 호 자격분류 기 호 자격분류 기 호 (14) 공정면허 자격인증 평가서(종합) (F2100-13)
개발 요원 CD 검사/시험요원 CI 2자 심사요원 CP (15) 공정면허 자격인증평가(갑지) (F2100-14)
내부심사요원 CA 특별공정요원 CS 환경/안전/보건 CE (16) 공정 자격인증카드_공정 게시용 (F2100-15)
공정면허 PP
5.6 사후 관리 7. 부표
(1) 자격 인정자의 전출, 퇴직등 변동사항이 발생시 해당 부서 팀장은 즉시 해당 인원에 대하여 (1) 부표 1. 자격 요건 및 평가 방법
자격인증 변경 요청서를 작성, 사업부장 승인 후 기술연구소 품질경영팀장에게 제출하여 사내 (2) 부표 2. 공정 작업자 숙련도 평가 기준
자격 관리대장에서 말소하며, 전출자에 대하여는 해당 기록 사항을 변경한다.
(2) 자격 인정 보수교육을 직무교육으로 하며, 자격 유효기간이 경과한 경우 관리부서 주관 재평가를 8. 관련표준
실시 한다. (1) 교육훈련 규정(F-1100)
(3) 자격 유효 기간은 "부표 1"을 참조한다. (2) 측정시스템 평가 지침(L-3101)
