계약검토 규정 개 정 번 호 5
페 이 지 2/3
1. 적용범위 책임(●) / 협조(→/←) 절 차 문서(●) / 기록(→/←)
이 규정은 고객으로부터 접수된 신규제품의 개발의뢰 접수에서 양산 주문전까지의 계약
검토 절차에 대하여 적용한다. ↓
(●) 고객 (→) 개발팀장 개발승인 (←) 개발요청서 (→) 개발일정계획서', 0
WHERE NOT EXISTS (SELECT 1 FROM regulation_sections WHERE reg_code = 'H-1100' AND sort_order = 0);
INSERT INTO regulation_sections (reg_code, section_title, section_body, sort_order)
SELECT 'H-1100', '2. 목적', '고객으로부터 입찰서의 제출 또는 계약서나 주문서를 수락전에 검토하기 위한 업무를 문서화 ↓
된 절차로 수립하고 유지시켜 고객의 요구와 기대사항을 충족 시킴을 그 목적으로 한다. (●) 각 사업부 개발팀장 신제품 개발 (●) 개발업무 규정', 1
WHERE NOT EXISTS (SELECT 1 FROM regulation_sections WHERE reg_code = 'H-1100' AND sort_order = 1);
INSERT INTO regulation_sections (reg_code, section_title, section_body, sort_order)
SELECT 'H-1100', '3. 관리절차', '계약검토 업무의 주관팀은 개발팀이 되며, 업무 절차는 다음과 같다. 4. 세부업무절차
4.1 개발의뢰 접수
책임(●) / 협조(→/←) 절 차 문서(●) / 기록(→/←) 고객으로부터 구두나 문서상으로 개발의뢰 요청이 오면 개발담당은 ''개발의뢰 접수대장''에
등록한다.
(●) 각 사업부 개발팀장 개발의뢰 접수 (←) 개발검토의뢰서 (→) 개발의뢰접수대장 4.2 개발관련 정보조사
4.2.1 개발담당은 개발의뢰 받은 품목을 검토하고 정보가 불충분한 경우 고객에게 문의하여
↓ 고객의 조직과 의사소통 및 연계성 채널을 포함한 필요정보를 입수한다.
(●) 각 사업부 영업팀장 개발관련 정보조사 (←) 설문,경쟁사 자료 (←) 고객사업계획 4.2.2 개발담당은 하기와 같은 자료를 개발의뢰 받은 품목의 검토자료로 활용한다.
(1) 설문조사된 정보 또는 대중매체의 분석자료
↓ (2) 경쟁사의 관련 자료(Sample, 도면, 기타자료)
(●) 각 사업부 개발팀장 계약검토 (→) 제조타당성 검토서 (3) 고객의 사업계획(양산시점, 생산수량, 생산지역, 개발일정 마케팅 전략)
4.2.3 개발담당은 상기 내용을 취합 검토하여 관련팀에 제조타당성검토서, 개발정보 및 관련
↓ 자료를 배포한다.
(●) 각 사업부 개발팀장 계약 서류 취합 및 제출 (→) 원가계산서 (→) 고객요구서류
4.3 계약검토
4.3.1 제조타당성 검토서를 접수한 관련팀은 신제품에 관한 기술성, 경제성, 납기, 고객
지정 요구사항들을 조사, 검토한다.
품질경영 시스템 문 서 번 호 TPC - H - 1100
재,개정 일자 45047
계약검토 규정 개 정 번 호 5
페 이 지 3/3
(1) 기술성 : 금형 및 JIG제작, 생산 가능 여부 및 기타사항 4.7 계약변경
(생산팀,생산기술팀) 개발진행 또는 양산품목에 대하여 고객이 신규 요구사항을 추가하거나 일부 사양을
(2) 경제성 : 투자비용, 공용화, 원가절감 및 기타사항 변경하는 경우 개발담당은 『4M 변경 관리 규정』에 따라 조치한다.
(생산팀, 생산기술팀)
(3) 납 기 : Sample 일정준수 및 기타사항 5. 관련표준
(개발팀, 생산팀, 품질보증팀) (1) 개발업무 규정(J-1100)
4.3.2 개발담당은 일정이 촉박한 경우 관련팀과 회의를 통하여 상기 4.3.1항의 내용을 검토 (2) 4M 변경관리 규정(J-3100)
하고 ''계약 검토서''에 관련검토자료를 첨부하여 검토기록을 유지한다. (3) 양산 주문접수 및 납품관리 규정(H-2100)
4.4 계약서류 취합 및 제출 6. 관련양식
계약검토가 완료된 후 개발담당은 관련팀에서 ''원가계산서'' 작성을 위한 기초자료를 취합 (1) 제조타당서 검토서 (H1100-01)
하여 원가계산서 양식에 의거 자체원가를 산출하고, 품의서를 작성하여 대표이사의 승인을 (2) 개발의뢰 접수대장 (H1100-02)
득한 후 견적을 작성하고 고객의 요구 서류를 관련팀의 협조를 받아 취합,고객에게 제출 (3) 원가계산서 (H1100-03)
한다. (4) 원단위 원가분석 (H1100-04)
4.5 개발승인
(1) 계약서류 제출 후 고객으로부터 개발승인이 확정되면 개발팀은 고객으로부터 개발요청서를
접수하거나, 구두상 승인의 경우 ''개발의뢰 접수대장''에 기록 관리한다.
(2) 개발담당은 개발승인 내용이 고객에게 제출한 서류와 일치하는가를 검토하고 검토내용이
일치하지 않거나 추가 요구사항이 있을 경우에는 고객과 재협의하여 처리한다.
(3) 개발담당은 고객으로부터 접수한 개발요청 관련서류를 관련팀에 통보한다.
4.6 신제품 개발
관련팀은 개발팀으로부터 접수한 개발요청서나 내용을 참조하여 개발업무를 진행한다.
세부업무 절차는 『개발업무 규정』에 따른다.', 2
WHERE NOT EXISTS (SELECT 1 FROM regulation_sections WHERE reg_code = 'H-1100' AND sort_order = 2);
