이 규정은 양산제품의 주문접수 및 검토, 납품 및 실적관리, 수금업무에 대하여 적용한다.
2. 목적 (●) 각 사업부 영업팀장 (→) 관련팀장 월 납품계획 수립 (→)고객 발주서
주문접수에서 납품까지 고객의 요구사항을 보다 신속하게 처리하고, 고객의 납기를 준수하여
효율적인 판매 운영이 되도록 하는데 있다. ↓
(●) 각 사업부 영업팀장 (→) 생산팀장 일 납품계획 수립 (→)출고지시서', 0
