문서를 말한다.
3.2 판매계획 (●) 각 사업부 영업팀장 출고준비 및 납품 (→)거래명세서 및 관련 서류
월간 거래처별, 판매예정금액을 파악, 집계한 계획서를 말한다.
4. 관리절차 (●) 각 사업부 영업팀장 판매실적집계 및 보고 (→)일일납품 실적 (→)월납품실적
주문접수 및 판매업무의 주관은 각 사업부 영업팀이며 관리절차는 다음과 같다
책임(●) / 협조(→/←) 절 차 문서(●) / 기록(→/←) (●) 해당팀장 불만처리 (●) 고객불만처리규정
(●) 각 사업부 영업팀장 주문접수 (←)발주서(FAX,E-MAIL) 6. 세부절차
6.1 주문접수
↓ (1) 영업담당은 고객의 월간/일간 발주서 또는 생산계획을 접수한다.
(●) 각 사업부 영업팀장 (→) 관련팀장 계약검토 (→)납기검토관련 자료
품질경영 시스템 문 서 번 호 TPC - H - 2100
재,개정 일자 45047
양산 주문접수 및 납품관리 규정 개 정 번 호 5
페 이 지 3/4
6.2 계약 검토 6.5.3 출하 준비 및 확인
6.2.1 월 발주 검토 (1) 영업담당은 거래명세서에 출하될 품목 및 수량, 거래처 등을 기록하고 고객에게
(1) 영업담당은 고객의 월간발주서 또는 생산계획을 접수하면 납기요구사항 및 추가변동 인도될 납품서류를 관련팀의 협조를 받아 준비한다.
요인등을 검토하며, 그외 포장, 물류, 기타사항들을 확인하고 생산팀에 고객의 납기 (2) 영업담당은 거래명세서를 기준으로 고객별, 제품별로 선입, 선출 될 수 있도록 LOT
에 따른 리스크를 분석하여 그 일정내 생산이 불가능하면 고객과 협의 조정 등 구분하여 분류하고 이종혼입, 식별 및 라벨링 상태를 확인 후 상차한다.
필요한 조치를 하고 그 결과를 기록관리한다. 6.5.4 납품
(2) 영업담당은 고객의 발주서 및 생산계획을 관련담당에게 배포한다. (1) 납품담당은 영업담당에게 납품서류를 접수하여 상차수량과 비교하고 이상이 없을시
6.2.2 일 발주 검토 고객의 납품장소로 납품한다.
영업담당은 고객의 일일 발주 수량을 당사 재고와 비교하여 검토 결과 재고가 부족 (2) 납품담당은 납품전 기상변화에 따른 장비 및 공구를 사전 점검하고, 운송중에는
할 경우 고객과 일정을 재협의하고, 일정조정이 불가능할 경우 생산담당에게 긴급 도로 법규에 따른 규정속도를 준수하여 제품손상이 발생되지 않도록 하여야 한다.
생산가능여부를 확인하고 잔업, 연장, 철야 등 필요한 조치가 될 수 있도록 한다. (3) 운송중 비상상황에 대처하기 위해 회사와 비상연락체제를 구축하여야 한다.
6.3 월 납품 계획 수립 6.6 판매 실적 집계 및 보고
(1) 영업담당은 수주현황을 정리하여 연간 사업계획과 비교하여 차이가 없을 시 별도의 6.6.1 일일판매 실적집계
납품계획을 수립하지 않고 고객의 발주현황을 납품계획으로 대체한다. 영업담당은 거래명세서를 참조하여 "일일 납품실적 보고서"로 일 납품실적을 보고한다.
(2) 납품계획 수립시 거래처별 매출증진을 위하여 판매실적 및 판매촉진에 영향을 미치는
요인등을 검토하여 납품계획 수립시 반영한다. 6.6.2 월 판매실적 집계 및 보고
영업담당은 월별,거래처별, 품목별로 판매실적 및 초과운임 실적을 집계, 분석하여
6.4 제품 출고 및 납품 매월 공장장에게 보고하고, 고객 발주 대비 출하량이 20%이상 차이가 발생한 경우
6.4.1 일 납품 계획 수립 원인을 분석하여야 한다.
영업담당은 주간 납품계획 및 고객의 일 발주사항을 고려하여 ''일일 출고 계획서''로
당일 출고계획을 수립한다. 6.7 불만처리
6.4.2 재고 보유 여부 확인 회사에서 생산판매한 제품에 대해 고객으로부터 불만 또는 부적합 사항 발생시 『고객
(1) 영업담당은 당일 납품 계획에 따라 제품의 출하대상 품목 및 수량에 대하여 재고 보유 불만 처리 규정』에 따라 처리한다.
여부를 확인한다.
(2) 출하대상품목의 재고 부족시는 생산담당과 생산변경 가능 여부를 협의한다. 세부사항은
『생산관리규정』에 따른다.
