(●) 각 사업부 주관팀장 경쟁사 또는 목표지수 비교평가 (→)고객만족도 분석 자료 고객 불량율 및 고객품질불만 관련 통보 등을 조사내용으로 한다.
(2) 영업팀장은 수립된 계획에 따라 고객의 납기관련 및 초과운임 관련 성과와 품질
↓ 납기, 협조도 등을 설문을 통하여 조사한다.
