(3) 총무팀장은 내부고객 만족도 관련하여 복리후생 및 근무만족도 관련 사항에 대하여 년 1회 6. 관련양식
조사한다. (1) 년 고객만족도 모니터링 (H3100-01)
(2) 고객만족도 조사 시행 계획서 (H3100-02)
4.3 고객만족 자료 정리 (3) 고객만족도 평가서(설문지) (H3100-03)
주관팀장은 조사된 내용을 취합하여 분류 항목을 선정하여 항목별로 자료를 정리한다. (4) 종업원 만족도 조사 설문지 (H3100-04)
(5) 종업원 만족도 조사결과 보고서 (H3100-05)
4.4 경쟁사 또는 목표지수와 비교평가 (6) 종업원 동기부여 계획서 (H3100-06)
주관팀장은 정리된 자료를 경쟁사 또는 설정된 목표지수에 비교하여 고객만족 정도를 (7) 종업원 동기부여 실적평가서 (H3100-07)
평가하고, 항목별로 불만족한 사항에 대해 회사의 사정을 고려하여 우선순위를
결정하여 조치한다.
4.5 경영검토회의 상정
주관팀장은 내,외부 고객만족도 평가 관련 조사, 분석 및 조치한 내용을 경영검토회의에
상정하여 경영자의 검토를 받을수 있도록 준비한다.
4.6 경영자 검토 및 사업계획 반영
경영검토 회의에 상정된 고객관련 자료는 각 관련팀장의 검토 및 상위 경영자의
검토를 통해 회사의 향후 영업 발전 방향결정, 중장기 계획수립, 사업계획에 반영될수
있도록 하고 고객불만 해소 및 신뢰성 향상 정책수립에 활용한다.', 3
WHERE NOT EXISTS (SELECT 1 FROM regulation_sections WHERE reg_code = 'H-3100' AND sort_order = 3);
