하게 처리하여 고객의 요구조건을 충족시키고자 하는데 목적이 있다. (●) 품질보증팀장 (→) 고객 대책서 작성 및 고객 송부 (→)개선대책서 (→)고객불만 대응 조치 결과 보고서', 1
WHERE NOT EXISTS (SELECT 1 FROM regulation_sections WHERE reg_code = 'H-3200' AND sort_order = 1);
