INSERT INTO regulation_sections (reg_code, section_title, section_body, sort_order)
SELECT 'H-3200', '4. 관리절차 5.1 고객불만 접수', '고객품질관련 업무의 주관은 품질보증팀에서 주관하여 처리한다. 품질보증팀장은 고객 또는 관련팀으로부터 고객품질불만 사항을 접수하였을 경우는
책임(●) / 협조(→/←) 절 차 문서(●) / 기록(→/←) ''고객불만관리대장''에 등록한다.
5.2 현품처리 필요사항 파악
(●) 품질보증팀장 고객불만 접수 (←)고객 불만통보서 (→)고객불만 접수 대응 현황 보고서 품질보증팀장은 현품처리를 위하여 긴급히 대체해야할 사항 등을 고객과 협의하고 대책
마련을 위한 문제점을 파악한다.
(●) 품질보증팀장 현품처리 필요사항 파악 (→)조치사항 조사자료 5.3 현품 조치
(1) 품질보증팀장은 현품이 사용불가능할 경우 영업담당에게 통보하여 대체품을 납품하고
↓ 현품은 전량 회수하여 관련팀의 협조를 받아 선별한다.
(●) 품질보증팀장 (→) 관련팀장 현품조치 (→)선별,대체품 (2) 품질보증팀장은 대체품 납품이 불가능하고 고객이 긴급히 제품을 사용해야 할 경우는
선별인원을 선발하여 고객을 방문, 선별 조치토록 한다.
