5.4 불량품 분석 및 처리 ▣부표 1 : 고객사 홈페이지 주소
(1) 품질보증팀장은 불량현상 및 원인을 파악하고 선별 또는 수정 및 사용 가능유무를 순 고객사명 홈페이지 주소 부서명 확인 내용
파악하여 ''부적합품 발생 보고서''를 작성한 후 팀장에게 보고하고 관련팀에 1 ZF 삭스 https://www.zfsachskorea.co.kr/ 영업팀 발주수량 외
통보한다. 품질팀 품질이슈, 정보 외
(2) 관련팀은 부적합 발생보고서의 내용에 따라 수정 또는 폐기처리한다. 개발팀 개발품 정보 외
(3) 품질보증팀장은 조사결과 재발방지가 필요한 사항에 대해서는 『시정조치 운영규정』 2 삼보모터스 http://45.120.69.157:4161/ 영업팀 발주수량 외
의 절차에 따라 다른 유사제품 및 공정을 포함하여 시정조치될 수 있도록 한다. 개발팀 개발품 정보 외
QMS 품질팀 품질이슈, 정보 외
5.5 대책서 작성 및 고객송부 ※홈페이지 접속 점검은 1회/일 이상 접속하여 고객으로부터 전달되는 정보에 대하여 항시
(1) 품질보증팀장은 고객의 요구사항에 따른 개선 대책서를 작성하여 송부하고 현황을 관리한다. 점검, 보고, 결재, 회람등을 진행하여야 한다.
(2) 특별히 지정되는 경우 고객의 요구 양식에 기록 통보한다.', 4
