SELECT 'H-3200', '8. 관련양식', '6. CSR (고객지정 요구사항) (1) 고객불만 접수 대응 현황 보고서 (H3200-01)
(1) 개발 및 영업 팀장은 1회/주 고객사 홈페이지에 접속 및 신제품 개발시 CSR 변경 사항에 (2) 고객불만 대응 조치 결과 보고서 (H3200-02)
대하여 파악 후 대표이사 및 사업부장/ 팀장에게 보고, 승인을 득하여야 한다. (3) 개선대책서 (고객양식)
(2) 해당팀장은 변경사항에 대하여 매뉴얼 및 요구사항 매트릭스에 반영하여 개정 후
대표이사 및 사업부장/팀장에게 결재를 득한 후 관련 팀원 교육을 실시 하여야 한다.
(3) CSR(고객지정 요구사항)에 대한 고객사 홈페이지 및 부서별 확인, 결재, 회람 내용은
