(1) 공정설계 신제품 개발 계획에 따라 추가의 인원 계획이 필요할 경우 단기 및 중장기 투자계획
가. 각 사업부 개발팀장은 신규 개발품에 대해 MDT요원과 ''공정흐름도''를 작성하고 중 인원계획에 반영하고 사업계획을 수립해야 하며, 긴급한 충원의 필요성이 있을시
사양 및 공법을 협의한다. 각 사업부 생산팀장은 총무팀장과 협의를 거쳐 충원 요청에 따라 충원한다.
나. MDT는 개발품에 대해 공정별 생산되는 제품 특성과 관련된 공정변수(전공정 부품 (3) LAY-OUT 실시
특성, 공정변수, 작업조건, 부재료조건 등)와 상관관계를 분석하여 부품특성을 각 사업부 생산팀장은 신규 설비 및 생산 공정의 흐름, 유틸리티, LINE구성 등을 고려하여
만족하기 위한 공정관리항목 및 중요도를 설정한다. LAY-OUT 도면 및 계획서를 작성하여 효율적인 공정이 되도록 계획하며 투자 개념의
(2) 공정FMEA 작성 비용이 발생시 품의를 득한다. LAY-OUT 설정시에는 동선의 최적화와 공간 부가가치의
가. 공정흐름도에서 파악된 중요 공정특성 항목에 대한 각 공정의 기능 및 요구 사항을 최대한 활용이 되도록 한다.
파악하고, 공정별 고장형태, 고장영향, 고장원인, 현 공정관리 방법을 기입후, RPN
을 평가하고 RPN값이 "100이상인 항목 및 심각도가 9이상인 항목"에 대해서는 권고 5.1.5 치공구, 검사구, 계측기 설계 및 제작
