및 관리 지침』에 따른다. 등의 세부사항을 검토한다.
나. MDT는 고객의 특별특성 항목을 FMEA, 관리계획서, 작업표준 작성시 우선적으로 (2) 필요한 경우 내부 검토안을 토대로 외주 설계 제작을 진행한다.
검토하여야 하며, 해당문서에서 특별특성임을 알수 있도록 식별되어야 한다. (3) 치공구, 검사구, 계측기등의 구입 및 제작에 따른 상세 내용은 해당 절차에 따른다.
특별특성의 식별표시는 부표1의 특별특성 기호에 따른다. (4) 각 사업부 "생산팀장"은 치공구 제작이 완료되면 당사의 설비 CAPA 및 단가등을 고려하여
