6. 세부 절차 6.4 FMEA 회의 실시 및 MDT 소집 통보
6.1 FMEA의 일반사항 MDT장은 FMEA 실시를 위한 소집을 위하여 다음사항을 포함하는 협조전을 작성하고
6.1.1 구성 사업부장의 승인 후 사전에 관련팀에 통보한다.
특별히 지정되지 않는 경우 각 사업부 개발팀장이 MDT장을 겸임하며, MDT에는 MDT장을 (1) 회의 주제 및 장소, 일시/시간
포함하여 FMEA 개발에 필요한 생산,품질,생기,영업,자재 등 부서의 실질적이고 직접적인 (2) 팀별 참석자 및 사전 준비자료
대표자로 구성되는데 협력업체 및 고객 요구시 고객의 인원도 참여가 가능하다. 6.5 특별특성 검토 및 결정
6.1.2 책임과 권한 6.5.1 MDT장은 MDT활동을 통하여, 준비된 예비 특별특성 목록표를 재검토하고, MDT의견을
(1) MDT장은 FMEA를 관련 기능부문들 사이에서 아이디어를 상호 교환시키고 팀 활동을 수렴하여 조정, 확정한다.
장려하는 촉매 역할로 삼을수 있도록 감독할 책임이 있으며, 팀의 지명도/불량 가능성 6.5.2 특별특성에 관련한 부품은 반드시 FMEA 실시대상 품목으로 선정한다.
/검출도 및 RPN에 대한 결정권이 있다.
(2) MDT는 FMEA 결과 RPN 및 지명도가 높은 항목에 대하여 합의에 의해 중요 항목으로 6.6 FMEA 대상 품목 및 해석 레벨 결정
선정 관리하고 문서가 계속적으로 살아 있는 문서가 되도록 활용한다. 6.6.1 개발팀장은 MDT활동을 통하여, 예비 제조공정도 상의 공정구성을
재검토한다.
6.2 FMEA자료 준비 6.6.2 PFMEA는 예비 제조공정도 상의 전 공정을 대상으로 함을 원칙으로 한다.
MDT장은 제품공정기획단계 또는 제품설계 변경단계에서 FMEA의 실시를 위한 다음 단, 동일/유사제품에 대한 PFMEA 실시경험으로 대체할 수 있는 경우, MDT를 통한
사항을 준비하도록 한다.(필요시 관련팀에 자료를 요청한다) 제외결정을 할 수 있다.
6.2.1 예비 공정흐름도(PRE-제조공정도) 6.6.3 개발팀장은 MDT활동을 통하여, 특별 제품특성 목록검토 및 예비 공정흐름도 상의
6.2.2 특별특성 목록 및 이력 특별 공정특성을 재검토하고, MDT의견을 수렴하여 조정, 확정한다.
6.2.3 동일/유사제품의 PFMEA 실적자료 6.6.4 특별 제품특성 관련 공정은 반드시 PFMEA 실시대상 공정으로 선정한다.
6.2.4 동일/유사제품의 공정설계 및 개발 정보(성공사례,실패사례,벤치마킹자료,공정능력, 6.7 FMEA실시 대상품목별 고장형태 예측
생산성 자료,고객만족/불만족 자료 등) 6.7.1 MDT장은 MDT활동을 통하여 파악된 FMEA실시 대상부품별로 예측되는 고장형태를
6.2.5 동일/유사제품의 품질이력 정보 다음을 참조하여 도출한다.
6.2.6 고객 및 법규 요구사항(계약검토자료, 포장/인도 관련정보, 안전, 환경 등) (1) 과거의 고장 발생 경험, 부적합보고서(NCR), 고객만족/불만족 정보
6.2.7 제품설계 정보(도면 등), 제품샘플 등 (2) 경쟁사, 선진사의 동일/유사제품에 관한 실패정보 및 기술정보
(3) 특정 작동 및 사용조건하에서의 예측되는 고장발생 가능성 등
6.7.2 잠재적인 고장형태는 특정항목, 기능에 있어서 하나 또는 해당시 다수의 고장형태를
나열한다.
