6.8 잠재적 고장형태별 영향분석 6.12 1차 RPN 산출 및 위험수준 결정
6.8.1 MDT장은 MDT활동을 통하여 파악된 부품별,잠재적 고장형태별로 차량기능,인명상해, 6.12.1 MDT장 및 MDT는 (부표1,2,3) 기준으로 산출된 각각의 심각도(S),발생도(O),검출도(D)를
법규위배,조립성 영향,고객불만족 영향의 정도를 도출, 분석한다. 곱하여 위험우선순위(Risk Priority Number:RPN)를 산출한다.
6.8.2 잠재적 고장형태로 인한 각각의 잠재적 영향은 단품-부품/조립품/기능품-구성품- 6.12.2 심각도(S),발생도(O),검출도(D)가 각 9 이상이거나 RPN 100 이상인 항목은 권고조치
서브시스템-시스템으로 미치는 영향의 관계를 고려하여 작성한다. 대상항목으로서 적색다이아몬드(◇)기호로 식별표시한다(단, RPN 및 각 단위 평가
지수는 개선에 따라 조정가능하다)
6.9 잠재적 고장형태별 고장의 잠재적 원인/매카니즘 분석
6.9.1 MDT장은 MDT활동을 통하여, 파악된 각각의 잠재적 고장형태별로 이러한 고장형태의 6.13 권고조치의 계획 및 실행
추정원인을 도출한다. 6.13.1 MDT장 및 MDT는 상기 6.12.2항에서 도출된 권고조치항목에 대하여 종합적 위험성의
6.9.2 고장형태의 잠재적 원인 및 매카니즘은 각 기능팀 전문가들의 의견을 가능한 간결, 크기(RPN지수), 각각의 심각도(S), 발생도(O), 검출도(D)의 등급을 감소시키기 위해
명확,완전하게 기술한다. 다음사항을 포함하는 개선활동에 한다.
(1) 시정조치 및 예방조치 대상 항목별 방법 및 조치완료일자
6.10 현 적용 관리 방법의 기술 (2) 시정조치 및 예방조치 대상 항목별 책임자
6.10.1 파악된 고장형태, 원인 및 매카니즘에 대한 타당성을 확보하기 위하여 현재 6.13.2 MDT장은 상기 개선활동을 모니터링 및 확인하고 조치가 완료된 후 MDT를 재 소집
적용하고 있는 수단, 활동들을 기술한다. 하여 RPN 재 산출을 포함하여 FMEA를 개정한다.
6.10.2 적용 관리 방법의 전형적인 관리형태의 예는 다음과 같다. 6.13.3 MDT장은 FMEA 요구수준이 충족됨을 보장하여야 하며 낮은 등급의 항목이라 하더라도
(1) 에러/실수방지 가능한 개선조치를 실시한다.
(2) SPC
(3) 검사 및 시험 6.14 후속조치
(4) 공정심사활동 등 MDT장 및 MDT는 FMEA 결과로 도출되고 개선된 다수의 권고조치 실시 성과를 관련
6.11 정량분석 실시 문서에 반영되도록 하고 각 팀 담당인원의 교육을 포함한 팀별 후속활동을 주관한다.
6.11.1 MDT는 파악된 잠재적 고장형태에 대한 가장 심각한 영향과 관련된 심각도(S)
등급을 (부표1)에 의거, 각 고장 형태별로 기술한다. (1) 제조공정도(공정흐름도)
6.11.2 MDT는 파악된 잠재적 고장형태에 대한 고장의 잠재적 원인/매카니즘별 발생가능성 (2) 관리계획서
등급을 (부표2)에 의거, 결정하고 발생도(O)란에 기술한다. (3) 특별특성 관련문서
6.11.3 MDT는 파악된 현 적용 공정관리 방법으로 가장 좋은 검출가능성과 관련된 검출도(D) (4) 작업표준서 등
등급을 (부표 3)에 의거 결정하고 기술한다.
