주요 기능 상실 또는 저하 주요 기능 상실 (자동차 작동 불능, 자동차 안전운행에 영향을 미치지 않는다) 8 중대한 생산 중단 제품을 100% 폐기할 수 있다. 라인 가동을 중단하거나 선적 중단
