보조 기능의 상실 또는 저하 보조 기능 상실 (자동차가 작동하지만, 안락하고 편안한 기능 불능) 6 보통의 생산 중단 양산된 제품 100%가 라인 밖에서 재작업되고 합격되도록 할 수 있다.
보조 기능 저하 (자동차가 작동하지만, 성능 수준의 감소로 안락하고 편안한 기능 수준이 떨어짐) 5 양산 제품의 일부가 라인 밖에서 재작업되고 합격되도록 할 수 있다.
