SELECT 'J-1102', '4. 세부절차', '책임(●) / 협조(→/←) 절 차 문서(●) / 기록(→/←) 4.1 관리계획 작성시기
각 단계별 관리계획의 작성 시기는 다음과 같다.
(1) 시작품 관리계획 - 개발일정계획 수립후 시작품 제작이전
(●) 품질보증팀장 MDT 소집 통보 (→)회의소집 통보서 (2) 양산전 관리계획 - 승인용 도면 접수후 양산 Try-out 실시 이전
(3) 양산 관리계획 - 시험생산 이후 고객승인 이전
(●) MDT 관련 자료 준비 (←)유사차종관리계획서 (←)공정흐름도 4.2 MDT 소집 통보
(1) 품질보증팀장은 각 단계별 관리계획 작성시기에 따라 MDT요원을 소집한다.
↓ (2) MDT 구성은 품질보증팀,생산팀,영업팀,자재팀으로 구성됨을 원칙으로 하며, 세부
(●) MDT 관리계획 작성 및 승인 (→)관리계획서 사항은 『개발 업무규정』에 따른다.
(주) 고객 요구시 MDT 구성에 고객이 포함될 수도 있다.
(●) 해당팀장 관리계획 등록 및 배포 (→)기술표준관리대장 4.3 관련자료 준비
MDT 구성원은 공정흐름도(또는 제조공정도), FMEA, 특별특성, 유사품으로부터
얻어진 정보 등 각 단계에 해당하는 모든 유용한 정보를 자료로 준비한다.
