4.4 관리계획 작성 및 승인 (2) 생산제품이 단종되었을 경우 관리계획은 폐지하고 목록에서 삭제한다.
(1)준비된 자료와 MDT 구성원들의 공정에 대한 기본적인 이해를 바탕으로 MDT 회의를 실시 (주) 단종이라 함은 양산 + 서비스기간이 완료되었음을 말하며 단종 확인은 고객의
하여 관리계획의 초안을 작성하고 검토한 후 CF팀장의 승인으로 확정한다. 통보에 따른다.
(주) 관리계획의 작성은 부표1에 따른다.
(2)관리계획서 작성시 FMEA와 공정번호, 공정명등이 일치하게 작성되어야 한다. 6. 관련표준
(1) 문서 및 자료관리 규정 (A-4100)
4.5 관리계획 등록 및 배포
(1) 품질보증팀장은 확정된 관리계획에 관리번호를 부여하고 ''기술표준관리대장''에 7. 관련양식
등록한다. (1) 관리계획서 표지 (J1102-01 갑)
관리번호 부여방법은 다음과 같다. (2) 관리계획서 (J1102-01 을)
(3) 관리계획서 특별특성 (J1102-02)
(4) 관리계획서 체크리스트 (J1102-03)
① : TPC(회사약호)
② : X(관리계획서 기호) 8. 부표
③ : 차종 약호 (1) 관리계획서 작성 요령
④ : 일련번호
(2) 등록된 관리계획서 사본을 관련팀에 배포한다. 배포시 ''기술표준 관리대장''에
배포처 확인과 구본의 폐기 또는 구본 날인을 확인한다.
(주) 제,개정된 관리계획을 배포하는 경우 이전단계 관리계획(시작품 또는 양산전)
또는 개정이전 관리계획은 회수 폐기함을 원칙으로 하나 해당팀장의 판단에
따라 구본도장 날인후 보관할수 있다.
4.6 관리계획 개정 또는 폐지
(1) 관리계획의 승인, 배포가 완료된 후 설계변경, 공정변경, 공정능력 부족, 공정
불안정, 4M 변경 등이 발생하였을 경우 MDT를 통하여 개정 필요성을 파악하고 제정
절차와 동일한 절차에 따라 개정을 실시한다.
