관리계획서 작성 및 관리 지침 개 정 번 호 7
페 이 지 4/5
부표 1. 관리계획서 작성 요령
1. 관리계획서 항목 설명 (12) 고객 엔지니어링 승인/일자
(1) 양산전, 양산 책임있는 공급자 품질 대리인의 승인을 득한다.(요구시)
관리계획의 단계를 구분표시한다. (13) 고객 품질 승인/일자
(2) 관리계획 번호 책임있는 공급자 품질대리인의 승인을 득한다.
추적에 이용되는 관리계획 문서번호를 기입한다. (14) 기타승인/일자(요구시)
(3) 품번/최신 변경 수준 모든 다른 합의된 승인을 득한다.(요구시)
관리되고 있는 제품번호를 기입한다. 해당시에 가장 최신의 기술수준변경 또는 도면 (15) 부품/공정번호
사양의 발행일자를 기입한다. 공정흐름도에 따른 공정번호를 기록한다.(필히 FMEA 공정 번호와 일치화 하여야 한다)
(4) 품번/설명 (16) 공정명/작업설명
관리되고 있는 제품/공정의 이름 및 설명을 기입한다. 공정흐름도에 따른 공정명을 기록한다.(필요시 공정설명 포한)
(5) 공급자/공장 (필히 FMEA 공정명과 일치화 하여야 한다)
회사명 및 관리계획을 준비하는 해당 공장을 기입한다. (17) 제조를 위한 기계, 장치, 지그, 공구
(6) 업체 코드 기술된 각 작업에 대해 제조를 위한 기계, 장치, 지그 또는 기타 공구등과 같은
고객으로부터 지정된 코드가 있다면 기입한다. 적절한 공정장비를 파악하여야 한다.
(7) 담당자/전화번호 ・특성 : 계량치 또는 계수치 데이터가 수집될 수 있는 공정 또는 그 산출의 대별되는
관리계획에 책임있는 주요 담당자의 이름 및 연락처를 기입한다. 모양, 치수 또는 적절한 경우 조건표(vYJual aids)를 사용할 것
(8) 핵심팀 (18) 번호
관리계획의 가장 최근변경에 대한 책임 있는 개개인의 성명 및 전화번호를 기입한다. 필요시 공정흐름도, FMEA, 기술표준, 도면등과 같은 모든 해당되는 문서의 참고
그것은 모든 팀원의 이름, 전화번호 및 직위가 첨부된 배포리스트에 포함될 것이다. 번호를 기입한다.
(9) 공급자/공장승인/일자 (19) 제품
제조공장의 승인을 획득하라.(만약 요구시) 제품특성은 도면 또는 다른 기술정보에 기술된 부품, 구성품 또는 조립품의 특징
(10) 최초작성일자 또는 특성이다. MDT는 모든 자원으로부터 중요 제품특성을 편집한 특별 제품
최초의 관리계획이 작성된 일자를 기입한다. 특성을 파악하여야 한다. 정기적으로 추적되는 다른 제품특성을 열거할 수 있다.
(11) 개정일자
가장 최근 관리계획의 개정일자를 기입한다.
