(20) 공정 (25) 관리방법
공정특성은 파악된 제품특성과 인과관계를 가지는 공정변수(입력변수)이다. 공정 본란은 해당되는 절차서 번호를 포함하여 작업이 어떻게 관리되는지 간략히 설명을
특성은 그것이 발생될 때만 측정될 수 있다. MDT는 제품산포를 최소화하기 위해 기재한다. 이용되는 관리방법은 공정의 효율적인 분석에 근거하여야 한다. 관리방법
관리되는 산포에 대한 공정특성을 파악하여야 한다. 각 제품특성에 하나 또는 그 은 현존하는 공정의 형태에 따라 결정된다. 작업은 SPC, 검사, 계수치 자료, 실수방
이상의 공정특성이 있다. 어떤 공정에서는 하나의 공정특성이 몇가지 제품특성에 지책(자동화공정/비자동화 공정) 및 샘플링 계획 등에 의해 관리되어 질 수 있으며
영향을 줄 수 있다. 이에 한정되지는 않는다. 전형적인 공정이 어떻게 관리되고 있는지 예를 언급하라.
(21) 특별특성 분류 관리계획의 설명은 제조공정에서 수행되고 있는 계획 및 전략을 반영하여야 한다.
특별특성 항목일 경우 구분기호를 기입한다. 고객 제출시에는 고객의 지정기호를 사용한다. 복잡한 관리절차가 사용된 경우 그 계획서에서 문서화된 절차서의 제목 및 번호를
특별특성으로 지정된 모든 중요품질 특성들에 대한 적절한 공정관리가 이루어져야 한다. 언급할 수 있다. 관리방법은 공정관리의 효율성을 위해 지속적으로 평가되어져야
중요품질특성은 다른특성에 우선하여 공정능력산출, 관리도작성등의 관리방안니 강구되어야 한다. 가령 공정 또는 공정능력에 있어서 유효한 변경이 이루어졌다면 관리방법의
한다. 평가에 반영되어져야 한다.
적절한 통계적 도구들이 사전품질기획 동안 결정되어야하고, 관리계획서내에 포함되어야 한다. (26) 시정조치계획
(22) 제품/공정사양/공차 시정조치계획에서는 부적합제품의 생산 및 관리범위 밖의 작업을 피하기 위해 필요
사양과 공차는 도면, 설계검토, 재료표준. CAD 자료, 제조 및/또는 조립 요구 한 시정조치를 필요로 한다. 이러한 조치는 보통 공정과 가까운 사람 즉, 작업자,
사항과 같은 다양한 기술문서로부터 얻을 수 있다. 조장, 감독자에게 책임이 있으며 명백하게 계획서에 명시되어야 한다. 모든 경우에
(23) 평가/측정방법 있어서 의심되는 제품 및 부적합제품은 명확하게 식별되어야 하고 격리되어야 하며
본 란은 사용되고 있는 측정시스템을 파악한다. 이것은 부품/공정/제조장비의 처분은 시정조치 계획에 지정된 사람에 의해 실행되어야 한다. 본란은 특별한 시정
측정에 요구되는 계측기, 고노게이지 및/또는 시험장비를 포함할 수 있다. 측정 조치 계획번호를 언급할 수 있도록 조치책임자를 명확히 할 수도 있다.
시스템의 선형성, 재현성, 반복성, 안정성 및 정확성의 분석은 측정시스템이
완료되고 개선이 이루어지기 전에 수행되어야 한다.
(24) 샘플크기/주기
샘플링이 요구될 때, 관련된 샘플크기 및 주기 개재
(Fool Proof로 관리되는 경우 시험빈도를 필히 표시할것)', 2
