필요한 장소에서 적기에 사용되게 함으로써 품질관련 활동을 지시하기 위함을 목적으로 한다. 6.2 작업표준 제정 및 승인
6.2.1 생산팀장은 작업표준을 신규 작성시 P1생산 이전 또는 P1 생산 단계에서', 1
