(●) 품질보증팀장 (→) 해당팀장 초도품 제출서류 수준 파악 (→)부표1 참조
↓ (●) 품질보증팀장 기록관리
(●) 생산팀장 초도품 승인용 부품 생산
↓ 4. 세부 절차
(●) 품질보증팀장 (→) 협력업체 공급업체 초도품 승인서류 접수 (←) 초도품 보증서 외 4.1 초도품 승인 대상 여부판단
(1) 품질보증팀은 신제품 개발,설계변경,자재변경,공정변경 등에 따라 양산부품승인
(PPAP)의 필요성이 있는지 확인한다. 초도품 승인 대상 기준은 (부표 1)과 같다.
(2) 관련팀은 상기 (1)항의 변경이 있을 경우 품질보증팀에 세부사항을 통보하여야
한다.
품질경영 시스템 문 서 번 호 TPC - J - 2100
재,개정 일자 45047
양산부품 승인업무 규정 개 정 번 호 5
페 이 지 3/5
4.2 초도품 승인 제출서류 수준파악 4.6 시정조치
(1) 품질보증팀장은 고객이 요구하는 제출서류의 수준을 파악하고 관련팀에 통보하여야 한다. (1) 품질보증팀장은 평가결과 불만족시 공급업체에 통보하여 외주품의 문제점을
단, 고객이 별도 수준을 요구하지 않을 경우 부표 1의 승인 대상 기준별로 부표2 시정 또는 개선조치토록 한다.
제출서류를 준비한다. (2) 생산팀장은 자작품의 문제점을 시정 또는 개선조치토록 한다.
(2) 품질보증팀장은 고객 요구 제출서류에 근거하여 해당팀에 서류를 준비토록
통보하고 준비일정을 협의한다. 4.7 고객승인의뢰
품질보증팀은 관련팀으로 부터 제출용 서류를 취합하고, 검토 후 만족시 고객에게 제출한다.
4.3 초도품 승인용 부품생산
(1) 생산팀장은 정규 양산 체제와 동일하게 총 500개 이상을 생산하여야 하나,
고객이 서면으로 시료수를 지정 했거나 승인한 경우에는 생산수량을 변경할 수 있다. 4.8 고객승인 접수 및 이관
(2) 연속 LOT로 생산하여야 하며, 4시간 이상의 생산분이어야 한다. (1) 고객승인시는 고객의 승인서를 접수함을 원칙으로 하나 고객이 제공하지 않은 경우
승인결과를 확인하여야 한다.
4.4 공급업체의 초도품 승인 제출 (2) 품질관리담당은 고객승인시 결과를 관련팀에 통보하고 제출서류를 승인서류 관리
(1) 품질보증팀장은 초도품 제출수준을 파악 후 공급업체에 통보한다. 절차에 따라 유지관리한다.
(2) 공급업체는 초도품 승인 보증서를 작성하여 부품과 함께 부표1에 따라 관련 서류를 첨부하여 (3) 승인통보를 받은 관련팀은 양산진행, 개발이관 등의 업무를 실시한다.
품질보증팀에 제출하여야 한다. (4) 고객의 잠정 승인시 품질보증팀장은 잠정 승인기간과 문제점을 파악하여
업무회의를 통하여 잠정 승인기간 동안 제품 구분방법과 문제점 시정계획을 수립한다.
4.5 평가 단, 제품 구분시 고객의 별도요구가 있을시 고객의 요구에 따른다.
(1) 특별특성 지정 부품의 공정능력 평가는 『공정능력 운영 지침』에 따른다. (5) 고객 미승인시 품질관리담당은 문제점을 파악하고 최초 작성과 동일한 절차에 따라
(2) GAGE R&R 평가는 『측정시스템 평가 지침』에 따른다. 재작성한다.
(3) 특별특성 지정항목 이외의 항목은 n=5는 검사기준서의 전치수를 검사하고, 품질특성
''B Rank''이상의 항목은 n=30 이상을 검사하여 C=0 일 경우 승인한다. 4.9 초도품 승인 서류관리
(4) 특별특성 지정항목 이외의 부품이라도 ''B Rank'' 이상의 항목은 공정능력이 (1) 초도품 승인 관련서류는 품질보증팀에서 관리한다.
Ppk≤1.67 로서 공정개선이 요구될 경우 승인을 불허한다. (2) 구 모델 승인문서를 신 모델에 적용하는 경우(CARRY OVER), 구 모델 승인 문서 사본
(5) 품질평가는 만족하나 표준류나 게이지 등의 준비사항이 미완료된 경우 추진계획서를 을 신 모델 파일에 보관하여야 한다.
접수 후 검토 결과에 따라 품질보증팀장이 조건부 승인 할 수 있다. 이때 (3) 초도품 승인 대상 서류 중 제출되지 않은 서류는 고객의 요구가 있을 경우 즉시 사용
기한을 명시하여 기한 경과시에는 조건부 승인을 취소 할 수 있다. 할 수 있도록 유지관리하여야 한다.
