↓ (1) 품질향상 또는 생산성 향상을 위한 개선
(●) 해당팀장 4M변경 요청 (→) 4M변경 요청서 (2) 원가절감을 위한 개선
(3) 성능, 내구성, 조립성, 장착성 등의 향상을 위한 개선
↓ (4) 오기, 누락, 판독의 어려움 등의 개선
(●) 개발팀장 (→) 관련팀장 4M변경 검토 (→) 4M변경 요청서 (→) 4M변경 관리대장 (5) 시정 및 개선조치에 따른 공정변경 사항도 포함한다.
4.1.2 생산담당
↓ (1) 작업자 교체
(●) 개발팀장 (→) 고객 설계변경 요청 또는 4M변경 요청 (→) 4M변경 요청서(고객양식) (→) 설변 ECR 요청서(고객양식) (2) 생산설비 신설,교체,개조 및 유효설비 가동
(3) Lay-Out 변경 및 제조위치 변경
