페 이 지 3/4
4.1.3 개발담당 4.4 설변 접수 및 통보
도면변경(치수, 형상) 및 재질변경 4.4.1 개발담당은 당사 요청에 의한 설변적용인 경우 관련 설계출력 문서(도면,설변
4.1.4 구매담당 통보서등)를 접수하면 ''사양변경 접수대장''에 기록하고, 관련팀에 통보하여
공급업체 변경 및 공급업체의 생산조건 변경 적용시점이 관리되도록 한다.
4.4.2 개발담당은 고객의 설변요구사항인 경우 관련 설계출력문서(도면,설변통보서)를
4.2 4M 변경 요청 접수하면 ''사양변경 접수대장''에 기록하고 적용가능성,적용시점,재고 등에
4.2.1 4M 요청팀은 다음사항을 고려하여 ''4M 변경 의뢰서''로 4M 변경을 요청한다. 대해 접수후 10일이내 검토를 하여 적용불가시 고객과 협의 조정한다.
(1) 상기 4.1항의 변경 필요성에 대한 사유 (HKMC 4M변경 기준에 따른다) 4.4.3 설변 통보시, 관련 기술문서(도면,시방서등)를 첨부하여야 하며, 해당 문서의
(2) 변경 전, 후의 개선효과 비교 배포와 동시에 구본의 회수 및 폐기 여부를 관리한다.
(3) 변경 완료 및 적용에 대한 요청시점
4.5 고객승인
4.3 4M 변경 검토 및 조치 품질보증팀장은 공정 및 설계변경으로 인한 고객승인은 『양산부품 승인 업무규정』에
4.3.1 개발담당은 4M 변경 요청서를 접수하여 적용가능성을 검토하고, 설계변경이 따라 관련 자료를 준비하여 고객의 승인을 받는다.
필요한 경우 4.3.2 항에 따른 업무를 진행하고, 공정변경 사항인 경우 다음 업무를
진행한다. 4.6 후속조치
(1) 개발담당은 공정변경으로 인한 영향을 검토한 후 , 그 결과를 변경요청서에 기록하고 4.6.1 개발담당 및 해당팀 담당은 적용일자를 정확히 준수 및 적용이력을 관련문서 및
적용가능여부를 평가한다. 기록으로 관리한다.
(2) 개발담당은 영향평가 결과를 팀장에게 보고하고, 적용가능한 경우 고객의 4M변경 4.6.2 해당팀은 관련문서에 따라 적용되는 범위까지 주관업무를 수행한다.
신청서로 고객에게 통보하여 승인을 받은 후 적용될 수 있도록 한다. 4.6.3 해당팀은 4M 변경으로 영향을 받는 모든 기술문서(관리계획서,제조공정도,작업
4.3.2 개발담당은 설변요청 관련자료를 접수하고 다음항목을 조사, 분석한 자료를 첨부하여 표준서,검사기준서 및 기타문서)의 개정여부를 검토하고 필요 시, 4M 변경품 적용
팀장의 검토 및 대표이사의 승인을 받아 고객의 책임있는 담당자와 협의하고 설변에 시점 이전에 개정, 관리한다.
대한 고객승인을 받은 후 적용 후속업무를 이행한다. 4.6.4 품질담당은 적용 후 1~3개월 정도에 걸쳐, 품질현황을 모니터링하고 필요시
(1) 자재담당이 검토한 자재비 증감여부와 재고현황 및 처리방법 회의를 주관, 안정수준으로 개선한다.
(2) 개발담당이 자체적으로 검토한 설변 시의 변경 TOOL''G을 포함한 제조방법, 원가상의
문제점 여부 및 대응기간 5. 관련표준
(3) 생산담당이 검토한 현 생산계획과 적용 타당성 (1) 양산부품 승인업무 규정 (J-2100)
(4) 품질담당이 검토한 품질관리 사항 및 적용 타당성
품질경영 시스템 문 서 번 호 TPC - J - 3100
재,개정 일자 45047
