INSERT INTO regulation_sections (reg_code, section_title, section_body, sort_order)
SELECT 'J-3100', '4. 책임과 권한', '4.1 생산팀장
1) 생산방법이 변경시 생산방법 변경 요청
2) 해당시 표준류(작업표준 등)를 작성 및 유지
4.2 개발팀장
1) 신규설비, 교체, 개조 변경 요청 및 검토
2) 생산방법 변경에 필요한 설비 및 치공구 제작
3) 해당시 표준류(공정 FMEA)를 작성 및 유지
4.3 자재영업팀장
1)구매품 생산방법이 변경시 생산방법 변경 요청
2)외주업체가 변경시
4.4 품질경영팀장
1) 생산방법 변경 승인 및 결과 통보
2) 해당시 표준류(관리계획서)를 작성 및 유지
3) 생산방법 이력 작성 및 유지관리
4) 생산방법 변경사항 고객 통보, 승인 및 적용 통보', 14
WHERE NOT EXISTS (SELECT 1 FROM regulation_sections WHERE reg_code = 'J-3100' AND sort_order = 14);
INSERT INTO regulation_sections (reg_code, section_title, section_body, sort_order)
SELECT 'J-3100', '5. 업무 절차', '5.1 4M 변경관리의 일반사항
관련 팀은 다음의 사항이 실행되고 있음을 보정한다.
a) 고객 요구사항의 준수를 보장하는 검증 및 실현성 확인 타당성확인 활동을 규정하는 것
b) 실행 전에 변경사항을 타당성확인 하는 것
c) 관련된 리스크 분석의 증거를 문서화 하는 것
d) 검증 및 실현성 확인 타당성 확인의 기록을 보유하는 것
공급자에서 만들어진 것을 포함한 변경사항은 제조공정의 모든 변경에 영향을 타당성 확인
하기 위해 변경의 검증(부품 설계, 제조 위치 또는 제조공정에 대한 변경과 같은)을 위한
생산시험 가동을 요구하여야 할 것이다.
고객에 의해 요구되는 경우, 조직은 다음을 하여야 할 것이다.
e) 가장 최근 제품 승인 이후 모든 계획된 제품 실현변경을 고객에게 통보한다.
f) 변경의 실행에 앞서 문서화된 승인을 얻는다.
g) 생산시험 가동 및 새로운 제품 실현성 확인과 같은 추가적인 검증 또는 식별 요구사항을
완수한다.
5.2 생산방법 변경 승인대상
공장의 생산변경 승인 대상에 대한 기준은 아래와 같다.
단, 금형 교체, 공구 교환 등의 일상변경에 대해서는 생산방법 변경 승인대상에서 제외한다.
구 분 내용 구분 해당팀
작업자 *Line별 작업자가 대폭변경시(작업자 30%이상 교체) 생산팀
설비/치공구 *생산설비를 신규제작, 교체, 개조 할 경우 생산기술팀
*치공구 신규 제작 및 교체 할 경우 생산기술팀
*12개월 이상 유휴 설비를 사용시 생산팀
*설비 Lay -Out가 변경시 생산팀
재료 *원재료의 재질 및 성분이 변경시 개발팀
*1년 이상 경과한 장기 재고 사용시 생산관리팀
*품질에 영향을 미치는 부자재가 변경시 품질팀
방법 *작업방법, 순서가 변경시(수동⇒자동, 가공기준등) 생산팀
*외주선(부품, 소재, 임가공업체) 변경시 생산관리팀
*생산공장이 이전시(사내⇒외주 등) 생산팀
*신 치공구 적용시 개발팀
*KD품이 국산화시 개발팀
5.3 생산방법 변경사항 등록
1) 신청팀은 생산방법 변경사항이 발생시 생산방법 변경 관련팀 회의를 소집하여 고객 적용
대상 유/무, 적용 예정일, 변경추진 계획 등에 대한 일정계획을 수립한다.
2) 해당팀은 생산방법 변경에 대한 일정계획을 수립 후 "4M변경신청서"를 작성하여 담당자
및 계획일정을 기록 및 보관한다.
5.4 생산방법 변경사항 검토, 실행 및 승인
1) 해당팀은 생산방법 변경사항에 대해 검토를 하고 품질경영팀으로 승인을 요청한다.
2) 품질경영팀은 요청받은 4M 변경사항 및 품질보증상의 관련 예상 문제점을 종합 검토
하여 승인,승인 불가에 대한 정단한 사유를 기재하여 최종 판정을 하여 공장장이
최종 승인을 한다.
3) 품질경영팀장의 승인된 4M 변경요청 결과는 E-mail을 통하여 관련팀으로 통보하고 원본은
품질경영팀이 관리한다.
4) 품질경영팀은 4M 변경시 고객 요구사항의 준수를 보장하는 검증 및 실현성 확인을 첨부의
4M 변경 FLOW에 따라 실행한다.
5) 공급사의 5M변경도 4M 변경FLOW에 따라 검증과 실현성 확인을 수행한다.
6) 4M변경 사항이 발생시 품질경영팀은 관련된 리스크 분석을 실시하여 조치하고 기록을 보유
한다.
7) 4M 변경사항은 제조공정의 모든 변경에 영향을 타당성 확인을 위해 변경의 검증을 위한
생산시험가동을 실시한다.
5.5고객 양산부품 승인(PPAP)/초도품 승인(ISIR) 관리
1) 고객의 4M 변경대상은 반드시 적용전에 사내승인을 원칙으로 하며, 사내승인을 받지 못한
경우에는 생산방법 변경 요청은 자동 기각되며, "양산부품승인규정" 및 "외주품 승인지침
"에 따라 실시한다.
2) 품질경영팀은 고객의 4M 변경대상 기준에 따라 양산부품 승인(PPAP) 또는 초도품 승인
(ISIR)이 필요한 경우에는 고객이 지정한 매뉴얼에 따라 고객승인을 받은 후 이력관리를
한다.
5.6 사내 표준류 개정관리
관련팀(생산, 품질보증, 개발, 관리 등)는 생산방법 변경사항을 검토하여 해당되는 경우 관련
표준류(공정 FMEA, 관리계획서, 작업표준 등)를 개정하고 관리한다.
5.7 사내 양산적용 관리
1) 생산팀은 생산방법 변경품이 사내 양산적용이 되는 경우에는 식별을 하고 적용이력을 공정
검사 체크시트에 기록, 등록하고 보관한다.
2) 생산팀은 변경사항에 대해 작업자 교육을 실시한다.
5.8 고객 적용 통보 및 관리
품질경영팀은 고객에게 고객 적용일정을 통보하고 기록문서는 보관한다.
5.9 초도품 납품관리
관리팀은 고객에게 초도품을 납입시 고객이 지정한 방법으로 납품 Box에 식별을 하고
납품일자를 이력관리한다.', 15
WHERE NOT EXISTS (SELECT 1 FROM regulation_sections WHERE reg_code = 'J-3100' AND sort_order = 15);
