이 규정은 제품 DATA,제품도면의 접수,작성,보관 및 폐기에 적용한다.
2. 목적 (●) 각 사업부 개발팀장 도면접수 및 등록 (←)고객 도면(2D,3D) (→)도면관리대장
제품 DATA,제품도면의 작성울 체계화하고 보관 및 쉽게 찾아볼 수 있는
절차를 명확히 하여 도면 관리의 원활을 기하여 업무의 능률을 향상시키는데 있다. ↓
(●) 사용팀장/공급자 도면보관 및 활용 * 최신본 식별', 0
