SELECT 'J-4100', '3. 용어의 정의', '3.1 참고도면 또는 입수도면(DRAWING FOR REFERENCE) ↓
고객 또는 외부로 부터 입수한 단지 참고용으로 쓰이는 도면 (●) 각 사업부 개발팀장 (←) MDT 도면변경 관리 (●)4M변경관리 규정 ←변경된 고객 도면
3.2 샘플제작용 도면(DRAWING FOR MANUFACTURING SAMPLE) ↓
고객의 요구에 의한 SAMPLE제작, 평가 및 제출용 도면 (●) 각 사업부 개발팀장 (→) 해당팀장 도면 폐기 (→)도면관리대장 * 최신본 식별
3.3 양산용 도면(DRAWING FOR PRODUCTION) ↓
고객의 승인 완료 후 양산을 위한 양산 공급용 도면 (●) 각 사업부 개발팀장 도면 보존
3.4 조립도면(DRAWING FOR ASSEMBLY)
부품의 조립 방법 및 조립 시 크기, 공차, 조립후의 특성시험사양, 참고와 주의사항 5. 세부 절차
등을 명기한 조립후의 상태를 표기한 도면 5.1 도면관리 일반
(1) 당사의 모든 제품도면은 각 사업부 개발팀 주관으로 관리한다.
3.5 부품도면(DRAWING FOR PARTS) (2) 각 팀은 필요한 도면을 열람 및 사본 요청을 할수 있다.
조립전 부품들의 제작을 위한 세부 도면 (3) 도면은 최초 작성목적 및 용도에 맞게 사용한다.
(4) 도면은 관리를 위한 ''도면관리대장''에 등록하고 항상 유효본(최신본) 도면을 사용한다.
4. 업무 절차 (5) 도면은 각 사업부 개발팀장의 승인없이 무단복사, 사용할 수 없다.
고객도면의 접수, 등록 및 관리의 주관팀은 각 사업부 개발팀 이며, 업무절차는 다음과 같다.
