재,개정 일자 45047
도면관리 규정 개 정 번 호 5
페 이 지 3/3
5.2 도면접수 및 등록 5.5 도면의 폐기
개발담당은 고객으로부터 도면을 접수하면, 접수인을 스템핑한 후 ''도면관리대장''에 5.5.1 단종제품의 원도, 개발이 중지된 개발품의 원도에 대하여 개발담당은 각 사업부
등록하고, 바인더에 파일링한다. 개발팀장의 확인 후, 폐기한다.
단, 폐기결정된 원도 중 향후의 설계에 참조가치가 있는 도면은 별도 참고 도면철로
5.3 원도의 보관 및 활용 분리, 보관한다.
5.3.1 보관
(1) 각 사업부 개발팀장은 모든 제품 관련 도면에 대한 사내·외 기밀유지를 위하여 5.6 도면의 보존
대외비로 취급, 보관한다. 5.6.1 도면의 보존장소 및 보존환경은 화재, 수해, 해충 등에 대한 대책을 고려한 위치에
(2) 도면의 보관장소 및 보관환경은 화재, 수해, 해충 등에 대한 대책을 고려한 위치에 비치하여 재난의 발생 시, 즉시 반출할 수 있도록 한다.
비치하여 필요시, 즉시 반출할 수 있도록 보관한다. 5.6.2 폐기, 훼손된 도면은 절단(가로,세로 3cm이하) 또는 소각처리하고 원도에 대해서는
5.3.2 최신 유효도면의 구분 및 배포 다음의 요구기간을 참조하여 보존기간을 정한다.
(1) 각 사업부 개발팀 개발담당은 고객승인이 확정된 양산용 도면은 전부 유효도면이므로 (1) 제조물책임법(PL법) : 제품출하 후 10년+PL결함사고 발생 후 3년 이상을 요구함.
각 사업부 개발팀에서 통합관리하는 것을 원칙으로 하나 배포 필요시에는 ''도면관리대장''에 개발 시부터 산정시 최소 15~20년 이상의 보존기간 설정.
기록하고, 각 팀 또는 협력업체에 배포하며, 양산용 도면의 추가 등록이 있을시 또는 (2) IATF 16949규격 : 개발 시부터 제품 단종까지의 기간 +법적 서비스 기간 + 1~3년 이상의
설계변경이 있을 때마다 ''도면관리대장''을 갱신한 후 관련팀이 열람할 수 있도록 비치한다. 보존기간 설정.
(2) 도면철에 보관된 도면은 유효도면과 구도면의 구분을 명확히 식별할 수 있도록 5.6.3 도면 일치성 점검은 "도면 부품 일치성 점검 지침"에 기준하여 정기적 평가를 실시한다.
구도면에는 ''구본''에 식별표시를 한다.
5.3.3 도면의 보관 및 활용 6. 관련 표준
(1) 각 사업부 개발팀은 바인더 파일에 최근 배포된 유효 도면이 가장 위쪽(앞쪽)에서 확인될 수 (1) 4M변경관리규정(J-3100)
있도록 철하고 ''도면관리대장''에 E.O NO. 기재하여 구본과 혼동이 없도록 한다.
(2) 금형 및 장비, 제작, 샘플 또는 제품이 제작,자재준비 등 도면의 활용 시, 각 사업부 개발팀 7. 관련양식
에서 통보한 ''도면관리대장'' 상에서의 최신 유효본여부를 확인 후, 사용한다. (1) 도면관리대장 (J4100-01)
5.4 도면의 변경(REVISION)관리
5.4.1 원도의 변경은 『4M변경 관리 규정』에 관련팀 협의체(MDT)의 검토 및 승인 절차를
완료 후, 고객에게 변경요청한다.', 1
WHERE NOT EXISTS (SELECT 1 FROM regulation_sections WHERE reg_code = 'J-4100' AND sort_order = 1);
