책임(●) / 협조(→/←) 절 차 문서(●) / 기록(→/←) 4.2 품질 검사원
품질 검사원은 도면 & 부품 일치성 점검을 위한 계획 수립 및 점검 결과를 품질 팀장에게
보고해야 한다. 품질 검사원은 점검계획에 의거하여 해당 부품의 도면 일치성 확인 검사를
(●) 각 사업부 품질보증팀장 검사방법의 정의 (검사협정 및 관리계획서) 실시하며, 도면 기준에 준한 합부 판정을 실시한다.
↓ 4.3 외주업체 지도전담조직 담당자
(●) 각 사업부 품질보증팀장 검사 자원 확보 * 자격인증 관리 대장 외주업체 지도전담조직 담당자는 협력사 도면 & 부품 일치성 점검을 위한 계획 수립 및 점검
결과를 해당팀장에게 보고해야 한다.
(●) 각 사업부 품질보증팀장 검사 기준 설정 (→)검사 기준서 , ISIR 승인서 5. 세부 절차
5.1 품질 팀장은 도면 일치성 점검에 대한 자격요건을 갖춘 품질 검사원을 선정한다.
(●) 각 사업부 품질보증팀장 도면 일치성 검사실시 (→)검사성적서, 시험성적서 5.2 사내 및 외주 협력사 도면 & 부품 일치성 점검을 위한 계획을 수립 및 실시한다.
↓ 5.3 도면 & 부품 일치성 점검은 1회/분기 이상 실시함을 원칙으로 하되, 차종별 생산수량 및
품질안정성, F/PROOF강화 상태에 따라 변경 할 수 있다.
