5.4 도면 & 부품 일치성 점검 평가시트 활용 점검 실시 후 결과를 관련 부서에 통보한다.
5.5 점검 결과 문제점에 대해 차종별 품질 담당/검사자 및 외주업체 전담조직 담당자는 추진부문에
시정조치 요구를 한다.
5.6 추진부문은 개선안을 일정 내 (시정조치 요구 후 1주일 내) 회신하고 품질 검사원 및 외주협력사
전담조직 담당자는 개선안을 검증한다.
5.7 점검결과 및 개선안에 대해 주관팀장은 검토 승인 실시하고 , 품질 검사원은 이력관리 및 점검
개선현황에 대한 지속적인 모니터링을 실시 한다.
5.8 자체 및 외주 협력사 평가 결과에 대해서는 분기 1회 실시하고, 그 결과에 대해 품질팀장은
경영진에 정기적으로 보고 한다.', 2
