SELECT 'K-1100', '3. 관리 절차 ↓', '구매업무의 주관은 원소재 및 부자재 경영관리실 구매팀, 외주가공품/금형/지그 각 사업부 (●) 구매담당 실적 평가 및 사후관리 (→)발주 대비 입고실적
생산팀이며, 운영 절차는 다음과 같다.
책임(●) / 협조(→/←) 절 차 문서(●) / 기록(→/←) 4. 세부절차
4.1 개발단계
4.1.1 개발착수 품의
(●) 각사업부 개발팀장 부품개발 착수품의 (→)부품 개발 요청서 각 사업부 개발팀장은 수급자재로 확정되어 외주개발시 부품개발요청서, 부품LIST,
원재료 법/규제 요구사항 목록표를 작성하여 대표이사의 승인을 득한다.
↓ 4.1.2 견적접수
(●) 각사업부 개발팀장 (→) 협력업체 업체선정 및 단가결정 (●)협력업체관리규정 (→)단가결정품의서 (1) 각 사업부 개발팀장은 『협력업체 관리규정』에 따라 등록된 업체중 공급 가능한
2개 이상 업체에 관련 자료를 송부하여 견적을 요청한다. 단, 전문제작 설비보유 또는
↓ 제작의 기술보유(KNOW-HOW) 등으로 단일견적이 불가피한 경우는 예외로 한다.
(●) 구매담당 계 약 (→)기본거래계약서 (→)클레임보상협정서 (→)품질 확약서 (2) 기등록이 되어 있지 않은 업체는 『협력업체 관리 규정』에 따라 등록을 한 후 견적
을 접수한다.
↓ 4.1.3 업체선정
(●) 구매담당 자재구매계획 수립 →구매생산 계획 발주서 각 사업부 개발팀장은 업체에서 접수한 견적서의 내용을 검토후 적정한 가격,
업체능력, 원재료 법/규제 요구사항등을 고려하여 업체를 선정한다.
