페 이 지 3/4
4.1.4 초도샘플 시험 4.2.2 자재 발주
(1) 개발담당은 초도 샘플을 접수하여 『양산부품 승인업무 규정』에 따라 품질관리담당 (1) 구매담당은 등록업체에 한하여 구매품에 대한 자재사양, 포장,검사, 규제물질 등이
에게 검사 및 시험을 의뢰한다. 명기된 “구매규격서”를 팀장의 승인을 득한 후 배포한다.
(2) 불합격시에는 업체에 부적합 내용을 통보하여 조치하게 하고 재 샘플을 접수하여 (주) 규제물질에 대해서는 고객이나 국가의 산업안전 규정에 의해서 지정이 받은
상기 (1)항의 절차에 따라 재검사를 실시한다. 규제물질 LIST를 확보(고객, 업체의 MSDS:물질안전 보건자료), 목록을 작성하여
4.1.5 가격결정 납품업체에 사전에 배포하며, 자재입고시 규제물질의 사용여부를 확인한다.
(1) 각 사업부 개발팀장은 선정된 업체에 부품의 가단가를 적용하여 대표이사의 품의를 만약, 사용하고자 할때는 반드시 고객 및 안전관리 담당에게 사전승인을 득한
득한 후 부품개발을 착수하고, 관련 자료를 구매담당에게 송부한다. 후 사용하여야 하며 규제물질에 대한 취급 절차는 『자재관리규정』에 따른다.
(2) 각 사업부 개발팀장은 고객과 제품 가격이 결정되면 구매담당에게 송부하고, 구매담당은 (2) 구매담당은 고객이 지정하거나 승인한 자재에 대해서는 등록업체 목록을 확인하여
협력업체와 협의를 통하여 서로의 이해와 납득 가능한 범위내에서 부품 가격을 결정한다. 등록된 업체에 구매를 해야한다.
(3) 구매담당은 업체와 결정된 가격을 협력업체 단가 결정 품의서를 작성하여 대표이사의 (3) 구매담당은 등록업체에 한하여 차년도 자재 소요예상량을 통보한다.
승인을 득한다. (4) 구매담당은 매월말 등록업체 LIST를 참고하여 발주량 및 구매사양이 명기된 익월
4.1.6 계 약 예상구매 발주서(Forecast Order)를 작성하여 팀장의 결재를 득한 후 업체에 통보
구매담당은 협력업체와 기본거래계약서를 체결(신규업체일 경우)하고, 품질관리담당은 (Fax/우편)한다.
초도품 승인후 협력업체와 품목별로 검사협정을 체결한다. (주) 발주서에는 당사의 주문요구 사항이 나타나도록 자재번호, 품명, 규격, 수량,
가격, 재질, 납기등의 사항이 포함되도록 한다.
4.2 양산단계 (5) 구매담당은 협력업체에 구매 규격서, 작업표준, 도면 등을 배포할 경우 해당
4.2.1 구매계획수립 관리대장에 배포내역등을 등재, 관리하며 변동사항이 있을 경우 최신본을
(1) 구매담당은 영업팀의 월판매계획, 생산팀의 월 생산계획을 접수한 후 재고현황, 송부하여 유효본 관리를 하게한다.
사용예정량, 자금사정등을 고려하여 ''월 자재 수급계획''을 수립한다. 4.2.3 발주 관리
(2) 생산팀의 인원, 제조단가, 설비등의 생산능력등으로 제조 라인의 일부 물량을 외주 (1) 구매담당은 생산내역을 확인하여 업체별 일일 입고지시를 한다. 발주/입고현황을
처리하는 경우는 승인된 협력업체를 선정하여 품의서를 작성하여 대표이사 승인후 ''자재관리 대장(전산양식)''에 기록, 관리한다.
처리한다. 단, 미승인업체는 『협력업체 관리규정』에 따라 선정 평가후 적격하다고 (2) 발주에 따른 납기에 문제가 예상될 경우 관련팀에 통보하여 생산 및 고객의 납기에
판단시 외주처리 한다. 차질이 발생되지 않도록 조치 하여야 한다.
(3) 원,부자재가 고객의 유,무상 지급품인 경우 고객발주량을 고려하여 매월''사급 신청서''를 4.2.4 입고 및 검사
작성하여 고객에게 송부한다. (1) 구매담당은 거래처로부터 물품이 입고되면, 품질보증팀의 입고담당 검사원에게
검사의뢰를 하며 세부사항은 『검사업무 규정』에 따른다.
품질경영 시스템 문 서 번 호 TPC - K - 1100
재,개정 일자 45047
구매업무 규정 개 정 번 호 5
페 이 지 4/4
(2) 구매담당은 거래명세서 검수란에 검사원의 싸인을 확인하고 검수를 실시, 합격품일 (2) 비정기지불
경우 『자재 관리 규정』에 따라 하역 및 적재하고, 부적합품일 경우에는 구매담당은 자재가 입고된후에 업체로부터 세금계산서를 접수하여 ''지출결의서''를
『부적합품 관리 규정』에 따라 처리한다. 작성하고 대표이사의 승인을 득한 후 경리담당에게 송부한다.
(3) 구매담당은 고객 또는 공급자가 협력업체의 입고품에 대해 실사평가를 원할 경우, (3) 기타 자재의 대금지불
업체에 출장검사를 실시할 수 있다. 계약 또는 발주서상의 대금지불조건에 따른다.
4.2.5 월 실적평가 및 사후관리
(1) 구매담당은 매월초에 전월의 업체별 납품실적, 초과운임 및 재고현황 등을 분석하여 5. 관련 표준
자재업무 보고서를 작성, 팀장의 결재를 득한 후 관리한다. (1) 양산부품 승인업무 규정 (J-2100)
(2) 구매담당은 월 구매실적 평가시 정기(부정기)실적평가 조치에 대한 진행사항을 확인 (2) 검사 업무 규정 (L-2100)
하며, 이에 따르는 업체개발 및 조치사항은 『협력업체 관리규정』에 따라 처리한다. (3) 협력업체 관리 규정 (K-1200)
(3) 구매담당은 구매실적 평가서의 결과에 따라 대금지불조건, 발주량 등의 업체별로 (4) 자재관리 규정 (K-2100)
차등을 두어 업체에 100% 납기준수를 유도한다. (5) 부적합품 관리 규정 (B-1100)
(4) 각 사업부 생산팀의 외주가공품 구매담당은 협력업체의 부품품질 적합성과 납기 관련 (6) 리스크 관리 규정(A-8100)
리스크관리 절차에 따라 리스크를 분석하여 이에 따른 조치를 하여야 한다.
4.2.6 크레임처리 6. 관련양식
(1) 구매담당은 자재결품 및 품질문제로 인하여 회사에 손실이 발생되었을 경우 생산 (1) 원자재 입고 요청서 (K1100-01)
담당 및 품질관리담당으로 부터 자료를 통보받아 업체에 크레임을 제기한다. (2) 원소재 생산 의뢰서 (K1100-02)
