이사의 결재를 득한후 경리담당에게 대금의뢰 하며, 경리담당은 회사가 정한 일자에 (9) 품질 보증 협정서 (K1100-09)
대금을 지불한다. (10) 원재료 법_규제 요구사항 목록표 (K1100-10)', 2
