선정하고, 거래함으로서 업체간 경쟁심 고취 및 가격, 납기의 최적화및 외주품질을 책임(●) / 협조(→/←) 절 차 문서(●) / 기록(→/←)
확보하는데 그 목적이 있다.
3. 용어의 정의 (●) 주관팀장 선정 필요성 파악
3.1 협력 업체
회사의 도면과 시방서에 따라 원.부자재를 생산하여 공급하는 업체와 납품 운송 ↓
용역업체,외주가공업체,JIG,제작,금형제작 업체를 말한다. (●) 주관팀장 (→) 협력업체 선정평가 (→)업체실태조사서 (→)업체 평가표(체제)
: 당사에 부품/자재를 공급하는 타 사업부도 협력업체 군으로 포함되나, 별도의 관리
체계에 따른다(각 항목 중 "타 사업부 실적 체제 평가표" 내용 참조) ↓
3.2 등록 업체 (●) 주관팀장 (→) 대표이사 업체등록 (→)협력업체등록대장
구매할 외주자재의 품질보증과 안정적 공급을 위해 규정된 절차에 따라 업체평가를
실시 그 자격이 승인되어 회사와의 거래대상 업체로 등록된 업체를 말한다. ↓
(●) 주관팀장 (→) 협력업체 기본계약 체결 (→)기본거래계약서 (→)클레임보상협정서 (→)품질 확약서
3.3 협력업체 평가요원
업체실태조사 및 평가를 실시함에 있어 실제로 해당업무를 수행할수 있도록 책임을 ↓
부여 받은자를 말한다. (●) 주관팀장 샘플 평가 (●)양산부품 승인업무규정
3.4 실태조사 ↓
등록을 필요로 하는 신규업체에 대해 일정 수준의 자격요건을 맞추고 있는지의 여부 (●) 주관팀장 사후관리 (→)협력업체평가계획서 (→)협력업체평가표 (→)평가보고서
를 확보하기 위하여 해당업체를 방문하거나 평가서를 통해 조사하는 행위를 말한다.
