5.1 협력업체의 적용범위 (6) 기존업체가 품질문제가 다발하고 개선이 극히 미흡한 경우
(1) 원자재업체 : 제품의 구성요소중 중요부분을(가격, 구성요건) 차지하는 원자재를 (7) 기존업체가 납기지연이 빈번한 경우
공급하는 업체로써, 예를 들면 생산용도의 "조관업체"가 있다.
(2) 부자재업체 : 제품을 제작하는데 간접적으로 소요되는 자재로서 용접자재등을 5.4 협력업체 추천
공급하는 업체 (EX:용접봉,BOLT.NUT,SEALER 등) 신규업체와 거래를 해야할 필요성이 있는 팀장은 추천업체를 평가선정 주관팀으로
(3) 외주가공업체 : 부품의 일부를 제작(A''SSY) 입고하거나 원자재 사급에 의해서 외주처에서 통보하여야 하고 업체 추천시 다음의 내용을 고려 하여 추천 하여야한다.
입고되는 자재를 공급하는 업체 (EX:PRESS물,용접물 등) (1) 제조가공 경험이 풍부하고 품질보증 및 공정관리가 되어 있는 업체
(4) JIG제작업체 : 부품을 제작하기 위한 JIG를 제작,공급하는 업체 (2) 노사관계 및 재무구조가 양호한 업체
(5) 검교정업체 : 계측기 검교정하는 업체 (3) 개발품에 대하여 적극적인 자세를 가진 업체
(4) 품질,납기,원가관리에 대하여 관리자와 경영자의 관심도가 양호한 업쳬
5.2 협력업체 관리의 주관팀 및 평가방법 (5) 우수한 설비 및 시험기구를 보유한 업체
협력업체 구분 주관팀 평 가 방 법 (6) 품질시스템 인증 업체 (IATF / ISO / KS등)
신 규 선 정(최초) 사 후 관 리(년 1회)
