페 이 지 4/6
(2) 심의결과 협력업체 등급 평가표에서 70점이상 이상된 업체를 선정한다. 5.7 특례적용
단, 원자재 업체는 고객에게 등록된 협력업체에 한하여 5.7항 특례적용에 따라 신규업체 다음의 경우는 일반현황 조사(업체 실태조사)만하고, 신규업체 선정평가를 제외한다.
선정평가 및 사후평가를 제외 한다. (1) 부자재업체
(비고) 당사 타 사업부는 QM부서에서 진행하는 정기평가결과와 타 사업부에서의 사양검토 (2) 해당업체에서만 공급 가능한 수입품 및 특수한 물품 또는 용역의 경우
(제조타당성검토) 결과를 기반으로 평가된다 (품질 및 납기관련 리스크분석 포함) (3) 고객에게 등록된 원자재업체 (사급자재)
(3) 고객이 공급업체 또는 특정자재를 지정한 경우 고객과 공급업체간의 계약 내용에 준하여 대응 (4) A/S 외주가공업체
한다.
㈜ 규제물질에 대해서는 고객이나 국가의 산업안전 규정에 의해서 지정이 될 경우 5.8 협력업체 평가 요원 자격기준
구매담당은 규제물질 LIST(고객, 업체의 MSDS:물질안전 보건자료)를 확보하여 협력업체 평가요원의 자격기준은 『사내 자격관리 규정』에 따른다.
목록을 작성하고 납품업체에 사전에 배포하며, 자재입고시 규제물질의 사용 여부를
확인 한다. 만약, 사용하고자 할 경우에는 반드시 고객 및 안전관리 담당에게 5.9 기본계약 체결
사전에 승인을 득해야 한다. 평가 결과 적격업체로 선정되면 주관팀장은 필요한 경우 기본거래계약서 / 크레임 보상
협정서/품질확약서을 체결한다.
5.6 등록 (비고) 타 사업부와의 거래관계에서는 본 게약체결을 생략 할 수 있다.
(1) 모든 양산용 자재/부품/임가공은 승인 된 업체와 승인된 자재/부품만의 적용관리를 위하여
별도의 승인업체와 "승인자재목록(AVL/AML)"을 유지하여야 한다. 5.10 샘플평가 및 승인
(2) 본 목록에는 업체별 공급리스크와 자재/부품별 품질 리스크가 분류되고 이러한 리스크와 주관팀장은 필요한 경우 품질 시스템 평가 결과 적격업체에 한하여 『양산부품 승인
성과에 근거하여 협력업체 관리계획이 수립되어야 한다. 승인업무 규정』따라 샘플 평가를 하여 승인한다 (타 사업부 거래관계에서도 적용필요)
(3) 거래중인 외부 공급사들은 매년 성과와 리스크가 평가되고 업데이트 되어야 한다.
(4) 주관팀장은 조사된 내용을 분석하고 회사의 협력업체로 적합하다고 판정된 경우 5.11 사후관리
"업체실태 조사서"에 체크시트를 첨부하여 대표이사의 승인을 득한다. 5.11.1 협력업체 품질시스템 개발
(5) 주관팀장은 평가지적사항 및 의견을 포함한 평가결과(협력업체 평가표)를 업체로 각 사업부 팀장은 매년 협력업체의 품질경영시스템을 수준을 조사하고 다음의 목표를
통보한다. 가지고 품질경영시스템이 향상되도록 유도하여야 한다.
(6) 부적합으로 판단된 업체는 부적합 사항에 대하여 향후 개선대책을 수립하여 대표이사의 (1) 1차 ISO 시스템 인증 (ISO9001 & ISO14001) 또는 KS인증
결재를 득한후 주관팀으로 송부하고, 개선완료시 업체평가 선정 주관팀으로 재등록을 (2) 2차 IATF 16949 시스템에 준하는 관리
요청한다. (3) 3차 IATF 16949 인증
(비고) 타 사업부는 "업체 실태조사서"대신에 내부 정기평가 결과로 대체한다.
