재,개정 일자 45821
협력업체 관리 규정 개 정 번 호 8
페 이 지 5/6
5.11.2 사후 평가계획 수립 5.11.5 등급 평가 결과의 적용
주관팀장은 아래사항을 참조하여 년1회 "협력업체 평가계획서"을 수립하여 각 사업부 구매팀장은 년1회 종합평가 결과의 확정된 등급에 따라 INCENTIVE 또는
대표이사의 승인을 받는다. 단, 금형,지그 등 제작업체는 별도의 사후 평가를 실시 PENALTY를 아래의 등급별 조치사항과 같이 적용한다.
하지 않고 주관팀에서 신규 프로젝트 수행시 기 시행한 프로젝트의 실적 등을 고려 단, 평가결과의 적용은 경영방침에 의거 변경될 수 있다.
한다. 등급 등급별 조치사항
(타 사업부는 QM부서가 진행하는 정기평가 결과를 근거로 "타 사업부 실적체제 평가표" A등급 신규발주 최우선 적용 -각종 혜택 우선부여, 체제 평가 면제
작성하여 대체 한다.) B등급 신규발주 우선적용 -각종 혜택 우선부여
5.11.3 평가실시 C등급 변경없음 -1,2등급으로 상승되도록 지원 및 지도
(1) 각 사업부 주관팀장은 평가계획에 따라 "협력업체 평가표(체제,실적)"의 각 항목별로 D등급 물류조정검토 -
실시한다. 평가시 관련팀의 협조를 받아 시행할 수 있다. 5.11.6 조치사항
(2)평가시 인증서 갱신여부 확인 및 갱신된 최신본을 접수하여 평가서에 첨부하여야 하며. 각 사업부 구매팀장은 분기별 평가되는 납기 및 품질지수의 평가결과에 대하여 아래와
인증서 갱신이 확인될시 업체 현황내 인증 기간등 변경사항을 기록관리하여야 한다. 같은 조치를 취하며, 지속적인 개선이 이루어지도록 필요한 조치를 취한다.
(3) 사후 평가결과 등급부여기준은 다음과 같다. (1) 각 사업부 구매팀장은 분기 품질지수 평가순위 하위업체에 대하여 ''개선대책서''를
등급 등급 부여 기준 INCENTIVE / PENALTY 제출받고 또한 해당업체로 하여금 재발방지대책을 발표하게 하고 개선이 완료될 때까지
A등급 90 ~ 100점 우수 협력업체 신차 개발 우선권 부여, 체제평가 제외 지속적인 개선확인을 실시한다.
B등급 80 ~ 89 점 거래가능 협력업체 신차 개발 우선권 부여 (2) 각 사업부 구매팀장은 연속하여 등급이 3회이상 하락하는 업체에 대해서 업체 개선결과에
C등급 70 ~ 79 점 개선대상 협력업체 신차 개발 참여 가능 대한 협의를 실시하고 그 결과 협력이 불충분한 업체로 판단될시 대표이사의 승인을
D등급 70점 이하 거래불가 협력업체 1회에 한하여 재평가 득하여 발주전환을 결정하고 해당업체에 통보한다.
(4) 2항. 갱신된 인증서 최신본 당사 미 제출시 평가 점수가 높아도 D등급 판정 후 협력업체 통보
및 당사 유관부서 정보 공유하여야 하며, 갱신된 인증서 최신본 미 제출 협력업체에 대하여 5.12 협력업체 현황 변경
재 평가를 실시하여야한다. (재평가 실시때까지 미 제출시 내부 경영진 보고 후 거래조정 실시) 5.12.1 주관팀장은 업체등록과 관련된 문서를 유지,관리하며 업체현황이 변경될 시에는
(5) 평가점수가 70점이하 일 경우 개선대책을 접수 후 1회에 한하여 재 평가를 실시할 수 있다. 변경된내용을 접수하여 변경,관리한다.
재 평가시 평가검수가 70점이하일 경우 경영진 보고 후 거래조정을 실시한다. 5.12.2 주관팀장은 승인,등록된 협력업체중 다음사항에 해당되는 업체는 등록을
취소할 수 있으며, 취소 사유를 해당 협력업체에 통보한다.
5.11.4 평가 결과 보고 (1) 계약이행을 위반하여 거래가 불가능하다고인정되는 경우
각 사업부 주관팀장은 "협력업체 평가표(체제,실적)"를 작성하여 대표이사의 승인를 (2) 협력업체 평가에 의해 당사의 구매요건을 현저히 만족시키지 못한다고 인정되는 경우
득하고 사본을 관련팀에 배포한다. (3) 기타 사유에 의거 거래를 지속하는 것이 불합리하다고 인정되는 경우
