(●) 주관팀장 자재내역 확인 가. 거래명세서 나. 수입검사성적서
(5)품질보증팀 검사담당은 자재가 입고되면 자재의 내역을 확인하여 『검사업무 규정』에
↓ 따라 자재입고검사를 실시한다.
