3)생산팀 담당자는 구매팀 담당자에게서 접수받은 MSDS성적서를 현장에 게시하고, 성적서 (1) 배치에 융통성이 있어야 한다.
내 그림문자와 실뭉의 그림문자 일치여부를 확인한다. (2) 식별검사가 용이해야 한다.
4)생산팀 담당자는 성적서와 실물 보관용기의 그림문자가 상이할경우 구매팀 담당자에게 (3) 자재가 녹이 발생되지 않아야 한다.
