4.2 검사결과 판정 를 수립, 기준에 준하여 관리한다.
(1) 품질보증팀 검사담당은 합격품일 경우에는 거래명세서에 싸인을 한다. (4) 적재단수는 4단이하 또는 1m 20Cm 이하로 적재하여야 한다.
(2) 불합격된 물품인 경우 거래명세서에 불합격 표시를 하여 구매팀 자재담당에게 통보 4,5,3 자재 관리
하며, 『부적합품 관리 규정』에 의하여 처리한다. (1)주관팀 자재담당은 규제물질에 대해서는 MSDS 자료를 비치하고, 일반자재와 격리하여
(3) 일반 구매품목에 이상이 있을 경우 즉시 반품처리한다. 보관, 관리하며 규제물질 사용자재표시에 대한 고객의 요구가 있을시에는 출하시
