(4) 주관팀 자재담당은 보관중인 물품중에서 매 반기말 6개월이상 고정적으로 사용하지 6. 관련양식
않는 불용자재에 대해서는 “장기 재고관리 현황”에 기재하고 다음의 처리 방법에 따라 (1) 장기재고 관리 현황 (K2100-01)
처리한다. (2) 원소재 입출고 관리대장 - 전산양식 (K2100-02)
가. 주관팀 자재담당은 조사한 장기 적체품 현황을 해당담당에게 통보하여 사용여부를 확인한다. (3) 부품 입출고 관리대장 - 전산양식 (K2100-03)
나. 주관팀 자재담당은 월 1회 "장기 재고 점검대장"을 이용 점검을 실시한다. (4) 재고조사표 (K2100-04)
다. 자재담당은 해당물품의 외관 및 열화검사를 결과에 따라 이상이 없으면 "장기 재고 식별표"를 (5) 장기 재고 점검대장 (K2100-05)
부착하고, 부적합품 발견시는“부적합보고서”로 해당 사업부 자재담당에 통보한다. (6) 선입,선출 관리 기준서 (K2100-06)
(주) 열화 확인을 위한 검사는 해당자재 또는 제품 검사규격을 준용한다. (7)장기 재고 관리 기준서 (K2100-07)
라. 해당 사업부 자재담당자는 재 검사결과 불량인 경우 제품 폐기 기안을 대표이사까지 상신, (8)생산수량 대비 소모품 월소요량 및 안전재고 (K2100-08)
승인을 득해야 한다. (9)소모품 사양 및 공급처 지정 현황 (K2100-09)
마. 불용 또는 불량 판정되어 폐기 승인된 장기 적체품을 폐기/매각/재활용 처리한다.
바. 주관팀 자재담당은 폐기/매각/재활용 처리 후 관련 증빙자료를 경리팀에 송부한다.
사. 장기재고/불용재고에 대한 식별은 부표1을 참조하여, 자재담당은 식별관리를 하여야한다.
4.6 공정 잔량 자재 관리
(1) 해당 사업부 자재담당은 월 1회이상 불시 공정 투입 후 잔량품 관리에 대하여 점검을 실시하고
관리 기준(지정위치 보관, 품명, 품번, 잔량등)을 만족하지 못할시 부적합 통보서를 해당팀에
발송, 개선을 진행며, "지속적 개선업무 규정"에 의해 처리한다.
4.7 부적합품 처리
해당 사업부 자재담당은 주관팀 자재담당으로부터 부적합 물품을 인수받아 부적합 상태를 확인
한 후 합격자재와 격리하여 관리하며 세부적인 사항은 『부적합품 관리규정』에 따른다.', 1
