SELECT 'L-1100', '2. 목적', '이 규정은 생산설비의 유지 및 관리절차를 명확히 함으로서 설비가 최적의 성능을 발휘 4. 책임과 권한
하여 높은 생산효율과 공정의 안정성을 유지할 수 있도록 함을 목적으로 한다. 설비보전 목적을 달성하기 위하여 생산팀장은 다음의 업무를 가지며 이의 이행에 대한
책임을 진다.
3. 용어의 정의 (1) 생산설비 보전목표, 보전계획 수립 및 실시
