페 이 지 3/4
5.2 공법검토 5.4.2 TRY-OUT 실시
(1) 개발팀장은 신규 개발인 경우 도면 및 관련 자료를 입수하여 지그구조,재질,공정 등 (1) 개발팀장은 필요시 회의를 소집하여 아래의 사항을 확인한 후 TRY-OUT 일정을
사양을 결정하고 "공법 검토서"를 작성한다. 조정/확정하여 실시한다.
(2) 작성된 "공법 검토서"를 관련 부서 회람 검토 후 제작의뢰를 진행 한다. 가. 생산팀 : 적용장비의 사용가능 여부,직원인원의 배치상태, 원자재 준비상태
나. 품질보증팀 : 검사방법 및 검사준비 상태
5.3 제작의뢰/제작 (2) 개발팀장은 TRY-OUT 실시 결과를 "회의록"에 기록하고 문제점이 발생된 경우 시정
5.3.1 제작의뢰 시정조치되도록 조치한다.
(1) 개발팀장은 사내·외작 결정을 한 후 외작품은 『협력업체 관리규정』의 절차에 (3) TRY-OUT 결과 문제점이 없으면 샘플을 품질보증팀에 의뢰한다.
따라 기 등록된 업체로 부터 견적을 접수한다 (2) 품질보증당당은 도면 및 검사기준서에 준하여 검사를 실시하고, 그 결과를 검사성적서에
(2) 개발팀장은 견적내용을 검토하여 업체를 선정 후 품의서를 작성하여 대표이사의 작성하여 팀장의 승인을 득한 후 생산팀에 통보한다.(제작업체 3차원 측정 데이터로 대체가능)
승인을 득한 후 선정된 제작업체에 발주한다. (3) 개발팀장은 판정결과에 따라 문제점을 분석하여 관련팀 및 외주 지그제작업체와
(3) 지그개발이 자체 제작일 경우 생산기술팀에 업무 협조 요청하여 제작한다. 협의하여 개선대책을 수립하고 문제점을 해결한다.
5.3.2 제작
(1) 외주 제작업체는 의뢰된 사양을 근거로 입고 요구일내 제작한다. 5.5 지그등록 및 이관
(2) 지그의 사내 제작은 생산기술팀에서 제작하며 입고,불출,사용,반납,폐기의 절차는 5.5.1 등록
외주제작품과 동일하게 처리한다. (1) 개발팀장은 TRY-OUT 결과 합격된 지그에 대하여 다음과 같이 관리번호를 부여하고
(3) 고객지급 지그인 경우의 처리 절차도 회사에서 제작하는 경우의 절차와 동일하다. "지그관리대장" 및 "지그이력카드"를 작성한다.
5.4 지그입고 검사 (1)(2)(3) : 회사약호(TPC)
개발팀장은 지그제작이 완료되면 지그를 입고시키거나 지그제작업체를 방문하여 (4) : 지그(J)
지그검사 기준에 따라 검사를 실시하여 검사결과를 기록한다. (5)(6) : 설비약호 2자리
(7)(8) : 일련번호
5.4 TRY-OUT (2) 고객지급 지그일 경우에는 지그관리대장 및 이력카드에 "고객지급품"이라고 명기한다.
5.4.1 원자재 준비 5.5.2 이관
개발팀장은 필요한 원자재 규격, 재질, 소요량 등을 파악하여 구매팀에 구매의뢰 한다. (1) 개발팀장은 고객의 지침에 따라 지그도색 및 명판을 부착하여 지그이력카드 및 관련
자료를 생산팀에 이관하여 관리토록 한다.
