(2) 개발팀장은 외주 양산지그에 대해서는 협력업체에 이관시 "지그 사용대차 계약서"와 고객에게 4M변경 신청을 하여 승인을 득한다.
"지그인수보관증"을 작성하여 이관하고 공증하여 보관한다. 5.7.3 폐기
(1) 폐 지그 처리
5.6. 사용,보관 및 보존 생산팀장은 사용불가로 반납받은 폐 지그는 식별표시하여 지정장소에 보관하고,
5.6.1 양산지그는 생산관리 담당자는 재고 파악이 용이하도록 현황판을 게시한다. 대표이사의 승인을 득한 후 폐기한다.
