5.6.3 생산관리 담당은 사용중인 지그에 대해 매년 초 지그 정기점검 계획을 수립하여 설계/공정변경 등의 원인으로 발생된 불용지그는 식별표시하여 지정장소에 보관하고,
점검계획에 따라 "지그정기점검표"에 따라 점검을 실시하고 점검결과를 기록한다. 매각처리를 기본으로 하되 불가능할 경우 폐 지그와 동일하게 폐기처리한다.
5.6.4 지그점검 결과 문제가 발생한 경우 자체 또는 업체를 선정하여 수리를 실시하고
수리 결과를 이력카드에 이력으로 관리 한다. 6. 관련표준
5.6.5 생산팀에서는 지그를 사용중 문제가 발생되면 기안서 작성 내부 사업부장에게 결재 승인 (1) 개발업무 규정(J-1100)
