3.7 시료수
2. 목적 로트로부터 검사를 위해 채취한 샘플링검사 단위를 말한다.
이 규정은 검사업무에 대한 사항을 규정함으로써 효율적이고 정확한 검사를 통해
품질보증과 고객의 만족을 도모하는 데 있다. 3.8 검사기준서
당사의 제품사양 또는 재료규격에 표시된 품질특성에 대하여 검사항목, 검사방법 및
3. 용어의 정의 기타 검사에 관련된 각종 사항을 명확히 한 표준을 말한다.
3.1 수입검사
협력업체에서 입고되는 부품 및 반제품에 대하여 해당 검사 규격에 의거하여 검사 4. 책임과 권한
하는 것을 말한다. 4.1 품질보증팀장
(1) 품질계획업무 결과에 따라 검사단계를 결정하고 필요한 검사기준을 문서화하여
3.2 공정검사 개정 관리할 책임이 있다.
공정진행중인 재공품에 대하여 작업자가 자주검사를 실시하는 것과 품질관리담당이 매일 (2) 당사에서 사용되는 자재 및 완성품에 대해 검사를 정해진 검사기준에 따라 실행하며
정기적으로 순회검사하는 것을 공정검사라 한다 제품의 품질을 보증할 책임이 있다.
(3) 부적합품 발생시 해당팀장으로 하여금 재발방지 및 개선토록 할 책임이 있다.
3.3 최종검사 (4)「사내 자격관리 규정」에 따라 자격이 부여된 자에게 검사업무를 수행토록 하여야
생산공정의 최종단계에서 행해지며 완성된 제품이 제품검사기준에 적합한지의 여부를 할 책임이 있다.
검사하는 행위를 말한다. (5) 고객이 요구하는 검사의 실시와 결과(성적서등)를 제공할 책임이 있다.
3.4 샘플링검사 4.2 각 사업부 생산팀장
지정된 규격에 따른 검사기준에 명기된 시료의 검사수량을 샘플링하여, 검사를 (1) 각 공정별 작업표준을 설정하고, 작업자로 하여금 작업표준에 따라 자주검사를
실시하고 그 결과를 판정기준과 비교하여 합,부를 판정하는 행위를 말한다. 실시하도록 하여야 할 책임이 있다.
(2) 부적합품 발생시 부적합품에 대해 개선하여야 할 책임이 있다.
3.5 전수검사
대상로트 전체를 검사하는 것을 말한다.
