합부판정기준, 필요시 사용계측기명, 샘플링 기준, 검사결과의 기록등 구체적인 (5) 품질보증팀장은 다음의 경우는 ''검사 성적서"를 작성하여 검사 결과를 기록유지 한다.
검사관련 정보를 파악하여 한다. 가. 생산 LINE에서 부적합품이 발생한 경우
