5.2 수입검사
5.2.1 일반사항 5.2.4 검사결과의 처리
수입검사는 다음의 한가지 이상의 검사방법을 적용하여 실시하여야 한다. 수입검사 결과 발생된 부적합품은 『부적합품 처리 규정』에 따라 처리한다.
(1) 적합성이 판명된 통계적 테이터의 입수 5.2.5 긴급품 선투입
(2) 입고검사 및 시험 납기상의 문제등으로 긴급품이 입고된 경우 해당팀은 긴급투입후 품명, 수량등을
(3) 공인기관에 의뢰하여 평가 품질보증팀에 통보하여야 하며, 품질보증팀장은 거래명세서 및 검사일지에
(4) 협력업체의 품질보증서 또는 성적서 입수 긴급투입품임을 알수 있도록 하고 검사결과 문제발생시 회수 가능하도록 하여야 한다.
(5) 수용 가능한 품질성 및 기록과 외주업체 현장에 실시한 2자, 3자 심사 또는 감사결과
5.2.2 수입검사 의뢰
협력업체 납품담당자 또는 자재담당자는 부품 입고시 거래명세서로 검사담당에게
검사의뢰를 하여야 한다.
