자재입고시 협력사로부터 받은 성적서를 기준으로 동일한 항목 확인하여 합격, 불합격 5.5 정기검사 및 최종제품 감사(AUDIT)
판단하며, 합격시 " 합격스티커 또는 당사 식별표" 를 부착하고 생산라인 및 자재보관장으로 정기검사 및 최종제품 감사는 『공정 및 제품심사 규정』에 따라 실시하고, 제품에 대한
