5.3 공정검사 6. 검사의 외부의뢰
5.3.1 검사실시 당사에서 시험 또는 검사할 수 없는 항목과 외부기관의 확인을 필요로 하는 사항에
공정검사는 작업자가 실시하는 자주검사와 품질관리담당이 실시하는 순회검사로 대하여서는 ISO/IEC 17025에 따라 인증된 연구소, 검사기관, 관련업체 등에 시험의뢰한다.
구분하여 실시한다.
(1) 작업자가 실시하는 자주검사는 "작업표준 및 기준서"에 설정된 항목, 순서 준하여 검사를 7. 검사 및 시험장비
실시하여 "자주검사 체크시트" 에 검사결과를 기록한다. 검사 및 시험장비의 관리는 『계측기 관리규정』에 따른다.
(2) 품질관리담당은 중요품목에 대해 ''순회검사 표준''에 따라 매일 아침 9시에 검사를 실시하고
검사결과를 순회검사 일지에 기록 후 팀장에게 결재 승인을 받도록 한다. 8. 부적합품 처리
부적합품의 처리는 『부적합품 관리규정』에 따른다.
5.3.2 검사결과의 처리
(1) 합격품 9. 품질평가 및 조치
작업자는 자주검사 결과 합격품은 부품식별표를 부착하여 품명, 작업일자를 기록하여 품질보증팀장은 품질현황을 월1회 정기적으로 분석하여 대표이사의 결재를 득하고
지정된 장소로 이동시키고, 품질관리담당은 합격품에 대해서는 별도의 식별표시를 관련팀에 통보한다.
하지 않는다.
(2) 부적합품 10. 관련표준
작업자 및 품질관리담당은 부적합품이 합격품과 혼입되지 않도록 식별하고, 발생된 (1) 부적합품 처리규정 (B-3100)
부적합품은 부적합품 처리 절차에 따라 처리하여야 한다. (2) 사내자격관리규정 (F-2100)
(3) 시정조치 규정(B-2100)
5.4 완성품 검사 (4) 공정 및 제품감사 규정(A-5200)
5.4.1 품질관리담당은 고객과 검사협정시 설정된 ''검사기준서''에 따라 완성품 검사를 (5) 신뢰성 시험업무 규정(L-2200)
