페 이 지 2/3
1. 적용범위 책임(●) / 협조(→/←) 절 차 문서(●) / 기록(→/←)
이 규정은 당사의 중금속,인장 시험 등의 신뢰성 시험 업무에 대하여 적용한다.
2. 목적 (●) 품질보증팀장 신뢰성 시험 (●)검사규격 및 도면 (●)시험표준
각 제품별 요구되는 성능을 기준대로 평가하여 고객에게 성능을 보증하는데 목적이 있다.
3. 용어의 정의 (●) 품질보증팀장 시험결과 평가보고 (→)시험성적서
3.1 신뢰성 시험
목표기한동안 당사 제품이 지속적으로 성능유지가 되는가를 신뢰성 시험설비 및 ↓
공인된 기관 또는 고객이 인정한 업체등을 활용하여 확인하는 시험을 말한다. (●) 품질보증팀장 이상발생 보고 및 문제의 중요도 파악
3.2 비교 시험 ↓
동급의 유사한 타제품을 당사의 동일한 시험조건으로 확인하는 시험을 말한다. (●) 품질보증팀장 (→) 관련팀장 원인분석 및 조치', 0
WHERE NOT EXISTS (SELECT 1 FROM regulation_sections WHERE reg_code = 'L-2200' AND sort_order = 0);
