책임(●) / 협조(→/←) 절 차 문서(●) / 기록(→/←) ↓
(●) 품질보증팀장 기록 유지 (→)시험성적서
(●) 품질보증팀장 년간 시험계획 수립 (→)신뢰성 시험 계획서', 1
