SELECT 'L-2200', '5. 세부업무절차', '↓ 5.1 시험계획 수립
(●) 품질보증팀장 (←) 외부공인기관 개발품 시험계획 수립 및 시험의뢰 (→)시험의뢰서 (1) 양산품에 대하여 고객의 요구사항과 요구주기를 고려하여, 품질담당은 매년 말 신뢰성
시험계획을 작성하여 담당부서장의 승인을 받는다.
↓ (2) 개발품인 경우 고객의 요구 항목에 대해 개발일정 계획을 고려하여 자체 또는 외부
공인기관에 시험을 의뢰한다.
품질경영 시스템 문 서 번 호 TPC - L - 2200
재,개정 일자 45047
신뢰성 시험업무 규정 개 정 번 호 5
페 이 지 3/3
(3) 신뢰성 시험은 년 1회 이상 실시하는 것이 원칙이다. 단 고객과 협의된 주기가 우선이며, 5.5 기록의 보관
유사제품으로 기입증 된 경우 이로 대체할 수 있다. 품질담당은 시험성적서를 기록으로 보관한다.
5.2 신뢰성 시험 실시 6. 관련표준
(1) 품질담당은 일정계획에 따라서 시료를 채취 하거나 또는 해당 시료를 인계받아 로트번호, (1) 4M 변경관리 규정(J-3100)
제원 등을 확인하고 신뢰성 시험을 실시 한다.
(2) 시험/검사기준은 해당제품, 검사규격, 도면, 시험표준에 따르고 시험에 사용되는 시료는 7. 관련양식
시험항목별로 고객과 협의 시료수를 정하여 시험을 진행 한다. (1) 년 신뢰성 시험 계획서(L2200-01)
(3) 품질담당은 회사내에서 시험을 실시하지 못할 경우 외부기관(공인기관)에 의뢰를 하여야
하며, 외주품에 대한 시험은 외주업체에서 시험 (외부 공인기관 의뢰 포함)을 실시/의뢰 하는 8. 부표
것을 원칙으로 한다. (1) 부표1 시험장비 작동 기준서
단, 외주업체 성적서는 고객이 인정한 업체만 가능함
5.3 시험결과 평가보고
(1) 품질담당은 시험결과를 일정계획표에 기록하고 시험성적서/검사성적서를 발행하여
담당부서장에게 보고하며, 사본을 관련부서에 배포한다.
(2) 품질담당은 시험 완료된 제품은 지정된 보관장소에 보존 후 반기별로 폐기처분한다.
5.4 이상 발생처리
(1) 품질보증팀장은 시험결과 기준에 부적합한 경우 문제의 심각성 및 제품에의 영향
등을 파악한다.
(2) 품질보증팀장은 문제의 원인조사 및 발생시기를 소급, 추적하고 관련부서와 협의하여
처리방안을 수립하여 대표이사에게 보고한다.
필요시 고객에 통보하여 협의한다.
(3) 품질보증팀장은 부적합 현품의 처리를 실시하고 그 결과를 생산팀장에게 통보한다.
(4) 이상처리 실시 후 필요할 경우 『4M 변경관리 규정』에 의거하여 변경조치한다.', 2
WHERE NOT EXISTS (SELECT 1 FROM regulation_sections WHERE reg_code = 'L-2200' AND sort_order = 2);
