자재 또는 제품의 품질판정 기준을 나타내기 위해 준비한 가장 나쁜 상태의
견본을 말한다. ↓
(●) 품질보증팀장 (→) 해당팀장/ 협력업체 한도견본 등록, 비치 (→)한도견본 관리대장 (→)한도견본표
