INSERT INTO regulation_sections (reg_code, section_title, section_body, sort_order)
SELECT 'L-2300', '4. 관리절차 5. 세부절차', '한도견본 관리의 주관팀은 품질보증팀 이며, 업무 절차는 다음과 같다. 5.1 한도견본 필요 중요 품질특성 선정
(1) 사내에서의 한도견본 필요팀 또는 협력업체에서는 필요한 한도견본 특성을 선정
한다.
(2) 한도견본 설정시기는 공정설계시 PFMEA를 통하여 양산중에 크래임 발생 등으로 한도
견본이 필요하다고 판단되는 경우에 설정한다.
품질경영 시스템 문 서 번 호 TPC - L - 2300
재,개정 일자 45047
한도견본 관리 규정 개 정 번 호 5
페 이 지 3/4
(3) 협력업체의 경우에도 외주 개발시 또는 양산 입고중 필요하다고 판단되는 경우에 설정 5.4 견본의 개정
한다. (1) 품질관리담당은 견본의 유효기간을 1년으로하며, 만료 3~6일전에 견본을 개정한다.
(2) 견본을 개정하는 경우 새로 제작하는 것을 원칙으로 한다.
5.2 한도견본의 제작 및 승인 (3) 견본을 년 1회 개정하는 주체는 다음과 같다.
(1) 필요팀에서는 설정된 한도견본을 제작하고 품질보증팀장에게 승인을 득한다. ①공정내 자주검사 용도 한도 견본 : 생산팀
(2) 품질보증팀장은 생산팀장 또는 관련팀장과 협의하여 승인하고 “한도견본표"를 발행한다. ②수입검사 및 공정 페트롤 용도 한도 견본 : 품질팀
(3) 한도견본의 최종결정권자는 품질보증팀장이 된다. ③그외 한도 견본 : 상호 협의하에 관리 주체 지정
(4) 한도견본의 유형은 실제품을 이용 제작이 기본이나, 부득히한 경우 "한도검사 기준서"를 작성
대체 할 수 있다. 5.5 견본의 유지
(5) 한도 견본의 유효기간은 1년으로 하며, 만료 3~6일전에 한도 견본에 대하여 개정을 실시한다. 견본관리 담당자는 승인되지 않은 견본이 사용되지 않도록 해야 한다.
5.3 승인된 견본의 관리
(1) 품질관리담당은 승인된 한도견본을 “한도견본 관리대장”에 등록하고 “한도견본표”를
부착한다. 5.6 폐기
(2) 필요팀에서는 승인된 한도견본을 품질관리담당으로 부터 인수하여 해당 공정의 견본 (1) 필요팀은 공정의 폐기 또는 한도견본의 유효성 상실등의 사유 발생시 한도견본을
보관 장소에 게시하고 작업표준, 관리계획서 등 관련 기술표준에 내용을 기록한 후 품질관리담당에게 반납한다.
해당인원에게 사용방법 등을 교육시킨다. (2) 품질관리담당은 “한도견본 관리대장”에 폐기사유를 기록하여 품질보증팀장의
(주) 한도견본 관리번호 부여방법은 승인을 득하고 폐기조치한다.
① - ② ③ - ④ ⑤
①A: 표준견본 5.7 기록의 보관
B: 한도견본 품질관리담당은 한도견본 관리대장을 기록으로 보관한다.
C: 불량견본
②③ 차종(또는 모델) 약어(두자리)
④⑤ 일련번호(00 ~ 99)
(3) 품질관리담당은 견본의 승인일로부터 정기 개정주기를 계산하여 ‘한도견본표’에
유효기간을 표시한다.
