5.2 계측기 구입 의뢰 (7)(8) : 일련번호(01~99)
사용팀장은 필요한 계측기의 시방, 수량을 구매청구서에 기록하여 개발/품질관리
팀장에게 제출한다. 제작시에는 ''구매청구서''에 해당도면을 첨부하여 의뢰한다. 5.7 불출 및 사용
(1) 계측기 불출시에는 ''계측기관리대장'' 및 ''계측기 이력카드''에 사용담당 및 용도를
5.3 계측기 구매 또는 제작 기록하고 불출한다.
품질보증팀장은 구입 의뢰된 내용을 검토하고, 대표이사의 승인을 득한 후 (2) 계측기 사용담당은 계측기가 적절히 사용되어질 수 있도록 유지, 관리한다.
계측기를 구매하거나 제작한다.
5.8 정기 검·교정
5.4 계측기 검·교정 5.8.1 년간 교정검사 계획작성 및 승인 (모든 계측기 연 1회 / 매년 5월 실시)
(1) 품질보증팀장은 신규 구입 또는 제작된 계측기를 검·교정하며 성능의 이상 품질보증팀장은 교정검사 대상 계측기에 대하여 년간 교정검사 계획을 작성하여
유무를 확인한다. 대표이사의 승인을 받는다.
(2) 품질보증팀장은 구매품의 검·교정 결과 성능의 이상이 있으면 반품하며, (주) 검사용 계측기는 교정검사 대상이 되고, 기타의 계측기는 점검대상이 된다.
제작품에 이상이 있는 경우 재 작업한 후 검・교정을 실시한다. 5.8.2 교정검사 및 점검 실시
(1) 품질보증팀장은 년간 교정검사 계획에 근거, 교정검사 및 점검을 실시한다.
품질경영 시스템 문 서 번 호 TPC - L - 3100
재,개정 일자 45821
계측기 관리 규정 개 정 번 호 8
페 이 지 4/5
(2) 품질보증팀장은 사외 검교정 대상 계측기는 공인 교정기관에 교정검사 대상 5.8.6 검사 유효성 평가
계측기를 제출하여 검사를 의뢰하며, 교정검사 완료후 교정검사 성적서 및 필증을 교부 (1) 교정검사 결과 부적합 계측기가 있는 경우, 품질보증팀장은 해당 계측기로
받는다. (검교정 리스트 기준 누락 계측기 여부를 검교정 성적서 기준 비교 검토하여야 한다.) 측정한 검사항목이 제품에 미치는 영향과 부적합 발생시기 등을 조사하여 이전에 실시한
(3) 사내 자체 검교정을 실시하는 경우는 검정하고자 하는 계측기를 사용하여 계측기의 검사의 유효성 및 조치방안을 수립하여 대표이사의 승인으로 실행한다.
측정구간 범위를 등간격으로 4등분하여 각 구간별로 3회씩 측정한다. (2) 부적합 계측기 사용으로 인하여 기 출하된 제품의 품질에 의문이 있는 경우, 개발/
(4) 사내점검을 실시하는 경우는 게이지의 마모 및 파손상태에 대해 점검을 실시한다. 품질보증팀장은 상세내역을 문서화하여 고객에게 통보하고 협의결과에 따라 조치한다.
5.8.3 합부판정 (3) 품질보증팀장은 조사결과, 조치방안 및 결과에 대해 보고서를 작성하여 보고한다.
(1) 품질보증팀장은 사외 검교정검사 결과를 계측기 교정검사 표준에 의거, 계측기의 허용오차
범위(보정값, 측정불확도:부표1 참조)와 비교하여 적합성 검토 후 합부 판정을 실시한다. 5.9 분실/파손 통보
(2) 사내 자체 검정인 경우는 구간별 3회 반복하여 측정하고, 측정결과가 사외검교정 (1) 사용팀장은 사용 계측기가 분실/파손이 발생할 경우 품질보증팀장에게 분실신고
결과 합격인 계측기의 3회 반복 측정 결과와 비교하여 측정 정밀도 및 정확도가 5% 및 수리를 의뢰한다.
이내 일 경우 합격으로 한다. (2) 분실 계측기에 대하여 사용팀장은 즉시 대체 계측기를 구입하여야 한다.
(3) 품질보증팀장은 합부판정 결과를 "교정검사 성적서" 또는 "계측기 이력카드"에 기록하여 (3) 품질보증팀장은 필요시 대체 계측기 구입전까지 예비 계측기를 지원한다.
이력으로 관리한다.
5.8.4 합격 계측기 관리 5.10 수리, 폐기
(1) 외부 공인기관의 교정검사에서 합격한 계측기는 공인기관 발행의 스티커를 계측기에 (1) 품질보증팀장은 교정검사결과 부적합 계측기 또는 파손 신고 접수된 계측기 중
부착하여 관리한다. 수리가능한 계측기는 수리 및 검·교정을 실시하여 사용팀으로 반송하고, 수리 불가능시
(2) 사내 교정검사, 점검 및 측정시스템 평가 결과 합격한 계측기는 사내 교정 검사 필증 에는 폐기하고 사용팀에 통보한다.
스티커를 부착하여 관리한다. (2) 폐기 통보를 받은 사용팀장은 신규 구입한다.
(3) 품질보증팀장은 사내,외 교정검사가 완료된 계측기에 대하여 측정시스템 평가
대상 계측기에 대해서는 측정시스템 평가를 실시하고, 그 결과를 게이지 R&R Report에 5.11 일상점검
기록한다. (1) 품질보증팀장은 측정실 담당자에게 1회/일 계측기 이상 여부에 대하여 점검 후
5.8.5 부적합 계측기 관리 체크시트에 기록관리가 될수 있도록 관리한다.
(1) 유효기간의 경과, 교정검사 필증 스티커의 미 부착 및 교정검사 결과 부적합 판정된
계측기는 즉시 회수한다. 5.11 기록 유지
(2) 부적합 계측기는 수리 또는 교정한 다음 교정검사를 받아 합격 판정을 받은후 저등급 품질보증팀장은 "계측기 관리대장"과 "계측기 관리카드"를 기록관리 규정에 따라
으로 격하하여 사용한다. 보관, 관리한다.
