4.1 사업부장
3. 용어의 정의 년간 측정시스템 분석 계획 및 결과의 승인
3.1 GAGE R & R(게이지 반복성 및 재현성) 평가
측정장비의 측정체계 및 방법에 있어 정확성, 반복성, 재현성, 안정성, 선형성을 평가 분석하는 4.2 품질보증팀장
것을 말한다. 년간 측정시스템 분석 계획 수립 및 결과 보고
3.2 반복성 5. 업무 절차
동일한 측정자가 동일한 게이지로 동일 시료를 여러번 측정하였을때 얻어지는 측정값의 변동을 측정시스템 평가의 주관팀은 품질보증팀이며, 업무절차는 다음과 같다.
말한다.
책임(●) / 협조(→/←) 절 차 문서(●) / 기록(→/←)
3.3 재현성
동일한 시료를 동일한 게이지로 여러명의 측정자가 측정하였을때 측정자들 간의 측정평균치의
차이를 말한다. (●) 품질보증팀장 측정시스템 평가대상 선정 및 계획 (→) 측정시스템 분석 계획서
3.4 안정성 ↓
동일한 제품을 동일한 게이지로 환경변화에 의하여 일정시간, 기간이 지난 후 재측정하였을때 (●) 품질보증팀장 측정시스템 평가 준비 *시료,대상자
나타나는 측정치 평균값의 차이를 말한다.
3.5 선형성 (●) 품질보증팀장 (→) 대상자 측정시스템 평가실시 (→)게이지 R&R보고서 (계량,계수)
게이지의 정해진 작동 범위내에서 행하여진 측정 평균값의 차이를 말한다.
