개념에 관한 내용을 포함시킨다.
4.5 통계적 기법의 적용
(1) 모든 팀은 업무분석 또는 개선을 위하여 통계적 기법을 적극 활용하여야 한다.
(2) 예방조치를 위한 품질기록 분석시에는 통계적 기법을 사용하여야 한다.
(3) 품질보증팀장은 검사 결과에 대하여 모집단의 분포와 추이를 관찰하고 품질개선을
위한 자료로 활용한다.
(4) 공정 중 특별특성과 중요관리항목에 대하여 통계적 기법을 사용하여 공정의 안정성을
확보한다.
4.6 적용결과 확인 및 보완 / 갱신
(1) 품질보증팀장은 반기 단위로 각팀의 통계적 기법 적용 현황 및 결과를 확인하고
평가하여 다른 기법 사용의 필요성이나 추가 교육 필요성을 판단하고 이에 따른 조치
를 취한다.
(2) 품질보증팀장은 정기적으로 협력업체의 통계적 기법 적용결과를 접수하여 적용
결과를 확인 검토하고 지도/보완 필요사항을 추출하여 추진한다.
