5.1 초기유동 관리시의 공정능력 관리절차는 아래와 같다.
5.1.1 초도 생산
(●) 품질보증팀장 초도품 품질 승인 (●) 양산부품 승인업무규정 (1) 생산관리팀장 주관하에 양산조건의 설비 및 금형, 표준류를 모두 갖추고 초도 생산을
실시한다.
(2) 초도 생산수량은 연속성 있는 300개 이상으로 한다.
4.2 양산시 공정능력 평가 절차는 아래와 같다. (3) 초도양산시 발생된 문제점은 즉시 개선조치하여야 한다.
책임(●) / 협조(→/←) 절 차 문서(●) / 기록(→/←) (4) 문제의 개선이 오랜시간 필요하면 일정을 연기한다.
(5) 필요한 관련팀은 초도생산시 입회하며, 관련팀의 선정은 생산팀장이 한다.
5.1.2 샘플링
(●) 사용팀장 양 산 (1) 품질보증팀장은 연속생산된 300개 이상의 로트에서 무작위로 100개를 샘플링한다.
(2) 시료 채취시 초도생산과 관련없는 타제품의 혼입에 주의해야 한다.
↓ 5.1.3 측정, 기록
(●) 품질보증팀장 검사 시행 (●) 검사업무규정 (●) 공정관리 규정 (1) 품질보증팀장은 샘플링된 시료를 측정하여 생산된 상태로의 데이터를 확보한다.
(2) 측정된 데이터를 검사성적서에 기록하며 검사규격과 대조하여 합부판정을 실시한다
↓ 5.1.4 공정능력 평가
(●) 품질보증팀장 공정능력 평가 (1) 품질보증팀장은 측정된 데이터를 PC를 이용하여 예비공정능력 지수 및 히스토그램
을 산출한다.
↓ (2) 예비 공정능력 산출은 6.1항에 따른다.
(●) 품질보증팀장 추이관리 및 보고 (→) 월업무 보고 자료 (3) 품질보증팀장은 예비공정능력 평가 결과 관련팀장과 협의하여 초도품 품질승인을
결정 또는 개선계획을 수립하여야 한다.
↓ 판단기준은 다음과 같으나 고객의 요구 사항에 따른다.
(●) 품질보증팀장 개선 활동 (●) 시정조치 규정 (●) 지속적 개선규정 가. Ppk > 1.67 : 생산 진행
나. 1.33 ≤ Ppk ≤ 1.67 : 주의 관찰하면서 생산 진행, 필요시 개선 추진
↓ 다. Ppk < 1.33 : 개선 추진
(●) 품질보증팀장 유지관리 및 공정 검토 (4) 개선방안은 규격완화 가능성 검토, 설비 또는 금형의 개선, 작업방법 개선,
원재료 개선 등이 포함되도록 한다.
