5.1.5 기록 및 보관 6.1 예비 공정 능력
품질보증팀장은 예비 공정능력 평가표를 기록으로 보관한다. 6.1.1 적용
(1) 신제품 양산 평가
5.2 초기유동관리 해제 후 (주) 신제품이라 함은 최초 생산품, 공정변경 생산품, 설계변경 생산품 등
5.2.1 양산 및 검사시행 고객으로 부터 초도품 승인을 요구받은 제품을 원칙으로 하며 내부 필요에
(1) 작업자는 월간, 주간 생산계획에 의거 양산을 실시하고 자주검사를 시행한다. 따라 추가 할수도 있다.
(2) 품질보증팀장은 특별특성 및 중요항목에 대해 검사한 데이터를 접수하여 Xbar-R (2) 만성적으로 불안정한 공정
관리도에 기록한다. (3) 설비 능력 평가시
5.2.2 공정능력의 평가 6.1.2 데이터 수집
(1) 품질보증팀장은 1개월간의 검사기록으로서 “공정능력 평가표”를 산출한다. (1) 초도 양산품인 경우 300개 이상의 제품에서 100개의 데이터를 수집한다.
(2) 공정능력 평가 산출결과를 공정능력 추이관리 그래프에 기록한다. 단, 데이터는 동일 로트에서 수집되어야 한다.
공정능력 산출은 8.2항에 따른다. (2) 초도양산 이후 공정의 안정성 평가시는 30일 생산 이내의 생산분에 대하여 n=100개
(3) 품질보증팀장은 업무회의시 공정능력의 추이 및 공정능력표를 관련팀에 이상의 데이터를 수집한다. 단, 동일 로트에서 수집되어야 하는 시료수는 최소 n=5
배포하고 사후조치에 대한 협의를 한다. 공정능력 부족시의 조치는 후공정에서의 이상으로 한다.
전수검사 실시여부 및 해당항목의 중요도를 감안하여 품질보증팀장이 시정조치, 6.1.3 예비 공정능력 산출
선별 등 필요조치 방안을 결정한다. (1) 수집된 데이터는 PC를 활용하여 예비 공정능력 지수(Pp & Ppk)와 히스토그램을
(주) 만성적인 불안정 공정에 대하여는 예비 공정능력 분석을 실시하여 개선점을 산출한다.
찾는다. Pp : 치우침을 고려하지 않고 산포만을 고려한 예비 공정능력 지수
(4) 공정능력지수의 결과는 해당월 품질월보에 기재한다. Ppk : 치우침과 산포를 함께 고려한 예비 공정능력 지수
5.2.3 사후관리 (2) 수계산에 의한 산출방법
(1) 생산팀장은 공정능력 평가 결과 공정능력이 충분하다고 판단되면 관련팀과 협의 ● 총 공정 표준 편차 T :규격의 폭
하여 관리의 간소화등 코스트 절감방안을 수립한다. TL :규격의 하한값
(2) 생산팀장은 공정능력이 불충분할 경우 시정조치 또는 예방조치 등의 개선활동을 ・σs = TU :규격의 상한값
추진한다. M :규격의 중간 값
5.2.4 기록 및 보관 x :평균치
품질보증팀장은 공정능력 평가표 및 품질월보를 기록으로 보관한다. σs:총공정 표준편차
