● 양측 규격인 경우 (2) 히스토그램의 해석
산출된 히스토그램은 하기에 의거하여 해석한다.
・Pp = 명 칭 형 상 조 치
낙 도 히스토그램 그래프 옆이 섬모양 그 테이터의 원인을 조사하고 필요시
・Ppk=(1 - K)Pp 으로 동떨어진 그래프 발생 해당 테이터를 제거하고 재산출한다.
이빠짐 히스토그램이 종 모양을 하지 않고 계급의 폭이 적당치 않거나 측정치가
K= 중간 중간 이가 빠진 모양 테이터를 읽는데 특정한 버릇 확인
낭떠러지 히스토그램의 항목이 급경사를 한쪽으로의 제한조건이 있거나 측정
● 편측 규격인 경우 ( 상한 또는 하한값만 규제) 이루거나 절벽인 경우 에 이상이 있는가 확인
・Pp = 6.2 공정 능력
6.2.1 적용
・상한값 또는 하한값만 규제하는 경우에는 Pp만을 산출한다. 공정이 안정된 초기유동관리 해제 이후 제품의 일상검사 기록의 평가
6.1.4 예비 공정능력 평가 6.2.2 데이터 수집
(1) 공정능력 지수해석 (1) Xbar -R 관리도 또는 체크리스트에서 데이터를 수집한다.
산출된 예비 공정능력 지수값을 하기에 의거하여 평가한다. (2) 데이터의 수는 최소 n=30 이상이어야 한다.
