페 이 지 4/4
4.7.3 생산실적 관리 5. 관련표준
생산팀장은 작업일보의 생산량을 근거로 전체 작업실적을 요약 정리하여 ''생산일보''로 (1) 공정 관리 규정 (M-2100)
사업부장에게 보고하고, 품목별 생산계획대 실적을 ''생산관리 대장''에 기록하여 (2) 양산주문접수 및 납품관리 규정 (H-2100)
매월 실적을 분석한다.
4.7.4 생산 저하 요인 체크 및 해결 6. 관련양식
(1) 생산팀장은 생산 실적 저하 요인 발생시 작업현황, 인원현황, 설비문제점 등을 검토 (1) 월 생산계획서 (M1100-01) - 전산기록관리 참조
하여 문제점 발견시 해당 반장과 비가동요인을 파악하여 대책을 수립하고 그 내용을 (2) 설비 비가동시간 관리대장 (M1100-02)
''생산 이상처리 보고서''에 기록하여 사업부장의 결재를 득한다. (3) 설비 비가동시간 이력관리대장 (M1100-03)
(2) 사업부장은 ''생산 이상처리 보고서''의 내용을 확인 후 적절성 여부를 판단하고 조치한다. (4) 공정별 인원 현황 (M1100-04) - 조직도 참조
(3) 조치된 사항은 지속적으로 관리되어야 하며 효과파악을 실시한다. (5) 설비 비가동 주요 코드 (M1100-05)
(6) 우발사고 및 이상발생 처리 절차서 (M1100-06)
4.7.5 생산 계획 변경 여부 체크 및 조치
생산팀장은 생산 계획 대비 실적 저조 사항이 발생되면 생산계획 변경 필요 여부를
체크하고 필요하다고 판단되면 고객과 협의하여 관련팀과의 합의에 따라 생산일정을
변경한다.
4.7.6 실적평가
(1) 생산팀장은 매월 업무 보고를 통하여 생산실적을 대표이사에게 보고하고 관련팀에
배포한다.
(2) 매월 생산실적을 집계 결과 계획대비 -20% 이상의 차이가 발생할시 원인분석 및 대책
을 수립하며 차기 계획에 반영한다.
4.8 생산계획변경
생산팀장은 영업팀장으로부터 납기 및 계획의 변경 요구가 있을시 변경내용을 접수
하고, 월간 계획의 변경인 경우는 수정 생산계획을 작성하여 관련팀장에게 통보하고,
일일 변경사항은 작업지시서로 작업지시를 한다.', 3
WHERE NOT EXISTS (SELECT 1 FROM regulation_sections WHERE reg_code = 'M-1100' AND sort_order = 3);
