4.2 작업 지시 (2) 설비 점검시 설비에 이상이 있을시는 작업자는 설비 점검표에 기록하고 설비이상 내용을
(1) 생산팀장은 ''작업지시서''로 현장반장에게 당일 생산계획을 통보한다. 생산팀장에게 보고한다..
(2) 생산현장관리자는 품목 및 수량을 개인별로 작업 지시하고 품질문제, 안전수칙 준수사항, 4.4 이상발생시 조치
특이사항 등을 교육 및 지시한다. (1) 작업자는 설비 이상 발생시 생산팀장에게 보고하고 생산팀장은 설비이상을 접수하면
『설비관리규정』의 절차에 따라 생산기술팀에 설비수리를 의뢰한다.
4.3 작업준비 및 초품 검사 (2) 생산관리자는 설비 이상 발생 조치가 완료 될시, 셋팅 조건을 재 점검, 전작업 최종품과
4.3.1 작업준비 비교 문제가 없다고 판단될시, 초품에 대하여 품질보증팀에 측정을 요청하여야 하며,
(1) 생산팀장은 작업현장을 작업환경에 적합하도록 정리정돈 상태를 유지하여야 하며, 품질보증팀에서 최종 합격 승인이 나기전에는 제품을 생산하였어는 않된다.
『3정 5S 활동 규정』에 따라 정리정돈 상태를 점검하고 부적합 사항 발생시 →비가동품에 대한 업무 처리 기준은 부표1 "설비 재가동시 절차"를 참조 한다.
『시정조치 운영 규정』의 절차에 따라 시정조치되도록 한다. →품질보증팀은 측정 결과를 사업부장에게 결재 승인을 받은 후 "문서 및 자료관리 규정" 내
(2) 해당 팀장은 유틸리티 중단, 인력부족, 주요장비 고장 및 필드반송과 같은 리스크에 보존 기간을 준수하여 보관한다.(※측정 성적서 내 필히 판정 기준을 명시할것)
대응하기 위한 ''비상사태 대비계획''을 수립하여야 한다. →생산팀은 공정 자주검사 체크시트 내 비가동 후 첫 생산품인 초품에 대하여 식별하고
(3) 작업자는 작업중 발생한 설비, 품질, 안전, 자재, 기타 이슈 사항에 대하여 "주/야 이슈사항 품질보증팀 측정값을 기록한다.
인수인계 일지"를 작성하여 교대조에 정보를 전달하여야 한다. (3) 초품 검사시 제품 특성 및 규격에 벗어날 때에는 즉시 팀장에게 보고후 조치를 받는다.
"주/야 이슈사항 인수인계 일지" 를 받은 교대조에서는 이슈사항에 대하여 필히 점검, 문제 (4) 생산팀장은 초품이 규격에 벗어나거나 제품 특성이 맞지 않을 때는 적절한 조치를 취하며
없음을 확인 후 작업 준비를 마쳐야 한다. 자체적으로 해결 불가능할때는 사업부장에게 보고한다.
(4) 생산팀장은 교대조간 정보 전달을 위한 "주/야 이슈사항 인수인계 일지"에 대하여 매일 시업전 (5) 사업부장은 관련팀의 협조를 구하며 정비 또는 수정에 있어서 장시간 소요될 시는
작성 및 교대조간 정보 전달에 문제가 없는지 확인 하여야하며, "주/야 이슈사항 인수인계 일지" 영업팀장과 협의하여 생산계획을 변경한다.
작성이 되지 않은 상태 정보가 전달되는것이 확인 되었을시 필히 문제를 제기하고 조치하여야
한다. 4.5 생산
(1) 작업자는 초품검사결과 이상이 없다고 품질보증팀에서 통보를 받으면 생산을 시작한다.
4.3.2 초품검사 (2) 각 공정의 작업자는 "식별 및 추적성 관리 규정"에 따라 비가동 전,후품에 대하여 식별 및
(1) 생산작업자는 지시 받은 생산활동을 위하여 비정상적인 생산가동 중단, 비상사태 다음 LOT 관리를 하여야 한다.
생산 재시작 후, 지그교체, 자재교체, 작업변경, 작업 첫가동후 설비점검 및 초품에 대하여 (3) 작업자는 생산중 지그교체 등 SET UP시에는 준비교체표준에 따라 SET UP을 실시하며
작업표준에 기재된 사항을 확인하여 ''설비일상 점검표'' 및 ''자주검사 CHECK SHEET''에 기록한다. SET UP전의 품질과 SET UP후의 품질의 동질성을 비교하며 특별 특성으로 지정된 항목
(주) 초품이라 함은 공정별 주간작업 및 교대 작업시 최초 생산된 제품을 말하며 은 통계적 기법을 통해 관리하며 그 이외의 항목은 자주검사CHECK SHEET에 기록한다.
SET UP 후의 제품도 포함한다.
