(4) SET UP후의 제품이 SET UP전의 제품과 상이할 때는 작업자는 팀장에게 보고하며 팀장 4.8 실적관리 및 완성품 보관장소 입고
은 4.6의 (2)항과 같이 처리한다. (1) 생산팀장은 익일 아침 출근 후 전일 작업한 작업일보를 확인하여 사업부장에게 보고한다.
(5) 생산기술팀장은 이전까지의 경험과 업무회의 결과, 수리내역 등을 참고로 하여 예방보전 (2) 생산팀장은 작업일보를 취합하여 일일 생산 계획 대비 실적을 관리한다.
계획/실시하며, 그 세부절차는 "설비관리 규정"에 따라 처리한다. (3) 영업팀장은 입고 조치된 제품을 『완성품 관리 규정』에 따라 관리한다.
