3.2 생산팀장 (1) 생산담당은 작업이 완료된 완제품에 대해서는 완성품 창고로 이송, 보관한다.
(1) 제품을 출하되기 전까지 제품별 또는 로트별로 식별수단을 유지, 관리할 책임이 있다 (2) 영업담당은 고객의 출하 요청시 고객의 요구에 따른 식별표를 부착하여 출하하여야 한다
(2) 외주가공품, 공정제품 및 최종제품에 대하여 식별표시 할 책임이 있다. 4.1.4 특채품 식별
3.3 구매팀장 : 원소재 및 부자재에 대하여 검사 대기전까지 식별표시 할 책임이 있다. 품질보증팀장의 승인을 득한 특채품은 해당 식별표에 ''특채'' 표시를 한후 식별관리한다.
3.4 영업팀장 : 완성품에 대하여 출고 후 식별표시 할 책임이 있다. 4.1.5 시작품 식별
