SELECT 'M-3100', '3. 업무절차 4.1 제품 입고', '완제품 관리의 주관팀은 생산팀이 되며 업무 프로세스는 다음과 같다. 생산팀장은 생산된 제품에 대하여 “생산 관리대장”에 수량을 기록한다.
책임(●) / 협조(→/←) 절 차 문서(●) / 기록(→/←)
4.2 제품적재
생산팀장은 제품별로 『식별 및 추적성관리규정』에 따라 식별하고 입고순으로 배치
(●) 생산팀장 제품 입고 (→) 생산관리대장 하여 선입, 선출이 가능하도록 한다.
↓ 4.3 출하요청
(●) 생산팀장 제품 적재 *적재관리 기준 (1) 영업담당 및 수출담당은 고객으로부터 납품에 대한 정보를 접수받고 선적계획
또는 출고 일정을 생산팀에 통보한다.
↓ (2) 생산팀장은 『양산주문접수 및 납품관리 규정』에 따라 출하준비를 한다.
(●) 생산팀장 (←) 영업팀장 제품 출고 요청 (←) 고객발주서
4.4 차량 배차 및 제품상차
↓ (1) 영업담당은 일정계획에 따라 차량을 수배하여 배차하고 출고지시서 또는 PACKING LIST에
(●) 영업팀장 차량배치 및 제품상차 (→) 납입지시서 따른 상차여부 및 식별표 부착여부등을 최종확인한다.
(2) 제품을 취급, 운반할 때는 지정된 인원에 의해서만 취급 관리될수 있도록 한다.
(●) 영업팀장 수불 정리 (→) 제품관리대장 4.5 수불정리
