4.6 월말재고 실사 7. 관련양식
(1) 생산팀장은 월말 마감후 익일 근무 시작 전에 재고조사를 하여 사업부장 결재를 득한다. (1) 장기재고 관리 현황 (K2100-01)
(2) 생산팀장은 매월초에 전월의 매출환입등의 내역을 확인하고 현재고현황과 실사수량 (2) 재고조사표 (K2100-04)
과의 차이를 대조한후, “재고조사서에” 기록하여 그 내역을 사업부장의 결재를 한다. (3) 장기 재고 점검대장 (K2100-05)
(3) 생산팀장은 보관중인 제품에 대해 자재관리규정 내 장기재고 점검대장 기준에 따라 점검하고 (4) 출하관리대장 (M3100-01)
점검 결과를 "재고 조사표에"에 기록한다. 6개월 이상 사용하지 않는 장기 보관품은
다음의 처리 방법에 따라 처리한다. 부표1. 보관상태 점검기준
가. 생산팀장은 장기보관품에 대해 해당 관련담당과 출하가능 여부와 시기를 확인한다.
나. 생산팀장은 사용불가능한 물품은 관련부서로부터 사유서를 첨부하여 폐기품의서를 NO 점 검 항 목
작성, 대표이사의 승인을 득하며 사용예정인 경우에는 품질관리부서에 사용여부에 1 장기 보관 제품의 식별 상태는 양호한가?
관한 검사를 의뢰한다. 2 보관 제품의 선입선출이 잘 이루어 지고 있는가?
다. 품질보증팀장은 해당물품의 외관검사 및 열화를 확인하기 위한 검사를 실시하고, 3 보관제품의 포장이 파손되거나 제품 손상 및 녹 발생은 없는가?
그 결과 이상이 없으면 구두로, 부적합품 발견시는 “부적합보고서”로 제품담당 4 제품이 지정된 장소에 보관하고 있는가?
에게 통보한다. 5 장기 보관품 LOT관리,사양구분은 이루어 지고 있는가?
(주) 열화 확인을 위한 검사는 해당자재 또는 제품검사규격을 준용한다. 6 A/S 예정품, B/OUT 품의 처리는 적절히 이루어 지고 있는가?
라. 검사결과 불량인 경우 제품담당은 폐기를 추진하며, 양품인경우 장기 적체품 라벨 7 제품은 규정용기에 적재되어 있는가?
을 부착하여 관리한다. 8 제품의 보관 위치가 다른곳에 보관되고 있지는 않는가?
마. 불용 또는 불량 판정되어 폐기승인된 장기 적체품을 폐기/매각/재활용 처리한다. 9 불량 반송된 제품은 불량 TAG 부착후 Q,C에 인수인계를 잘하고 있는가?
바. 생산팀장은 폐기/매각/재활용 처리 후 관련 증빙자료를 경리담당에게 송부한다. 10 제품의 보관 및 관련된 업무를 효율적으로 이행되는가?', 3
