SELECT 'M-4100', '3. 용어의 뜻 4.1 공장장', '3.1 작업 환경 (1) 추진위원장으로서 위원회를 운영 총괄한다.
생산현장,사무실,창고등 해당 공정에서 온도,습도,조도,진동,소음,분진등의 공기 청정도등을 (2) 전사적 3정 5행이 시행될 수 있도록 추진 및 사후관리 확인에 대한 책임이 있다.
만족스럽게 수행하기 위한 환경 조건을 말한다. (3) 전사적 3정 5행의 기획,조정,통제부분의 입안지시 및 시행을 할 수 있는 권한이 있다.
3.2 정리 4.2 간 사 (경영관리실 총무팀장)
필요한 것과 필요없는 것을 구분하여 작업장에는 필요한것이외에는 일체 두지 않는것을 말한다. (1) 전사 3정 5행의 추진방침과 세부 활동 계획을 수립할 책임이 있다.
(2) 추진활동 종합평가 및 시상 품의를 할 권한이 있다.
3.3 정돈 (3) 추진활동 문제점에 대하여 심의 조정할 책임이 있다.
필요한 것을 누구나 바로 꺼내어 쓸수 있는 상태로 하는것을 말한다. (4) 추진교육 및 지도의 책임이 있다.
3.4 청소 4.3 위 원 (각 사업부장)
버릴것을 버리고 사용가능한것은 잘 정돈하여 더럽혀짐이 없는 상태로 하는것을 말한다. (1) 3정 5행의 자주적인 전개와 점검을 실시할 책임이 있다.
(2) 3정 5행 활동시 발견된 문제점은 제안등을 통해 개선 할 수 있도록 유도할 책임이있다.
3.5 청결 (3) 사업부내의 3정 5행 활동의 감독 및 자주적 개선을 지시 확인할 책임이 있다.
정리,정돈,청소를 철저하게 하여 주변 환경을 깨끗이 하는것을 말한다.
