SELECT 'M-4100', '5. 운영 절차 6.3 실행', '3정5S 운영의 주관팀은 관리팀이 되며, 그 절차는 다음과 같다. 6.3.1 정리
(1) 활동구역별 해당 사업부장은 관리대상 물품을 List-Up하여 설정한다.
책임(●) / 협조(→/←) 절 차 문서(●) / 기록(→/←) (2) 해당팀장은 불요/불용품 분류기준을 설정하고, 업무 수행중 또는 청소시 불요/불용품을
식별하여 지정된 장소에 적재한다.
(3) 정리로 인하여 배출된 불요/불용품에 대하여 책임추궁하지 않을 것을 기본으로 한다.
(●) 경영관리 총무팀장 활동구역 작성 및 준비 (→) 3정5S 팀별 활동구역 (4) 경영관리 총무팀장은 적재된 불요/불용품 처리 방안을 설정하고 품의서를 작성하여
공장장과 대표이사의 검토, 승인을 득한다.
↓ (5) 경영관리 총무팀장은 승인된 처리방안에 따라 대상물품을 처리한다.
(●) 각 사업부장 실행(정리, 정돈, 청소, 관리)
6.3.2 정돈
↓ (1) 각 팀장은 관리해야 할 물품이 정량/정위치/정품으로 관리될 수 있도록 다음사항을
(●) 경영관리 총무팀장 진단 평가 (→) 3정5S 진단 시트 (사무실 및 현장용) 고려하여 방법을 설정한다.
가. 장소 / 품목/ 보관수량
↓ 나. 식별표기 : 명칭 / 수량 / 구분
(●) 경영관리 총무팀장 (→) 위원장 결과 처리 (→) 3정5S 활동 평가 보고서 * 포 상 (부표 2 참조) 다. 적치 방법
라. 현장게시 관리방법
↓ (2) 각 팀에서는 정해진 관리방법에 따라 정돈을 실시하고, 해당팀장은 매월 정돈상태를 확인한다.
(●) 각 사업부장 시정 조치 (→) 3정5S 평가지적 및 시정조치
6.3.3 청소
(1) 경영관리 총무팀장은 팀별 담당구역을 정하고 청소구역도를 작성한 후 식별가능한 곳에', 4
