6.2 활동구역 작성 및 준비 나. 청소시 해당되는 설비는 점검을 병행한다.
경영관리 총무팀장은 팀별 활동구역을 작성하여 지정한다. (3) 일상적인 청소는 작업전·후 담당구역을 청소하여 관리한다.
