SELECT 'M-4200', '1. 적용범위 5. 운영 절차', '이 규정은 회사에서 내 전공정에 대하여 적용한다. 조도관리 운영의 주관팀은 각 사업부 품질보증팀이 되며, 그 절차는 다음과 같다.
2. 목적 책임(●) / 협조(→/←) 절 차 문서(●) / 기록(→/←)
각 공정 별 조도(Lux)의 기준을 정해 제품에 대한 육안 검사가 보다 명확하고 효과적으로 진행
되기 위한 기준 수립 및 조도(Lux)의 관리를 명확하게 진행함에 그 목적 이다.
(●) 각 사업부 품질보증팀장 점검구역, 측정 포인트 기준 수립 (→) 조도 측정 구역', 1
