INSERT INTO regulation_sections (reg_code, section_title, section_body, sort_order)
SELECT 'M-4200', '4. 책임과 권한', '4.1 각 구역별 팀장 ↓
(1) 조도 측정의 각 구역 별 팀장은 공정 내 설치된 조명이 점등 불가 등의 정상 작동이 되지 않을시 (●) 각 사업부 품질보증팀장 결과 처리 (→) 시정 조치 요구서
즉시 생산기술팀에 수리 의뢰를 할 의무가 있다.
(2) 문제 발생시 품질팀장에게 보고할 의무가 있다. ↓
(●) 생산기술 팀장 시정 조치 (→) 완료 보고서
4.2 품질보증팀 조도 측정자
품질보증팀 조도 측정 담당자는 부표 1 "조도 측정 기준"을 참조하여 Lux를 측정할 의무가 있다.', 3
WHERE NOT EXISTS (SELECT 1 FROM regulation_sections WHERE reg_code = 'M-4200' AND sort_order = 3);
INSERT INTO regulation_sections (reg_code, section_title, section_body, sort_order)
SELECT 'M-4200', '6. 세부 절차', '4.3 생산기술팀 팀장 6.1 점검구역, 측정 포인트 기준 수립
(1) 조도에 이상이 생긴 부분이 접수될시 즉시 수리 조치를 할 의무가 있다. 품질보증팀 팀장은 조도측정 구역, 측정 포인트에 대한 기준을 수립한다.
(2) 수리 완료된 부분은 품질 팀장에게 보고할 의무가 있다
6.2 관리
4.4 품질보증팀 팀장 각 생산팀장은 성사 공정 확인시 조명등의 이상 발생에 대하여 관리 하여야 한다.
현장에서 발생된 조도 문제에 대한 생산기술팀의 수리 조치 결과를 확인하고, 조도 측정 위치를
지정하고, 품질팀에서 진행하는 조도 측정이 명확하게 진행 되고 있는지 모니터링 할 의무가 있다.
