6.3 진단평가 부표 1 조도 측정 기준
(1) 품질팀 조도측정 담당자는 1회/월 측정을 하여야 하며, 일몰 이후 시간 측정을 하여야한다 (1) Lux의 기준은 국가기술표준원의 KSA 3011:1998(2018) 표준서를 확인한 결과로 지정한다.
(2) 조도 측정 관리대장에 명기되어진‘작업장 조도 측정 위치도’를 확인하여 해당 구역 (2)표준 조도 및 조도범위는 <인용1. KSA 3011 표준 조도 및 조도범위> 표를 참조 하여 편의
으로 이동 한다. 상 <표1. KSA3011 표준 조도 및 조도 범위 정리표>로 정리 하였다.
(3) "조도 측정 기준서"를 참조 조도를 측정 한다
(4) "조도 측정 체크시트" 에 실측값 수기 기록 및 측정자/측정시간을 필히 기록하여야 한다.
(5) 해당 결과를 품질팀장에게 보고 한다.
6.4 결과처리
(1)품질보증팀 팀장은 측정 결과에 대하여 시정조치 사항 발생시, 업무 협조전을 이용 생산기술팀
팀장에게 시정 조치를 요청한다.
(2) 생산기술팀 팀장은 접수된 시정조치 요구서에 대하여 즉시 수리를 진행하여야 한다.
(3) 품질보증팀 담당자는 시정 조치사항 및 측정결과에 대하여 최종 품질보증팀 팀장에게 승인
받은 후 그 이력을 보관하여야 한다.', 4
